('7fc3db439b57', 'quesadillas poulet, épinards et mozzarella', null, 'hiver', 'janvier', 1, 1, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 GRANDE', null, null, '/assets/recipe_images/pexels/quesadillas-poulet-epinards-et-mozzarella.jpg', '[{"name": "3 œufs", "canonical": true}, {"name": "1 tortilla de maïs", "canonical": true}, {"name": "2 tranches de blanc de poulet", "canonical": true}, {"name": "½ mozzarella (CONSERVER L’AUTRE MOITIÉ AU FRAIS POUR VENDREDI)", "canonical": true}, {"name": "1 poignée d’épinards crus (OU UNE PETITE BOÎTE D’ÉPINARDS EN CONSERVE)", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "3 c. à s. de sauce tomate", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer les épinards.", "Dans un bol, battre les œufs. Saler\net poivrer.", "Dans une poêle chaude huilée,\nfaire cuire", "Ajouter la tortilla de maïs par-\ndessus. Retourner la tortilla dans\nla poêle.", "Toujours dans la poêle, ajouter\nla sauce tomate, le blanc de poulet,\nles épinards, la mozzarella et les\nherbes de Provence. Laisser cuire\nquelques minutes. Le fromage doit\ndevenir fondant.", "Replier les bords de la tortilla pour\nformer la quesadilla et couper en\ntriangle.\nLe blanc de poulet\nsans nitrites est à privilégier."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f85e95a0b4c2', 'blanquette végétarienne', null, 'hiver', 'janvier', 1, 1, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/blanquette-vegetarienne.jpg', '[{"name": "1 boîte de conserve de haricots blancs", "canonical": true}, {"name": "3 carottes", "canonical": true}, {"name": "1 barquette de champignons de Paris frais", "canonical": true}, {"name": "1 poireau", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à s. de crème de soja", "canonical": true}, {"name": "1 citron", "canonical": true}, {"name": "1 c. à s. de farine de blé", "canonical": true}, {"name": "1 c. à s. de cumin (EN OPTION)", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "8 c. à s. de riz", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Préparer un roux : mélanger la farine\navec de l’eau dans un bol.", "Éplucher et couper en dés l’oignon,\nle poireau, les carottes et les\nchampignons. Les faire cuire dans\nune poêle huilée pendant 5 min.\nAjouter un peu d’eau et laisser\nmijoter pendant 25 min. Extraire\nun peu du jus de cuisson des\nlégumes et laisser de côté.", "Mélanger le roux aux légumes.", "Casser l’œuf et séparer le jaune\ndu blanc dans 2 bols différents.", "Presser le jus de citron.", "Dans un saladier, ajouter la crème\nde soja, le jus de citron, le jaune\nd’œuf et le bouillon de légumes.\nMélanger cette préparation aux\nlégumes. Saler, poivrer et ajouter le\ncumin.", "Égoutter les haricots blancs\net les ajouter à la préparation.", "Dans une casserole d’eau bouillante\nsalée, faire cuire"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1d8ef8893860', 'tartinades de sardines et bâtonnets de carotte sauce fromage blanc', null, 'hiver', 'janvier', 1, 1, 'mercredi', 'apéritif/entrée', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tartinades-de-sardines-et-batonnets-de-carotte-sauce-fromage-blanc.jpg', '[{"name": "1 petite boîte de conserve de sardines", "canonical": true}, {"name": "1 citron", "canonical": true}, {"name": "2 tranches de pain complet ou de campagne", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 fromage blanc", "canonical": true}, {"name": "1 c. à s. de ciboulette fraîche (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Faire toaster les tranches\nde pain dans un grille-pain ou\ndans une poêle avec du beurre.", "Déposer les sardines sur les\ntranches de pain. Presser le jus\ndu citron et mettre la moitié\ndu jus sur les sardines.", "Laver, éplucher et couper\nla carotte en bâtonnets.", "Dans un bol, mélanger\nle fromage blanc, le reste du\njus de citron et la ciboulette.\nPoivrer.", "Tremper les bâtonnets\nde carotte dans la sauce.\nDéguster avec les tartines\nde sardines.\ntartinades de\nsardines et bâtonnets\nde carotte sauce\nfromage blanc\nTu peux également\nréaliser des bâtonnets de radis noir\nou de chou-fleur cru."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('06ba0d5861d8', 'flan au poireau au micro-ondes', null, 'hiver', 'janvier', 1, 1, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/flan-au-poireau-au-micro-ondes.jpg', '[{"name": "1 petit poireau", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "5 c. à s. de crème de soja", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper le poireau\nen rondelles.", "Dans une casserole chaude\nhuilée, faire cuire", "Pendant la cuisson, préparer\nle flan dans un grand bol :\nbattre les œufs avec la crème\nde soja. Saler, poivrer et ajouter\nle curry.", "Lorsque le poireau est\ncuit, l’égoutter et l’ajouter\nà la préparation. Mélanger.", "Verser la préparation dans un\nplat beurré (compatible au\nmicro-ondes).", "Cuire au micro-ondes\npendant 5 à 6 min. Vérifier"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c42be2391dd7', 'pancakes salés épinards et mozzarella', null, 'hiver', 'janvier', 1, 1, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pancakes-sales-epinards-et-mozzarella.jpg', '[{"name": "1 poignée d’épinards frais (OU UNE PETITE BOÎTE DE CONSERVE)", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "3 c. à s. de farine de blé", "canonical": true}, {"name": "4 à 5 tranches de mozzarella (LA MOITIÉ DE LA RECETTE DE LUNDI)", "canonical": true}, {"name": "Un petit verre de lait", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer les épinards et enlever\néventuellement les tiges dures.\nCouper les feuilles en morceaux.", "Couper la mozzarella en dés.", "Dans un saladier, faire la pâte\nà pancake : mélanger l’œuf,\nla farine, le lait et la levure. Saler\net poivrer. Ajouter les épinards\net la mozzarella.", "Dans une poêle chaude huilée,\nà l’aide d’une cuillère à soupe,\ndéposer"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('d0c8ab48c209', 'curry de poireau', null, 'hiver', 'janvier', 1, 2, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/curry-de-poireau.jpg', '[{"name": "1 oignon", "canonical": true}, {"name": "1 poireau", "canonical": true}, {"name": "2 pommes de terre", "canonical": true}, {"name": "10 c. à s. de riz blanc", "canonical": true}, {"name": "1 verre de crème de coco", "canonical": true}, {"name": "2 c. à s. de curry", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer et découper le poireau\nen fines lamelles.", "Rincer et découper\nles pommes de terre en dés.", "Éplucher et découper l’oignon\nen dés.", "Dans une poêle chaude huilée,\nfaire cuire l''oignon pendant\n2 min.", "Ajouter la crème de coco et\nlaisser cuire pendant 15 min.", "Dans une casserole d’eau\nbouillante salée, faire cuire"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('051189324242', 'poulet à la moutarde et purée de carottes', null, 'hiver', 'janvier', 1, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poulet-a-la-moutarde-et-puree-de-carottes.jpg', '[{"name": "1 escalope de poulet", "canonical": true}, {"name": "1 c. à c. de farine", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 c. à c. de moutarde", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "2 carottes", "canonical": true}, {"name": "1 pomme de terre", "canonical": true}, {"name": "1 verre de crème de coco", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "Sel et poivre Pour la purée de carottes :", "canonical": true}]'::jsonb, '["Éplucher et couper les carottes\net la pomme de terre en dés.", "Dans une casserole d’eau\nbouillante salée,", "Les égoutter et les écraser à la\nfourchette. Ajouter la crème de\ncoco. Saler, poivrer et ajouter\nle curry. Bien mélanger.\nPour l’escalope :", "Mettre de la farine sur chaque\nface de l’escalope. Tapoter pour\nretirer l’excédent.", "Dans une poêle chaude huilée,\nfaire cuire et dorer l’escalope\n4 min sur chaque face.", "Mélanger le lait et la moutarde.\nSaler et poivrer. Verser dans\nla poêle et laisser mijoter 15 min\njusqu’à ce que la sauce épaississe.\npoulet à la moutarde\net purée de carottes\nSi tu as un mixeur,\ntu peux mixer la purée pour\nune texture plus homogène."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('49a2ce50abd0', 'pâtes au thon', null, 'hiver', 'janvier', 1, 2, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pates-au-thon.jpg', '[{"name": "1 verre de crème fraîche", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "8 à 10 c. à s. de pâtes de ton choix", "canonical": true}, {"name": "1 boîte de thon", "canonical": true}, {"name": "3 c. à s. de sauce tomate", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Éplucher et couper l’oignon en dés.", "Dans une poêle chaude huilée,\nfaire cuire l''oignon pendant\n5 min.", "Égoutter les pâtes et les ajouter\nà la sauce.\npâtes au thon\nPrivilégie les pâtes à\nfarine complète ou semi-complète\npour faire le plein de minéraux.\nElles sont aussi plus rassasiantes."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5e0ec1f686eb', 'velouté poireaux, pesto et fromage de chèvre', null, 'hiver', 'janvier', 1, 2, 'jeudi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/veloute-poireaux-pesto-et-fromage-de-chevre.jpg', '[{"name": "2 poireaux", "canonical": true}, {"name": "2 pommes de terre", "canonical": true}, {"name": "1 c. à s. d''huile de tournesol", "canonical": true}, {"name": "3 verres d’eau + 1 cube de bouillon", "canonical": true}, {"name": "3 cuillères à soupe de pesto vert", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 petit fromage de chèvre", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon,\nles poireaux et les pommes de\nterre en dés.", "Dans une casserole (à bords\nhauts) chaude et huilée, faire\ncuire l''oignon,", "Laisser mijoter pendant 20 min\nen mélangeant de temps\nen temps.", "Mixer la préparation. Si tu n’as\npas de mixeur, tu peux laisser\nles légumes entiers.", "Ajouter le pesto. Bien mélanger.", "Servir dans des bols et ajouter\npar-dessus le fromage de chèvre\ncoupé en dés.\nvelouté poireaux,\npesto et fromage\nde chèvre\nLes veloutés sont des\nrecettes anti-gaspi par excellence.\nTu peux ajouter des légumes\nabîmés pour éviter de les jeter."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1576834c00af', 'chakchouka d’hiver', null, 'hiver', 'janvier', 1, 2, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/chakchouka-d-hiver.jpg', '[{"name": "1 petite boîte de pulpe de tomate", "canonical": true}, {"name": "1 petite boîte d’épinards en conserve", "canonical": true}, {"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à c. de cumin (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de paprika (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d''huile de tournesol", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon\net l’ail en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Casser les œufs dans la\npréparation. Laisser cuire\nenviron 5 min à feu doux\navec un couvercle. Parsemer\nde persil.\nchakchouka d’hiver\nTu peux utiliser\ndes épinards en conserve,\nsurgelés ou frais."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('762ab4963327', 'salade de chou-fleur et truite fumée', null, 'hiver', 'janvier', 1, 3, 'lundi', 'déjeuner/dîner léger', 'salé', 'chou-fleur', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-chou-fleur-et-truite-fumee.jpg', '[{"name": "2 tranches de truite fumée", "canonical": true}, {"name": "1/4 de chou-fleur", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre de ton choix", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION, FRAIS OU SÉCHÉ EN POT)", "canonical": true}, {"name": "1 c. à s. de graines de ton choix (tournesol, courge, sésame…)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Enlever le pied du chou-fleur\nà l’aide d’un couteau. Détacher\nles bouquets et les laver.", "Découper la truite fumée\nen petits morceaux.", "Réaliser la vinaigrette :\nmélanger l’huile, le vinaigre,\nle persil, le sel et le poivre.", "Mélanger tous les ingrédients\net ajouter les graines.\nDans cette recette,\nle chou-fleur est cru. Si tu\nle préfères cuit, plonge-le dans\nune casserole d’eau bouillante\nsalée. Ajouter du jus de citron\ndans l’eau et laisser cuire pendant\n15 min."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2d2479c36fe5', 'burger revisité au chou-fleur', null, 'hiver', 'janvier', 1, 3, 'mardi', 'déjeuner/dîner', 'salé', 'chou-fleur', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/burger-revisite-au-chou-fleur.jpg', '[{"name": "½ chou-fleur", "canonical": true}, {"name": "1 pomme de terre", "canonical": true}, {"name": "1 c. à s. de farine de blé", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "2 steaks hachés", "canonical": true}, {"name": "2 tranches de cheddar", "canonical": true}, {"name": "Sauce (à ta convenance)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre Pour les galettes de chou-fleur et pomme de terre :", "canonical": true}]'::jsonb, '["Laver et couper en dés le chou-fleur\net la pomme de terre.", "Dans une casserole d’eau bouillante\nsalée, faire cuire", "Égoutter et les écraser à la\nfourchette dans un saladier. Ajouter\nles œufs et la farine. Saler et poivrer.\nMélanger et former 4 galettes à\nla main.", "Dans une poêle chaude huilée, faire\ncuire pendant 5 min", "Dans une poêle chaude beurrée,\nfaire cuire", "Assembler les burgers avec la sauce\net avec les galettes en guise de pain\nburger.\nburger revisité\nau chou-fleur"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('df7b5c84f563', 'riz et lentilles aux oignons', null, 'hiver', 'janvier', 1, 3, 'mercredi', 'déjeuner/dîner', 'salé', 'chou-fleur', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/riz-et-lentilles-aux-oignons.jpg', '[{"name": "1 verre de riz", "canonical": true}, {"name": "1 petite conserve de lentilles", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 petit verre de crème", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire le\nriz (temps de cuisson indiqué\nsur", "Égoutter les lentilles.", "Éplucher et couper l’oignon\nen fines lamelles.", "Dans une poêle chaude huilée,\nfaire cuire", "Ajouter le riz cuit, les lentilles,\nla crème et le curry. Saler\net poivrer. Laisser le mélange\nmijoter pendant quelques\nminutes.\nriz et lentilles\naux oignons"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('d3cd5a4c553e', 'gratin dauphinois au micro-ondes', null, 'hiver', 'janvier', 1, 3, 'jeudi', 'déjeuner/dîner', 'salé', 'chou-fleur', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gratin-dauphinois-au-micro-ondes.jpg', '[{"name": "4 pommes de terre", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 verre de crème fraîche liquide", "canonical": true}, {"name": "2 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 c. à s. de muscade (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en fines\nlamelles", "Dans une casserole chaude,\najouter la crème liquide. Saler,\npoivrer et ajouter la muscade.\nPorter à ébullition la crème.", "Beurrer un plat passant au\nmicro-ondes et déposer les\ntranches de pommes de terre.", "Ajouter la crème et recouvrir\nde fromage râpé.", "Mettre le plat au micro-ondes\nà 750W pendant 10 min.\ngratin dauphinois\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f211fd85791b', 'chou-fleur cru et tartinade de fromage frais', null, 'hiver', 'janvier', 1, 3, 'vendredi', 'apéritif/entrée', 'salé', 'chou-fleur', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/chou-fleur-cru-et-tartinade-de-fromage-frais.jpg', '[{"name": "¼ de chou-fleur", "canonical": true}, {"name": "1 petit pot de fromage frais", "canonical": true}, {"name": "1 c. à c. de ciboulette (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de piment d’Espelette (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Enlever le pied du chou-\nfleur à l’aide d’un couteau.\nDétacher les bouquets et les\nlaver minutieusement. Couper\nles bouquets en morceaux.", "Dans un bol, mélanger le reste\ndes ingrédients.", "Tremper les morceaux de\nchou-fleur dans le fromage frais.\nchou-fleur cru\net tartinade\nde fromage frais"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('25541c40e102', 'pancakes salés au thon', null, 'hiver', 'janvier', 1, 4, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/pancakes-sales-au-thon.jpg', '[{"name": "1 petite boîte de thon", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à s. de farine de blé", "canonical": true}, {"name": "2 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Dans un bol, ajouter le thon\némietté, les œufs, la farine,\nl’emmental râpé, les herbes\nde Provence et le poivre.\nBien mélanger.", "Dans une poêle chaude huilée,\nformer des pancakes à l’aide\nd’une cuillère à soupe et faire\ncuire quelques minutes sur"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('231e72300b5a', 'wok aux lentilles corail, oignons et carottes', null, 'hiver', 'janvier', 1, 4, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/wok-aux-lentilles-corail-oignons-et-carottes.jpg', '[{"name": "2 verres de lentilles corail crues", "canonical": true}, {"name": "2 verres de nouilles de riz", "canonical": true}, {"name": "2 carottes", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 c. à s. de sauce soja", "canonical": true}, {"name": "1 c. à s. de gingembre en poudre (EN OPTION)", "canonical": true}, {"name": "Brins de coriandre (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en dés l’ail,", "Dans une casserole chaude\nhuilée,", "En parallèle, faire cuire les\nnouilles de riz dans une casserole\nd’eau bouillante (temps\nde cuisson indiqué sur", "Une fois que les nouilles de riz sont\ncuites, les ajouter dans les légumes\net les lentilles corail. Ajouter\nla sauce soja, le gingembre et\nle poivre. Bien mélanger. Ajouter\nles brins de coriandre en dernier.\nwok aux lentilles\ncorail, oignons\net carottes\nLes lentilles corail\nfont partie de la famille des\nlégumineuses. Elles sont riches en\nfibres et ont la particularité de cuire\nplus vite que les lentilles vertes."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0a83584f1431', 'œufs à la florentine à la poêle', null, 'hiver', 'janvier', 1, 4, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/oeufs-a-la-florentine-a-la-poele.jpg', '[{"name": "400g d’épinards en conserve, frais ou surgelés", "canonical": true}, {"name": "4 œufs", "canonical": true}, {"name": "1 c. à s. de crème fraîche", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer les épinards et enlever\néventuellement les tiges\ndures (pour les épinards frais\nuniquement).", "Dans une poêle chaude huilée,\najouter les épinards et les laisser\ncuire 2 min.", "Ajouter la crème et mélanger.\nCasser les œufs sur les épinards.\nSaler et poivrer.", "Couvrir et laisser cuire 3 min\nà feu doux.\nœufs à"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('69156424b105', 'gnocchis au poireau et sauce gorgonzola', null, 'hiver', 'janvier', 1, 4, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gnocchis-au-poireau-et-sauce-gorgonzola.jpg', '[{"name": "1 paquet de gnocchis", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 morceau de gorgonzola", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés l’oignon\net le poireau.", "Dans une poêle chaude huilée,\nfaire cuire", "Une fois les légumes cuits,\najouter le gorgonzola coupé\nen morceaux. Baisser le feu\net mélanger.", "Dans une casserole d’eau\nchaude salée, faire cuire les\ngnocchis pendant 1 à 2 min.\nIls remontent à", "Ajouter les gnocchis cuits\nà la première préparation.\nMélanger et poivrer.\ngnocchis au poireau\net sauce gorgonzola"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('840624256064', 'rouleaux de jambon et poireau', null, 'hiver', 'janvier', 1, 4, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/rouleaux-de-jambon-et-poireau.jpg', '[{"name": "½ poireau", "canonical": true}, {"name": "2 tranches de jambon", "canonical": true}, {"name": "2 c. à s. d’emmental râpé", "canonical": true}, {"name": "2 c. à s. de crème fraîche", "canonical": true}, {"name": "1 c. à c. de muscade (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver le demi-poireau\net le couper en deux.", "Dans une casserole d’eau\nbouillante salée, faire cuire les\n2 tronçons de poireau pendant\n10 à 15 min.", "Égoutter les tronçons de\npoireau et enlever l''eau restante\nen les essorant à l''aide d''un\ntorchon propre.", "Enrouler les tronçons\nde poireau avec une tranche\nde jambon.", "Les placer dans un plat passant\nau micro-ondes. Ajouter\nla crème et la muscade dans\nle plat. Saler et poivrer.", "Saupoudrer la préparation\nd’emmental râpé et faire cuire\nau micro-ondes pendant 5 min.\nrouleaux de jambon\net poireau\nTu peux choisir\ndu jambon sans nitrites et sans\nconservateurs, qui est meilleur\npour la santé."]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('009125325466', 'clémentines rôties à la cannelle', null, 'hiver', 'janvier', 1, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/clementines-roties-a-la-cannelle.jpg', '[{"name": "2 clémentines", "canonical": true}, {"name": "1 petit verre de jus d’orange", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à s. de cannelle en poudre", "canonical": true}]'::jsonb, '["Éplucher les clémentines\net les séparer en quartiers.", "Dans une poêle, faire\nfondre le beurre et ajouter\nles clémentines. Laisser dorer\npendant 5 min.", "Ajouter le jus d’orange et\nla cannelle. Baisser le feu.\nLaisser mijoter quelques\nminutes avant de servir.\nclémentines rôties\nà la cannelle\n2\nTu peux ajouter\nles épices de ton choix dans\nce dessert (clou de girofle,\nmélange 4 épices…)."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7fea5309a031', 'fudge au chocolat sans cuisson', null, 'hiver', 'janvier', 1, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/fudge-au-chocolat-sans-cuisson.jpg', '[{"name": "2 compotes de pommes sans sucres ajoutés", "canonical": true}, {"name": "¾ d’une tablette de chocolat de ton choix", "canonical": true}, {"name": "Quelques fruits secs de ton choix (amandes, pistaches, noix…)", "canonical": true}]'::jsonb, '["Faire fondre le chocolat au\nmicro‑ondes ou au bain-marie\n(placer le chocolat dans un\nrécipient au-dessus d’une\ncasserole d’eau bouillante).", "Dans un saladier, mélanger\nla compote et le chocolat fondu.", "Laisser figer au réfrigérateur\npendant 4 h.", "Servir avec quelques fruits secs\nconcassés par-dessus.\nfudge au chocolat\nsans cuisson\n1"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('35bf373ae8c3', 'mug cake à la vanille', null, 'hiver', 'janvier', 1, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/mug-cake-a-la-vanille.jpg', '[{"name": "1 c. à c. d’extrait de vanille liquide", "canonical": true}, {"name": "1 c. à s. bombée de farine", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}, {"name": "15g de beurre", "canonical": true}, {"name": "1 œuf", "canonical": true}]'::jsonb, '["Dans un mug, faire fondre le\nbeurre 30 sec au micro-ondes.", "Ajouter le sucre et l’œuf entier.\nMélanger.", "Incorporer la farine et la levure\nchimique. Bien mélanger pour\néviter les grumeaux.", "Ajouter l’extrait de vanille\nliquide.", "Faire cuire au micro-ondes\npendant 50 sec. Vérifier"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2e8855a86ddf', 'pomme au chocolat à la poêle', null, 'hiver', 'janvier', 1, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/pomme-au-chocolat-a-la-poele.jpg', '[{"name": "1 pomme", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "Quelques carreaux de chocolat noir ou au lait", "canonical": true}]'::jsonb, '["Éplucher et couper la pomme\nen rondelles.", "Dans une poêle chaude\nbeurrée, faire dorer les\nrondelles de pomme pendant\n5 min sur feu doux.", "Ajouter quelques carreaux\nde chocolat et laisser fondre.\npomme au chocolat\nà la poêle\n4\nTu peux réaliser cette\nrecette avec n’importe quel fruit\nde saison (orange, banane, poire…)."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a52c84cd4fd5', 'tartines de pain complet et œufs au plat', null, 'hiver', 'janvier', 1, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tartines-de-pain-complet-et-oeufs-au-plat.jpg', '[{"name": "2 tartines de pain complet", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une poêle chaude huilée,\ncasser et faire cuire", "Faire griller les tranches de\npain dans un grille-pain (ou à\nla poêle dans un peu de beurre\nsi tu n’as pas de grille-pain).", "Disposer les œufs sur\nles tranches de pain.\nSaler et poivrer.\ntartines de pain\ncomplet et œufs\nau plat"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b3bd782013ca', 'soupe de pois cassés', null, 'hiver', 'février', 2, 1, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/soupe-de-pois-casses.jpg', '[{"name": "10 c. à s. de pois cassés secs", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 petit verre de crème", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver les pois cassés et les laisser\ntremper 1h dans l’eau chaude.", "Les égoutter. Dans une casserole\nd’eau bouillante, ajouter les pois\ncassés et les faire cuire pendant\n30 min.", "Pendant ce temps, éplucher, laver\net couper en dés", "Dans une poêle chaude huilée,\nfaire cuire pendant 5 à 6 min", "Ajouter le persil et la crème. Saler\net poivrer. Laisser mijoter encore\n5 min.\nPasse le tout au mixeur\nsi tu en as un. C’est une soupe\néconomique qui se conserve\nfacilement dans des récipients\nhermétiques."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('21d1ed16a2ec', 'salade de betterave, riz et fromage', null, 'hiver', 'février', 2, 1, 'mardi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-betterave-riz-et-fromage.jpg', '[{"name": "1 petite betterave cuite", "canonical": true}, {"name": "3 c. à s. de riz", "canonical": true}, {"name": "Quelques dés d’emmental", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de vinaigre", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire le riz dans une casserole\nd’eau bouillante salée\n(temps de cuisson indiqué\nsur le paquet). L’égoutter et\nle passer sous l’eau froide dès\nqu’il est cuit.", "Découper en dés la betterave\net l’emmental.", "Préparer la vinaigrette :\nmélanger l’huile, le vinaigre\net le persil. Saler et poivrer.", "Mélanger tous les ingrédients.\nsalade de betterave,\nriz et fromage\nTu peux ajouter une\ntranche de jambon ou de blanc\nde poulet (à privilégier sans\nnitrites) pour compléter cette\nsalade."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('94568f0f6ff4', 'filets de poulet au curry et légumes croquants', null, 'hiver', 'février', 2, 1, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/filets-de-poulet-au-curry-et-legumes-croquants.jpg', '[{"name": "2 filets de poulet", "canonical": true}, {"name": "1 verre de lait de coco (ou de crème si tu as des restes de la recette de lundi)", "canonical": true}, {"name": "1 petite boîte de conserve de petits pois", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 navet", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de curry", "canonical": true}, {"name": "9 c. à s. de riz", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire le riz dans une casserole\nd’eau bouillante salée (temps de\ncuisson indiqué sur le paquet).", "Découper le poulet en fines\nlamelles.", "Éplucher, laver et couper\nla carotte, le navet, le poireau\net l’oignon en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Enlever la viande, ajouter les\nlégumes dans la poêle et les faire\ncuire pendant 5 min. Ajouter\nde l’eau si le mélange accroche.", "Ajouter le poulet, le curry, le\nlait de coco et les petits pois.\nLaisser mijoter à feu doux\npendant 5 à 6 min. Servir\navec le riz.\nfilets de poulet\nau curry et légumes\ncroquants"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f9ff50444e62', 'omelette au poireau', null, 'hiver', 'février', 2, 1, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/omelette-au-poireau.jpg', '[{"name": "5 œufs", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés\nle poireau et l’ail.", "Dans une poêle chaude huilée,\nfaire cuire pendant 10 à 12 min\nl’ail et", "Casser et battre les œufs dans\nun bol. Saler et poivrer.", "Une fois que les légumes sont\ncuits, ajouter les œufs par-dessus.", "Laisser cuire pendant 3 à 4 min.\nomelette\nau poireau"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0ef66bdc3a0c', 'sandwich sucré-salé œuf et truite', null, 'hiver', 'février', 2, 1, 'vendredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/sandwich-sucre-sale-oeuf-et-truite.jpg', '[{"name": "2 tranches de brioche", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "1 tranche de truite", "canonical": true}, {"name": "1 pot de fromage blanc", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de ciboulette (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire griller la brioche au grille-\npain ou à la poêle avec un peu\nde beurre.", "Dans une poêle chaude huilée,\ncasser", "Verser les œufs dans\nun saladier et ajouter\nun peu de fromage blanc.\nAjouter la ciboulette.", "Déposer les œufs sur\nla brioche, ajouter la truite\net refermer le sandwich.\nsandwich sucré-salé\nœuf et truite\nPendant tes courses\nau supermarché, pour choisir\nune brioche, regarde le Nutri-\nscore : il compare les valeurs\nnutritionnelles de produits\nde la même catégorie. Privilégie\nun Nutri-score se rapprochant de\nla couleur verte et de la lettre A."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5012b151faa2', 'œufs à la coque et mouillettes', null, 'hiver', 'février', 2, 2, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/oeufs-a-la-coque-et-mouillettes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "Pain de campagne", "canonical": true}, {"name": "Fromage de ton choix", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante, faire cuire", "Couper le pain de campagne et\nle fromage en bâtonnets.", "Placer l’œuf dans un coquetier\nou dans un bol. L’ouvrir\ndélicatement sur le dessus.\nTremper les mouillettes dans\nl’œuf.\nœufs à la coque\net mouillettes\nAccompagne cette\nrecette d’un riz aux légumes."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e279e47b560f', 'pizza sans four', null, 'hiver', 'février', 2, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PIZZA', null, null, '/assets/recipe_images/pexels/pizza-sans-four.jpg', '[{"name": "9 c. à s. de lait", "canonical": true}, {"name": "9 c. à s. d’huile d’olive", "canonical": true}, {"name": "8 c. à s. de farine de blé", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 sachet de levure chimique", "canonical": true}, {"name": "1 petite boîte de conserve de thon", "canonical": true}, {"name": "1 boîte de 200 ml de coulis de tomate", "canonical": true}, {"name": "3 cuillères à soupe de fromage râpé", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nle lait, l’huile et les œufs.", "Ajouter la farine et la levure.\nLaisser reposer la pâte 1h.\nSaler et poivrer.", "Couper l’oignon et l’ail en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans une autre poêle chaude\nhuilée, déposer et aplatir", "Recouvrir la poêle avec\ndu papier d’aluminium (ou\nun couvercle) et laisser cuire\nà feu très doux pendant 20 min.\npizza sans four\nAccompagne la pizza\navec une salade de carottes râpées."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f5a78e338330', 'chili sin carne', null, 'hiver', 'février', 2, 2, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/chili-sin-carne.jpg', '[{"name": "½ oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 boîte de tomates pelées", "canonical": true}, {"name": "1 petite boîte de haricots rouges", "canonical": true}, {"name": "4 c. à s. de riz", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de cumin", "canonical": true}, {"name": "1 c. à c. de paprika", "canonical": true}, {"name": "1 c. à c. de coriandre (EN OPTION)", "canonical": true}, {"name": "1 c. à c. d’origan (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Éplucher, laver et couper en dés", "Dans une poêle chaude huilée,\nfaire cuire pendant 3 min", "Ajouter les haricots rouges\négouttés, les tomates pelées,\nle cumin, le paprika, la coriandre\net l’origan. Saler et Poivrer.\nLaisser mijoter pendant 10 min\nà feu doux. Servir avec le riz cuit.\nchili sin carne\nSi tu utilises des herbes\nfraîches, il est préférable de les\najouter vers la fin de cuisson. Elles\npeuvent perdre leur saveur si elles\nsont trop cuites."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3c7fac5e248a', 'salade de pommes de terre et fromage', null, 'hiver', 'février', 2, 2, 'jeudi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-pommes-de-terre-et-fromage.jpg', '[{"name": "2 pommes de terre", "canonical": true}, {"name": "1 petite endive", "canonical": true}, {"name": "Fromage de ton choix", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de vinaigre ou de jus de citron", "canonical": true}, {"name": "1 c. à s. de paprika (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver les pommes de terre\net les couper en dés.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Laver et couper l’endive\nen morceaux.", "Couper le fromage en dés.", "Préparer la vinaigrette :\nmélanger l’huile, le vinaigre\nou le jus de citron et le paprika.\nSaler et poivrer.", "Mélanger tous les ingrédients.\nsalade de pommes\nde terre et fromage\nLe temps de\npréparation n’est pas une perte\nde temps en période de révision.\nIl permet de faire une pause\net de préparer des recettes\navec des aliments essentiels\nau fonctionnement du cerveau."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('afed97f33a1c', 'crêpes jambon champignons et salade', null, 'hiver', 'février', 2, 2, 'vendredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/crepes-jambon-champignons-et-salade.jpg', '[{"name": "3 grands verres de lait", "canonical": true}, {"name": "2 c. à s. de farine de blé", "canonical": true}, {"name": "1 c. à c. de levure chimique", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 petite barquette de champignons", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "2 c. à s. de crème fraîche", "canonical": true}, {"name": "1 tranche de jambon blanc", "canonical": true}, {"name": "1 salade", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger la farine,\nla levure, l’œuf, le lait et l''huile de\ntournesol. Bien mélanger et laisser\nreposer.", "Laver et couper en dés l’échalote\net", "Dans une poêle chaude huilée, faire\ncuire", "Couper la tranche de jambon blanc\nen dés. Les ajouter aux légumes.", "Verser 3 c. à s. de pâte à crêpes dans\nune petite poêle chaude huilée.\nÉtaler", "Garnir les crêpes avec le jambon\net les champignons. Les rouler.", "Servir avec de la salade et\nsa vinaigrette.\ncrêpes jambon\nchampignons\net salade\nTu peux faire plusieurs\ncrêpes d’avance et les garnir avec\nles ingrédients de ton choix."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c966bb8ed5b2', 'salade d’endive au poulet', null, 'hiver', 'février', 2, 3, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-d-endive-au-poulet.jpg', '[{"name": "1 blanc de poulet", "canonical": true}, {"name": "1 petite endive", "canonical": true}, {"name": "½ pot de fromage blanc (MANGER LE RESTE EN DESSERT)", "canonical": true}, {"name": "½ citron", "canonical": true}, {"name": "½ cuillère à café de moutarde", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Quelques noix (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Couper le blanc de poulet\nen dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Laver et couper l’endive en dés.", "Presser le citron.", "Réaliser la sauce : mélanger\nle fromage blanc, le jus de citron,\nla moutarde et le poivre.", "Couper grossièrement les noix.", "Mélanger tous les ingrédients\net le poulet cuit dans un saladier.\nPour faire le plein\nde vitamines, profite des légumes de\nsaison qui sont souvent moins chers."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('626eeaca560e', 'tartinade de lentilles corail', null, 'hiver', 'février', 2, 3, 'mardi', 'apéritif/entrée', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tartinade-de-lentilles-corail.jpg', '[{"name": "4 c. à s. de lentilles corail crues", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à s. de crème fraîche", "canonical": true}, {"name": "½ citron", "canonical": true}, {"name": "1 c. à c. de cumin (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de paprika (EN OPTION)", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "4 tranches de pain complet", "canonical": true}, {"name": "1 salade", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Presser le citron.", "Dans un saladier, ajouter les\nlentilles cuites, la crème fraîche,\nle cumin, l’ail en poudre,\nle paprika, l’huile d’olive et\nle jus de citron. Saler et poivrer.\nÉcraser à la fourchette ou mixer\nle tout.", "Toaster des tranches de pain\ndans un grille-pain ou à", "Étaler la tartinade sur\nles tranches de pain.", "Servir avec de la salade\net sa vinaigrette.\ntartinade\nde lentilles corail\nLes lentilles sont\ngourmandes, bonnes pour la santé\net la planète."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('371e36f9659c', 'pancakes de patate douce', null, 'hiver', 'février', 2, 3, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pancakes-de-patate-douce.jpg', '[{"name": "1 patate douce", "canonical": true}, {"name": "½ verre de lait", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}, {"name": "5 c. à s. bombées de farine de blé", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en dés\nla patate douce.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans un saladier, mélanger\nla farine, l’œuf, le lait et\nla levure. Saler et poivrer.", "Ajouter la patate douce cuite\net l’ail en poudre. Bien mélanger.", "Dans une poêle chaude\nhuilée, déposer une louche\nde pâte de manière à former\nun pancake. Laisser cuire 3 min\nsur chaque face.\npancakes\nde patate douce"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('69d4ef59ee09', 'pâtes à la crème de lentilles corail', null, 'hiver', 'février', 2, 3, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pates-a-la-creme-de-lentilles-corail.jpg', '[{"name": "10 à 11 c. à s. de pâtes", "canonical": true}, {"name": "4 c. à s. de lentilles corail crues", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à s. de crème fraîche", "canonical": true}, {"name": "½ citron", "canonical": true}, {"name": "1 c. à c. de cumin (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de paprika (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Presser le citron.", "Dans un saladier, ajouter\nles lentilles cuites, la crème\nfraîche, le cumin, l’ail en poudre,\nle paprika, l’huile d’olive et le jus\nde citron. Saler et poivrer. Écraser\nà la fourchette ou mixer le tout.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Mélanger les pâtes à la crème\nde lentilles corail sur feu doux.\nParsemer de persil.\npâtes à la crème\nde lentilles corail\nLe citron est\nriche en vitamine C qui booste\nle système immunitaire."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2ecada2bd3fb', 'croque-sardines et salade d’endive', null, 'hiver', 'février', 2, 3, 'vendredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/croque-sardines-et-salade-d-endive.jpg', '[{"name": "1 petite boîte de sardines", "canonical": true}, {"name": "2 tranches de pain de mie complet", "canonical": true}, {"name": "1 pot de fromage blanc", "canonical": true}, {"name": "½ citron", "canonical": true}, {"name": "½ c. à c. de moutarde", "canonical": true}, {"name": "1 endive et sa vinaigrette", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Presser le citron.", "Dans un bol, écraser les\nsardines grossièrement\nà", "Dans le bol, ajouter le fromage\nblanc, la moutarde, le jus\nde citron et le poivre.", "Tartiner les tranches de pain\navec le mélange de sardines.\nRefermer le croque avec les 2\ntranches de pain.", "Dans une poêle chaude huilée,\nfaire dorer", "Laver et couper l’endive en dés."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('331e846b0b36', 'bruschettas au poireau et gorgonzola', null, 'hiver', 'février', 2, 4, 'lundi', 'déjeuner/dîner', 'salé', 'poireau', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/bruschettas-au-poireau-et-gorgonzola.jpg', '[{"name": "1 poireau", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de muscade (EN OPTION)", "canonical": true}, {"name": "4 tranches de pain de campagne", "canonical": true}, {"name": "Quelques morceaux de gorgonzola (EN CONSERVER POUR LA RECETTE DE MERCREDI)", "canonical": true}, {"name": "1 salade", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés le poireau\net l’oignon.", "Dans une poêle chaude huilée,\nfaire cuire", "Faire griller les tranches de pain\nau grille-pain ou à la poêle avec\nun peu de beurre.", "Disposer le poireau et l’oignon\npar-dessus.", "Ajouter les morceaux\nde gorgonzola par-dessus.\nLaisser fondre quelques minutes.", "Servir avec une salade\net sa vinaigrette.\nbruschettas au\npoireau et gorgonzola\nTu peux utiliser du pain\nrassis pour éviter de le jeter."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a3e6c576aace', 'salade de haricots blancs au thon', null, 'hiver', 'février', 2, 4, 'mardi', 'déjeuner/dîner léger', 'salé', 'poireau', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-haricots-blancs-au-thon.jpg', '[{"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de vinaigre de ton choix", "canonical": true}, {"name": "1 c. à c. de moutarde", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "1 petite boîte de haricots blancs", "canonical": true}, {"name": "1 petite boîte de thon", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Préparer la vinaigrette en\nmélangeant l’huile, le vinaigre,\nla moutarde, le persil et le poivre.", "Égoutter les haricots blancs\net les verser dans un saladier.", "Égoutter le thon, l’émietter\net l’ajouter dans le saladier.", "Mélanger avec la vinaigrette.\nsalade de haricots\nblancs au thon\nLes haricots blancs,\ncomme toutes les légumineuses,\nse conservent longtemps quand\nils sont en conserve. Ce sont\ndes indispensables à avoir dans\nses placards."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6a78e01773ce', 'pâtes au poireau et gorgonzola', null, 'hiver', 'février', 2, 4, 'mercredi', 'déjeuner/dîner', 'salé', 'poireau', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pates-au-poireau-et-gorgonzola.jpg', '[{"name": "10 c. à s. de pâtes de ton choix", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "1 c. à s. de crème fraîche", "canonical": true}, {"name": "Quelques morceaux de gorgonzola", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés le\npoireau.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans une casserole d’eau\nbouillante salée, faire cuire les\npâtes (temps de cuisson indiqué\nsur", "Mélanger les pâtes au poireau.\nAjouter les morceaux de\ngorgonzola et laisser fondre\nquelques instants.\npâtes au poireau\net gorgonzola\nTu peux doubler ou\ntripler les quantités de cette\nrecette pour avoir un reste.\nIdéal pour apporter son repas le\nlendemain midi dans un bento\nen verre."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('039c0d512670', 'poulet aux pois chiches', null, 'hiver', 'février', 2, 4, 'jeudi', 'déjeuner/dîner', 'salé', 'poireau', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/poulet-aux-pois-chiches.jpg', '[{"name": "2 blancs de poulet", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "3 c. à s. de semoule de blé", "canonical": true}, {"name": "1 c. à s. de crème fraîche", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper le poulet en morceaux.", "Dans une poêle chaude huilée,\nfaire cuire", "Éplucher et couper l’échalote.\nL''", "Égoutter les pois chiches et les\najouter dans la poêle. Laisser\ncuire à feu doux pendant 10 min.", "Dans un saladier, verser 3 c. à s.\nd''eau bouillante, un peu d''huile\nd''olive et du sel sur", "Une fois le poulet cuit, ajouter\nla crème fraîche. Bien mélanger.", "Servir avec la semoule et le persil.\npoulet aux pois\nchiches"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f9514c132305', 'mug cake poireau-chèvre', null, 'hiver', 'février', 2, 4, 'vendredi', 'déjeuner/dîner', 'salé', 'poireau', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/mug-cake-poireau-chevre.jpg', '[{"name": "½ bûche de fromage de chèvre", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "8 c. à s. de lait", "canonical": true}, {"name": "4 c. à s. de farine", "canonical": true}, {"name": "1 c. à c. de levure chimique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nles œufs, le lait et l’huile.", "Ajouter progressivement\nla farine afin d’éviter les\ngrumeaux. Ajouter la levure\nchimique.", "Laver et couper le poireau\nen dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Couper le fromage en dés\net l’intégrer à la pâte.", "Remplir des mugs compatibles\nau micro-ondes jusqu’à mi-\nhauteur.", "Enfourner au micro-ondes\nà puissance maximale\npendant 2 min.\nmug cake\npoireau-chèvre"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c931d78fb06e', 'blinis sucrés aux fruits d’hiver', null, 'hiver', 'février', 2, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/blinis-sucres-aux-fruits-d-hiver.jpg', '[{"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}, {"name": "2 c. à s. de farine de blé", "canonical": true}, {"name": "2 verres de lait", "canonical": true}, {"name": "1 kiwi", "canonical": true}, {"name": "1 orange", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}]'::jsonb, '["Dans un saladier,\nmélanger l’œuf et le sucre.\nAjouter la farine et le lait\nprogressivement. Ajouter\nla levure chimique.\nBien mélanger.", "Éplucher et couper en dés\nles fruits.", "Dans une poêle chaude huilée,\nverser", "Servir avec les fruits coupés\nen dés.\nblinis sucrés\naux fruits d’hiver\n1\nIntégrer des fruits\nà un dessert permet de le sucrer\nnaturellement."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('327c81e76a6b', 'crème de bananes', null, 'hiver', 'février', 2, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/creme-de-bananes.jpg', '[{"name": "2 bananes", "canonical": true}, {"name": "1 fromage blanc", "canonical": true}, {"name": "1 c. à c. de sucre (EN OPTION)", "canonical": true}, {"name": "Quelques fruits secs (en option : noix, noix de cajou, amandes…)", "canonical": true}]'::jsonb, '["Écraser les bananes à l’aide\nd’une fourchette jusqu’à\nles réduire en purée.", "Ajouter le fromage blanc,\nmélanger puis compléter\navec le sucre et les fruits secs\n(en option).\ncrème de bananes\nLa banane est\nl’alliée des sportifs : elle est riche\nen magnésium et glucides simples."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ef1fa4308348', 'crêpes express', null, 'hiver', 'février', 2, null, null, 'petit déjeuner', 'sucré', null, 'POUR 4 CRÊPES', null, null, '/assets/recipe_images/pexels/crepes-express.jpg', '[{"name": "5 c. à s. de farine de blé", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "Une noisette de beurre", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}]'::jsonb, '["Mettre de la farine dans\nun saladier et former un puits.", "Ajouter l’œuf, le sucre et\nle beurre.", "Mélanger délicatement avec\nun fouet et", "Dans une poêle chaude huilée,\nverser une louche de pâte\net"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5f965757afa1', 'panna cotta de fromage blanc et fruits frais', null, 'hiver', 'février', 2, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/panna-cotta-de-fromage-blanc-et-fruits-frais.jpg', '[{"name": "1 orange", "canonical": true}, {"name": "1 pamplemousse", "canonical": true}, {"name": "1 kiwi", "canonical": true}, {"name": "1 poire", "canonical": true}, {"name": "¼ de tablette de chocolat blanc", "canonical": true}, {"name": "1 petit pot de fromage blanc", "canonical": true}, {"name": "1 feuille de gélatine", "canonical": true}, {"name": "2 c. à s. de crème liquide", "canonical": true}, {"name": "2 sablés bretons", "canonical": true}]'::jsonb, '["Laisser tremper la feuille\nde gélatine dans l’eau froide.", "Dans une casserole chaude,\nverser", "Hors du feu, verser le fromage\nblanc dans la casserole.", "Concasser et répartir les sablés\nbretons dans le fond d’une\nverrine. Déposer le précédent\nmélange par-dessus et laisser\nreposer 1h au frais.", "Peler et découper les fruits\nen dés. Les mélanger dans\nun saladier.", "Déposer les fruits sur\nles panna cottas avant\nde déguster.\npanna cotta\nde fromage blanc\net fruits frais\nLe fromage blanc\nest un indispensable à avoir dans\nson réfrigérateur : en dessert, pour\ndes sauces ou au petit déjeuner."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('d4453207aba2', 'pommes en papillote au micro-ondes', null, 'hiver', 'février', 2, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pommes-en-papillote-au-micro-ondes.jpg', '[{"name": "2 pommes", "canonical": true}, {"name": "1 c. à c. de cannelle en poudre", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}]'::jsonb, '["Peler les pommes. Les couper\nen deux, enlever le cœur et les\ncouper en rondelles.", "Placer les pommes au centre\nd’une feuille de papier\nsulfurisé. Ajouter la cannelle\net le sucre par-dessus.", "Rouler la feuille de papier\nsulfurisé de manière à former\nune papillote.", "Placer dans un plat compatible"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e72b1009141f', 'boulettes de viande au cumin', null, 'hiver', 'mars', 3, 1, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/boulettes-de-viande-au-cumin.jpg', '[{"name": "250g de bœuf haché", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à c. d’origan", "canonical": true}, {"name": "1 c. à c. de cumin", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’ail\nen petits dés.", "Dans un saladier, mélanger\nle bœuf haché avec l’ail,\nle cumin et l’origan. Saler\net poivrer.", "Façonner 12 petites boulettes.", "Dans une poêle chaude huilée,\nfaire cuire pendant 10 min\nen mélangeant.\nServir"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6e89f4b1de5d', 'omelette aux épinards', null, 'hiver', 'mars', 3, 1, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/omelette-aux-epinards.jpg', '[{"name": "3 œufs", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. de fromage râpé", "canonical": true}, {"name": "3 poignées d’épinards frais (OU EN CONSERVE)", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer les épinards et enlever\néventuellement les tiges dures\n(pour les épinards frais).", "Éplucher et couper l’ail\nen petits dés.", "Dans une poêle chaude\nhuilée, faire cuire l’ail pendant\n5 min. Bien mélanger.", "Dans un saladier, casser\nles œufs et les battre en\nomelette à l’aide d’un fouet\nou d’une fourchette. Saler\net poivrer.", "Ajouter les œufs dans la poêle.\nAjouter le fromage râpé par-\ndessus. Baisser le feu et laisser\ncuire jusqu’à ce que les œufs\nsoient cuits à votre goût.\nomelette\naux épinards\nL’ail est bon pour la\nsanté : il est anti-oxydant et il nous\naide à résister aux maladies de\nl’hiver. Un indispensable à toujours\navoir dans ses placards."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b244845490ff', 'maquereau et riz blanc', null, 'hiver', 'mars', 3, 1, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/maquereau-et-riz-blanc.jpg', '[{"name": "1 boîte de filets de maquereau", "canonical": true}, {"name": "5 c. à s. de riz blanc", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "½ cube de bouillon (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et découper\nen dés l’oignon.", "Dans une poêle chaude huilée,\nfaire cuire pendant 3 à 4 min", "Ajouter le demi-cube de\nbouillon et un grand verre\nd’eau chaude.\nBaisser le feu et laisser cuire\npendant 15 min. Rajouter\nde l’eau si besoin.", "Servir le riz avec les filets\nde maquereau en boîte.\nmaquereau\net riz blanc\nLes maquereaux\nsont des poissons à bas coût. On\nles trouve facilement en conserve."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2e626cf18f86', 'poke bowl d’hiver', null, 'hiver', 'mars', 3, 1, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/poke-bowl-d-hiver.jpg', '[{"name": "5 c. à s. de riz", "canonical": true}, {"name": "5 c. à s. de lentilles corail", "canonical": true}, {"name": "2 poignées d’épinards frais", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "2 c. à s. de graines de sésame", "canonical": true}, {"name": "1 petit pot de fromage blanc", "canonical": true}, {"name": "1 citron", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une autre casserole d’eau\nbouillante salée, faire cuire les\nlentilles corail pendant 10 min.", "Égoutter le riz et les lentilles.\nLes verser dans un bol et ajouter\nla sauce soja et mélanger.", "Rincer les épinards et la\ncarotte, les couper en petits\nmorceaux.", "Dans le bol, par-dessus le riz et\nles lentilles, ajouter la carotte\net les épinards. Rajouter de la\nsauce soja. Saupoudrer le tout\nde graines de sésame.", "Réaliser une sauce pour tremper"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('35c4d9ef8372', 'endives et pommes de terre à la fourme d’Ambert', null, 'hiver', 'mars', 3, 1, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/endives-et-pommes-de-terre-a-la-fourme-d-ambert.jpg', '[{"name": "2 ou 3 endives", "canonical": true}, {"name": "2 pommes de terre", "canonical": true}, {"name": "Un petit morceau de fourme d’Ambert", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "1 verre de crème fraîche", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher l’échalote. Découper\nfinement", "Dans une casserole d’eau\nbouillante salée, faire cuire les\npommes de terre pendant 10\nà 15 min.", "Dans une poêle chaude huilée,\nfaire cuire"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e38b554e819f', 'frittata aux champignons', null, 'hiver', 'mars', 3, 2, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/frittata-aux-champignons.jpg', '[{"name": "3 œufs", "canonical": true}, {"name": "1 petit verre de lait", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. d’origan", "canonical": true}, {"name": "1 petite barquette de champignons", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nau fouet ou à", "Éplucher et couper en dés\nl’oignon et les champignons.", "Dans une poêle chaude huilée,\nfaire cuire pendant 5 min les\noignons et", "Ajouter le mélange d’œufs et\nlaisser cuire sur feu doux, jusqu’à\nce que la frittata soit dorée et\nlégèrement soufflée.", "Couper la frittata en 4.\nfrittata\naux champignons\nCette recette\nitalienne peut être servie chaude\nou froide."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('eb465b2f09b7', 'de champignons, fromage frais aux herbes et lardons rôtis', null, 'hiver', 'mars', 3, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/de-champignons-fromage-frais-aux-herbes-et-lardons-rotis.jpg', '[{"name": "1 barquette de champignons", "canonical": true}, {"name": "2 c. à s. de crème fraîche", "canonical": true}, {"name": "1 petit paquet de lardons", "canonical": true}, {"name": "1 fromage frais aux herbes", "canonical": true}, {"name": "1 cube de bouillon", "canonical": true}]'::jsonb, '["Rincer et couper\nles champignons.", "Dans une casserole chaude\nà feu doux, faire cuire les\nchampignons.", "Émietter un cube de bouillon\ndans", "Une fois à ébullition, mixer une\npremière fois", "Mixer une nouvelle fois la soupe\njusqu’à obtenir une texture\nonctueuse.", "Dans une poêle, faire griller les\nlardons et"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c6dd6a82a1fc', 'filets de harengs et salade', null, 'hiver', 'mars', 3, 2, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/filets-de-harengs-et-salade.jpg', '[{"name": "1 paquet de filets de harengs cuits", "canonical": true}, {"name": "½ salade", "canonical": true}, {"name": "1 c. à c. de moutarde", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre de ton choix", "canonical": true}, {"name": "1 c. à c. de persil", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Séparer les feuilles et laver\nla salade.", "Préparer la vinaigrette :\nmélanger la moutarde, l’huile,\nle vinaigre et le persil.\nSaler et poivrer.", "Mélanger la salade avec\nla vinaigrette.", "Servir les harengs avec\nla salade.\nfilets de harengs\net salade\nLe hareng est\nun poisson dit « gras ». Il est\néconomique. Il est souvent vendu\nfumé ou mariné."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f6963d887cf9', 'truffade express', null, 'hiver', 'mars', 3, 2, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/truffade-express.jpg', '[{"name": "7 pommes de terre", "canonical": true}, {"name": "250g de tome fraîche du Cantal", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 barquette de lardons", "canonical": true}]'::jsonb, '["Éplucher et laver les pommes\nde terre. Les couper en dés.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Éplucher et couper l’ail en dés.", "Dans une poêle à bords hauts,\najouter les lardons et l’ail et faire\ncuire quelques minutes. Ajouter\nles pommes de terre cuites.", "Sur feu doux, ajouter le fromage\ncoupé en dés. Laisser fondre\nle fromage puis mélanger\ndélicatement.\ntruffade express\nLa truffade est un\nplat originaire d’Auvergne. Tu peux\nl’accompagner avec une salade et\nsa vinaigrette."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('593674709701', 'one pot pasta d’hiver', null, 'hiver', 'mars', 3, 2, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/one-pot-pasta-d-hiver.jpg', '[{"name": "1 oignon", "canonical": true}, {"name": "2 carottes", "canonical": true}, {"name": "1 boîte de conserve de lentilles", "canonical": true}, {"name": "8 à 9 c. à s. de pâtes de ton choix", "canonical": true}, {"name": "1 petite boîte de sauce tomate", "canonical": true}, {"name": "1 c. à s. de thym", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en dés\nl’oignon et les carottes.", "Dans une casserole chaude\nhuilée, faire cuire", "Ajouter la sauce tomate et\nun peu d’eau. Saler et poivrer.\nAjouter le thym. Laisser cuire\nsur feu doux pendant quelques\nminutes.", "Ajouter les pâtes et les laisser\ncuire dans la sauce tomate\npendant 8 à 10 min. Ajouter\nde l’eau si nécessaire.", "Égoutter les lentilles. Lorsque\nles pâtes sont cuites, ajouter\nles lentilles. Bien mélanger.\none pot pasta d’hiver\nCette recette est\ndéclinable avec plusieurs légumes\nd’hiver (champignons, panais,\nchou-fleur…)."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('beef1018a570', 'poulet à la crème', null, 'hiver', 'mars', 3, 3, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poulet-a-la-creme.jpg', '[{"name": "1 blanc de poulet", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "1 verre de crème fraîche", "canonical": true}, {"name": "5 c. à s. de riz", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol (POUR LA CUISSON)", "canonical": true}, {"name": "½ endive", "canonical": true}, {"name": "1 c. à s. d’huile de colza (POUR LA SAUCE)", "canonical": true}, {"name": "1 c. à s. de vinaigre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon en\ndés.", "Couper le blanc de poulet en\ndés.", "Dans une poêle chaude huilée,\nfaire cuire", "Baisser le feu et ajouter la\ncrème. Saler et poivrer. Laisser\nle mélange mijoter à feu doux.", "Dans une casserole d’eau\nbouillante salée, faire cuire le\nriz pendant 10 min. L’égoutter.\nServir", "Préparer la salade d’endive :\nlaver et couper l’endive\nen dés. Réaliser la vinaigrette\nen mélangeant l’huile de colza\net le vinaigre. Saler et poivrer.\nTu peux réaliser\ncette recette avec de la crème\nfraîche ou de la crème de coco."]'::jsonb, 'la crème', false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2baf63c77010', 'tartinade de lentilles express', null, 'hiver', 'mars', 3, 3, 'mardi', 'apéritif/entrée', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tartinade-de-lentilles-express.jpg', '[{"name": "1 boîte de lentilles vertes cuites", "canonical": true}, {"name": "2 c. à c. de fromage frais", "canonical": true}, {"name": "1 c. à c. de piment d’Espelette", "canonical": true}, {"name": "1 baguette de pain de campagne", "canonical": true}, {"name": "½ endive", "canonical": true}, {"name": "1 c. à s. d’huile de colza (POUR LA SAUCE)", "canonical": true}, {"name": "1 c. à s. de vinaigre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter les lentilles.", "Dans un saladier, écraser à\nla fourchette les lentilles avec\nle fromage et le piment. Saler\net poivrer.", "Couper des tranches de pain\nde campagne et tartiner", "Servir avec une salade\nd’endive : laver et couper\nl’endive en dés. Faire\nla vinaigrette en mélangeant\nl’huile de colza et le vinaigre.\nSaler et poivrer.\ntartinade\nde lentilles express\nSi tu as un mixeur,\ntu peux mixer la tartinade pour\nun rendu plus homogène."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ed8a0039005e', 'velouté de lentilles avec œuf poché et parmesan', null, 'hiver', 'mars', 3, 3, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/veloute-de-lentilles-avec-oeuf-poche-et-parmesan.jpg', '[{"name": "1 boîte de lentilles", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 verre de crème fraîche", "canonical": true}, {"name": "2 c. à s. de fécule de maïs", "canonical": true}, {"name": "4 c. à s. de parmesan râpé", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 verre de vin blanc cuisine (EN OPTION)", "canonical": true}, {"name": "1 c. à s. de coriandre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon en dés.", "Dans une poêle huilée à bords hauts,\nfaire cuire", "Égoutter les lentilles et les ajouter\nà la préparation. Ajouter la crème et\nla fécule de maïs diluée dans un petit\nverre d’eau. Laisser mijoter pendant\n10 min sur feu doux.", "Pour préparer l’œuf poché, verser\nun peu de vinaigre dans une\ncasserole d’eau bouillante. Former un\ntourbillon avec une spatule. Verser\ndélicatement l’œuf au centre du\ntourbillon. Attendre 3 min. Sortir et\négoutter l’œuf à l’aide d’une spatule.", "Déposer le velouté dans une\nassiette creuse avec l’œuf poché, le\nparmesan saupoudré et un peu de\ncoriandre.\nvelouté de lentilles\navec œuf poché\net parmesan\nS’il te reste du pain de\ncampagne de la veille, tu peux le\ncouper en petits morceaux pour en\nfaire des croûtons."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b5704eada35c', 'terrine de sardines au micro-ondes', null, 'hiver', 'mars', 3, 3, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/terrine-de-sardines-au-micro-ondes.jpg', '[{"name": "1 boîte de sardines", "canonical": true}, {"name": "1 verre de crème fraîche", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 citron", "canonical": true}, {"name": "1 c. à s. de ciboulette", "canonical": true}, {"name": "1 noisette de beurre (POUR LES RAMEQUINS)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Couper et presser le jus\nd’un citron.", "Dans un saladier, ajouter tous\nles ingrédients et écraser\nles sardines à la fourchette.", "Beurrer des ramequins passant\nau micro-ondes et", "Cuire au micro-ondes pendant\n12 min.", "Laisser refroidir et servir avec\nde"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('532ddb355ec0', 'curry de pois chiches et d’épinards', null, 'hiver', 'mars', 3, 3, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/curry-de-pois-chiches-et-d-epinards.jpg', '[{"name": "9 c. à s. de riz", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 boîte de conserve de pois chiches", "canonical": true}, {"name": "1 boîte de conserve d’épinards", "canonical": true}, {"name": "1 verre de purée de tomate en conserve", "canonical": true}, {"name": "1 petite brique de lait de coco", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à s. de curry en poudre", "canonical": true}, {"name": "1 c. à s. de paprika en poudre", "canonical": true}, {"name": "1 c. à s. de cumin en poudre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon en dés.", "Dans une poêle chaude huilée,\nfaire cuire pendant 2 à 3 min", "Égoutter les pois chiches et les\najouter à la préparation. Ajouter\nle lait de coco et la conserve de\ntomate. Saler et poivrer. Bien\nmélanger et faire cuire avec\nun couvercle pendant 20 min,\nà feu doux.", "Dans une casserole d’eau\nbouillante salée, faire cuire le\nriz pendant 10 min. L’égoutter\net"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('4428214f23f0', 'croquettes de carottes et mozzarella', null, 'hiver', 'mars', 3, 4, 'lundi', 'déjeuner/dîner', 'salé', 'carotte', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/croquettes-de-carottes-et-mozzarella.jpg', '[{"name": "4 carottes", "canonical": true}, {"name": "1 pomme de terre", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "4 c. à s. de chapelure", "canonical": true}, {"name": "1 boule de mozzarella", "canonical": true}, {"name": "1 verre d’huile de tournesol ou d’huile de friture", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en dés\nles carottes et la pomme\nde terre.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans un saladier, verser\nles légumes et les écraser à la\nfourchette jusqu’à obtenir une\npurée. Ajouter la farine. Saler\net poivrer. Bien mélanger.", "Couper des bâtonnets\nde mozzarella.", "Les enrober avec la préparation\nde légumes de manière\nà former les croquettes.", "Mettre la chapelure dans une\nassiette creuse et enrouler\nles croquettes dedans.", "Mettre l’huile dans une casserole\nchaude à bords hauts. Faire\nfrire"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('24cea8993782', 'bolognaise de lentilles', null, 'hiver', 'mars', 3, 4, 'mardi', 'déjeuner/dîner', 'salé', 'carotte', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/bolognaise-de-lentilles.jpg', '[{"name": "1 boîte de lentilles", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "1 boîte de coulis de tomate", "canonical": true}, {"name": "1 c. à c. de thym", "canonical": true}, {"name": "1 c. à c. de romarin", "canonical": true}, {"name": "6 c. à s. de pâtes de ton choix", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en dés\nla carotte, l’oignon et l’ail.", "Dans une poêle chaude huilée,\nfaire cuire pendant 5 min", "Égoutter les lentilles.", "Ajouter le coulis de tomate et\nles lentilles dans la poêle. Saler\net poivrer. Ajouter le thym et\nle romarin. Laisser cuire pendant\n20 min. Ajouter un peu d’eau\nsi besoin.", "Dans une casserole d’eau\nbouillante salée, faire cuire les\npâtes en fonction du temps\nindiqué sur", "Mélanger les pâtes avec la sauce\nbolognaise.\nbolognaise\nde lentilles\nL’huile d’olive ou\nl’huile de tournesol sont des huiles\nqui sont idéales pour la cuisson\ndes aliments. L’huile de tournesol\nsera plus économique."]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('85e6cb1a41ef', 'crumble de carottes et lardons au micro-ondes', null, 'hiver', 'mars', 3, 4, 'mercredi', 'déjeuner/dîner', 'salé', 'carotte', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/crumble-de-carottes-et-lardons-au-micro-ondes.jpg', '[{"name": "2 carottes", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 petite barquette de lardons", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 morceau de beurre", "canonical": true}, {"name": "1 c. à c. de thym frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés les\ncarottes,", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une poêle chaude, faire cuire\nquelques minutes", "Dans un saladier, mélanger\navec les mains la farine, le\nbeurre en petits morceaux et\nle thym. Saler et poivrer. Bien\nmélanger afin d’obtenir une\npâte à crumble.", "Dans un plat passant au\nmicro‑ondes, verser les\nlégumes et", "Enfourner au micro-ondes\npendant 5 min.\ncrumble de carottes\net lardons\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('08d513ecae56', 'merlan en papillote', null, 'hiver', 'mars', 3, 4, 'jeudi', 'déjeuner/dîner', 'salé', 'carotte', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/merlan-en-papillote.jpg', '[{"name": "2 filets de merlan", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 citron", "canonical": true}, {"name": "1 c. à s. de lait de coco", "canonical": true}, {"name": "1 c. à c. de persil", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper la carotte\net l’oignon en dés. Couper\nle citron en rondelles.", "Dans une poêle chaude huilée,\nfaire cuire pendant 5 à 8 min", "Ajouter le lait de coco et le persil.", "Sur une feuille de papier\ncuisson, déposer", "Replier la feuille de papier cuisson\nau centre et tordre les extrémités\npour former une papillote.", "Mettre la papillote dans une\nassiette et l’enfourner au\nmicro‑ondes pendant 2 à 3 min.\nmerlan en papillote\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2958bb4e35b8', 'pancakes de carottes ', null, 'hiver', 'mars', 3, 4, 'vendredi', 'déjeuner/dîner', 'salé', 'carotte', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pancakes-de-carottes.jpg', '[{"name": "2 carottes", "canonical": true}, {"name": "1 verre de lait de coco", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}, {"name": "5 c. à s. de farine", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper les carottes\nen dés.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans un saladier, écraser\nles carottes à la fourchette\npour former une purée.", "Dans un autre saladier, mélanger", "Incorporer les carottes cuites\ndans la pâte. Bien mélanger.", "Dans une poêle chaude huilée,\ndéposer une louche de pâte\npour former un pancake.\nLaisser cuire 3 min à feu moyen\nde chaque côté.\npancakes de carottes"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('fdb51a8f1a01', 'crème à la vanille express', null, 'hiver', 'mars', 3, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/creme-a-la-vanille-express.jpg', '[{"name": "2 verres de lait", "canonical": true}, {"name": "2 c. à s. d’arôme vanille liquide", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "2 c. à s. de farine de blé", "canonical": true}]'::jsonb, '["Mélanger la farine avec\nun demi-verre de lait.", "Dans une casserole, faire\nchauffer", "Quand le lait est chaud mais\npas bouillant, verser le premier\nmélange farine et lait. Mélanger\naussitôt au fouet. Maintenir\nun léger bouillonnement.\nLe mélange doit épaissir.", "Verser dans des ramequins\net garder au frais pendant\nau moins 2h.\ncrème\nà la vanille\nexpress\n4"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('75de90894bc6', 'mug cake beurre de cacahuète et pépites de chocolat', null, 'hiver', 'mars', 3, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/mug-cake-beurre-de-cacahuete-et-pepites-de-chocolat.jpg', '[{"name": "3 pommes golden", "canonical": true}, {"name": "13 c. à s. de sucre", "canonical": true}, {"name": "2 verres de crème liquide", "canonical": true}, {"name": "3 c. à s. de graines de sésame", "canonical": true}]'::jsonb, '["Éplucher les pommes en laissant\nla peau à intervalles réguliers.", "Dans une casserole d’eau chaude,\nverser 6 c. à s. de sucre. Une\nfois", "Dans une poêle chaude, faire\nfondre", "Une fois les pommes cuites, les\ntremper dans le caramel encore\nliquide.", "Ajouter la crème dans le reste de\ncaramel et le porter à ébullition\njusqu’à obtenir un mélange\nonctueux. Déposer le mélange\nau fond d’une assiette puis\ndéposer les pommes.\npommes d’amour\npochées au caramel\n3"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('fe6b99ad21c7', 'pain perdu', null, 'hiver', 'mars', 3, null, null, 'dessert', 'sucré', null, 'POUR 1 MUG CAKE', null, null, '/assets/recipe_images/pexels/pain-perdu.jpg', '[{"name": "1 carré de chocolat", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}, {"name": "1 jaune d’œuf", "canonical": true}, {"name": "1 c. à c. de beurre de cacahuète", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}]'::jsonb, '["Casser l’œuf et séparer le\njaune du blanc dans deux bols\ndifférents.", "Dans un mug, faire fondre\nle beurre au micro-ondes\npendant 40 sec. Ajouter\nle sucre, le jaune d’œuf et le\nbeurre de cacahuète. Mélanger.", "Verser la farine et mélanger\nà nouveau. À l’aide d’un\ncouteau, hacher le chocolat\npour en former des pépites\npuis les incorporer à la pâte.", "Faire cuire 1 min 30 au\nmicro‑ondes. Laisser reposer\n2 min avant de déguster.\nmug cake beurre\nde cacahuète et\npépites de chocolat\n1\nDans"]'::jsonb, null, true, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('4db4d55019af', 'pommes d’amour pochées au caramel', null, 'hiver', 'mars', 3, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pommes-d-amour-pochees-au-caramel.jpg', '[{"name": "½ verre de lait", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "4 tranches de pain rassis", "canonical": true}, {"name": "Une noisette de beurre", "canonical": true}]'::jsonb, '["Dans un saladier, fouetter les\nœufs", "Tremper les tranches de pain\ndans le mélange pendant\nquelques minutes, jusqu’à ce\nqu’elles soient bien imbibées.", "Dans une poêle chaude\nbeurrée, faire cuire"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a6677d3f2dbd', 'porridge pomme et chocolat', null, 'hiver', 'mars', 3, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/porridge-pomme-et-chocolat.jpg', '[{"name": "3 c. à s. de flocons d’avoine", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "4 carrés de chocolat", "canonical": true}, {"name": "1 pomme", "canonical": true}, {"name": "1 c. à c. de graines de chia", "canonical": true}]'::jsonb, '["Éplucher, enlever le cœur\net couper la pomme en dés.", "Dans une casserole chaude,\nmettre", "Dans une autre casserole, faire\ncuire", "Ajouter la pomme cuite et les\ngraines de chia dans la casserole\nde flocons d’avoine. Mélanger.\nLaisser les flocons absorber le lait.", "Verser dans un bol. Ajouter les\ncarrés de chocolat dans le porridge\npour qu’ils fondent.\nporridge pomme\net chocolat"]'::jsonb, null, false, true, 'crous', 'Crous_CalendrierRecette_Hiver.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('dc6b36a49230', 'flan aux asperges vertes aumicro-ondes', null, 'printemps', 'avril', 4, 1, 'lundi', 'déjeuner/dîner', 'salé', 'asperges', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/flan-aux-asperges-vertes-aumicro-ondes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "1 c. à s. de crème fraîche liquide", "canonical": true}, {"name": "1 c. à s. de fromage râpé", "canonical": true}, {"name": "10 asperges vertes en bocaux", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "Aneth", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper le demi\noignon. Couper les asperges\nen morceaux.", "Dans un bol, mélanger les œufs,\nle fromage râpé et la crème\nfraîche. Ajouter les asperges,\nle demi oignon et l’aneth.\nSaler et poivrer.", "Verser la préparation dans\n2 ramequins (compatibles au\nmicro-ondes).", "Faire cuire 2 min (puissance\nmaximale) au micro-ondes tout\nen surveillant."]'::jsonb, 'Pour un repas complet, ajoute les féculents de ton choix (pâtes, pain, riz…).', true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('49437aea10b0', 'apéro zéro déchet à la carotte', null, 'printemps', 'avril', 4, 1, 'mardi', 'apéritif/entrée', 'salé', 'asperges', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/apero-zero-dechet-a-la-carotte.jpg', '[{"name": "3 carottes avec fanes", "canonical": true}, {"name": "1 poignée de graines de courge", "canonical": true}, {"name": "1 poignée de pignons de pin", "canonical": true}, {"name": "2 c. à s. de parmesan râpé", "canonical": true}, {"name": "1 petite gousse d’ail", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Laver soigneusement les carottes\net récupérer les fanes.", "Éplucher les carottes mais\nconserver les épluchures.\nDécouper les carottes\nen bâtonnets.", "Hacher finement l’ail et les fanes\npuis les mettre de côté dans\nun bol.", "Concasser grossièrement les\npignons de pin et", "Faire frire les épluchures dans\nl’huile de tournesol pendant\n5 min. Les déposer sur un papier\nabsorbant.", "Déguster le pesto de fanes,\nles chips d’épluchures et\nles bâtonnets de carottes.\napéro zéro déchet\nà la carotte"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e1c13872c33d', 'boulettes de bœuf à la sauce tomate', null, 'printemps', 'avril', 4, 1, 'mercredi', 'déjeuner/dîner', 'salé', 'asperges', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/boulettes-de-boeuf-a-la-sauce-tomate.jpg', '[{"name": "1 steak haché", "canonical": true}, {"name": "3 c. à s. de coulis de tomate", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "2 c. à c. de persil frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un bol, écraser le steak\net ajouter 1 c. à c. de persil.\nMélanger.", "Façonner les boulettes.", "Dans une poêle huilée, faire\ncuire", "Ajouter le coulis de tomate et\n1 c. à c. de persil dans la poêle.\nSaler et poivrer.\nboulettes de bœuf\nà la sauce tomate"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f4fdebe18f27', 'poêlée de pois chiches et asperges', null, 'printemps', 'avril', 4, 1, 'jeudi', 'déjeuner/dîner', 'salé', 'asperges', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poelee-de-pois-chiches-et-asperges.jpg', '[{"name": "1 petite boîte de conserve de pois chiches", "canonical": true}, {"name": "10 asperges en bocal", "canonical": true}, {"name": "2 c. à c. de sauce soja", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Égoutter les pois chiches et\nles rincer.", "Couper les asperges\nen morceaux.", "Dans une poêle huilée, faire\ncuire"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ece13f5f3e57', 'saumon, asperges grillées et sauce citron', null, 'printemps', 'avril', 4, 1, 'vendredi', 'déjeuner/dîner', 'salé', 'asperges', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/saumon-asperges-grillees-et-sauce-citron.jpg', '[{"name": "1 pavé de saumon", "canonical": true}, {"name": "10 asperges en bocal", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 jaune d’œuf", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. d’aneth", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter et couper les asperges\nen morceaux.", "Dans une poêle huilée, faire\ncuire", "Casser l’œuf et séparer le jaune\ndu blanc.", "Presser le citron.", "Dans une casserole sur feu doux,\nfouetter", "Dans une assiette, verser la sauce\nsur le saumon et les asperges.\nsaumon,\nasperges grillées\net sauce citron"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8a4f8b8606e2', 'endive farcie au jambon et à la feta', null, 'printemps', 'avril', 4, 2, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/endive-farcie-au-jambon-et-a-la-feta.jpg', '[{"name": "1 endive", "canonical": true}, {"name": "2 tranches de jambon", "canonical": true}, {"name": "Quelques morceaux de feta", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Détacher et laver les feuilles\nde l’endive. Couper la moitié des\nfeuilles de l’endive en petits dés.", "Couper le jambon et la feta\nen dés.", "Dans un bol, mélanger\nle jambon, la feta et les feuilles\nde l’endive coupée. Saler\net poivrer.", "Farcir les feuilles restantes\nde l’endive avec la préparation.\nendive farcie au\njambon et à la feta\nTu peux rajouter\ndu riz cuit à la farce pour\nun repas plus consistant !"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a9fa090e1709', 'linguines au pesto de menthe et feta', null, 'printemps', 'avril', 4, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/linguines-au-pesto-de-menthe-et-feta.jpg', '[{"name": "1 petite poignée de linguines (À TA CONVENANCE)", "canonical": true}, {"name": "5 feuilles de menthe fraîche", "canonical": true}, {"name": "Quelques morceaux de feta", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une eau bouillante salée,\nfaire cuire", "Couper la menthe en fines\nlamelles.", "Dans un bol, mélanger\nla menthe et l’huile.\nSaler et poivrer.", "Verser le pesto de menthe sur\nles linguines et émietter la feta\npar-dessus.\nlinguines au pesto\nde menthe et feta\nPour un repas complet,\najoute un légume cru et 2 œufs\npar exemple."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a8c11237d8a8', 'salade de haricots rouges', null, 'printemps', 'avril', 4, 2, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-haricots-rouges.jpg', '[{"name": "1 petite boîte de conserve de haricots rouges", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter et rincer les haricots\nrouges.", "Laver et éplucher la carotte.\nÀ l’aide d’un épluche-légumes,\nréaliser des tagliatelles avec\nla carotte.", "Éplucher, couper le demi oignon\net l’ail en dés.", "Dans un bol, mélanger l’huile,", "Dans un saladier, mélanger tous"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7a94a5871a10', 'mac and cheese sans four', null, 'printemps', 'avril', 4, 2, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/mac-and-cheese-sans-four.jpg', '[{"name": "1 verre de macaroni cru", "canonical": true}, {"name": "2 c. à s. de cheddar râpé", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 verre de lait demi‑écrémé", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une eau bouillante\nsalée, faire cuire", "Pour la béchamel, verser\nle beurre dans une casserole\net ajouter la farine. Mélanger\npuis ajouter le lait petit\nà petit. Mélanger en continu,\nla béchamel doit épaissir.\nSaler et poivrer.", "Incorporer le cheddar râpé à la\nbéchamel et mélanger jusqu’à\nce qu’il soit fondu.", "Mélanger la sauce aux\nmacaronis.\nmac and cheese\nsans four\nTu peux ajouter des\nrestes de fromage (pour éviter de\nles jeter) dans la sauce des mac\nand cheese."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('080632ebf07a', 'Cake au thon, tomates séchées et feta au micro-ondes', null, 'printemps', 'avril', 4, 2, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/cake-au-thon-tomates-sechees-et-feta-au-micro-ondes.jpg', '[{"name": "1 petite boîte de thon", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "6 tomates séchées", "canonical": true}, {"name": "½ bloc de feta", "canonical": true}, {"name": "4 c. à s. de farine", "canonical": true}, {"name": "2 c. à s. de beurre", "canonical": true}, {"name": "1 c. à c. de levure chimique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire fondre le beurre\nau micro‑ondes.", "Couper les tomates séchées en\npetits morceaux.", "Dans un saladier, mélanger\nla farine et la levure. Former\nun puits et ajouter l’œuf.\nFouetter petit à petit.", "Ajouter le beurre fondu.\nÉmietter le thon et la feta\ndans la préparation. Ajouter\nles tomates séchées. Mélanger.", "Beurrer un moule compatible\navec la cuisson au micro-ondes\net verser la préparation. Faire\ncuire 6 à 8 min au micro-ondes\nà puissance maximale.\nCake au thon,\ntomates séchées et\nfeta au micro-ondes\nTu peux compléter\ncette recette avec une salade\nde carottes. Tu les coupes à\nl’aide d’un épluche-légumes pour\nformer des tagliatelles de carottes\net tu réalises une vinaigrette."]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cc8343f38c67', 'tartines d’oeufs brouillés', null, 'printemps', 'avril', 4, 3, 'lundi', 'déjeuner/dîner léger', 'salé', 'poireaux', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tartines-d-oeufs-brouilles.jpg', '[{"name": "2 tranches de pain de campagne", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "3 tomates séchées", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 c. à s. d’emmental râpé", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. d’origan", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper les tomates séchées et le\ndemi oignon en petits morceaux.", "Dans un bol, casser les œufs\net mélanger à l’aide d’une\nfourchette.", "Ajouter les tomates séchées,\nle demi oignon, l’emmental\net l’origan. Saler et poivrer", "Dans une poêle huilée,\nverser les œufs et mélanger\ncontinuellement jusqu’à ce\nqu’ils soient cuits.", "Faire griller le pain à la poêle\navec 1 noisette de beurre\n(ou au grille-pain si tu en as un).", "Mettre les œufs brouillés sur\nle pain grillé.\nCette recette se\ndécline à l’infini, avec tous les\naliments (ou presque) qui peuvent\nêtre dans ton réfrigérateur."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f5cb740bc887', 'tagliatelles aux poireaux', null, 'printemps', 'avril', 4, 3, 'mardi', 'déjeuner/dîner', 'salé', 'poireaux', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tagliatelles-aux-poireaux.jpg', '[{"name": "1 poignée de tagliatelles (environ 60g)", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de noix de muscade moulue", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une eau bouillante salée,\nfaire cuire", "Rincer et couper le demi\npoireau en petits cubes.", "Dans une poêle huilée, faire\ncuire"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('48487f685b39', 'croquettes de poisson blanc', null, 'printemps', 'avril', 4, 3, 'mercredi', 'déjeuner/dîner', 'salé', 'poireaux', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/croquettes-de-poisson-blanc.jpg', '[{"name": "1 filet de poisson blanc", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. de persil frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à s. de chapelure (OU PAIN DUR MIXÉ)", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire le poisson blanc dans une\neau bouillante salée pendant\n8 à 10 min. L’égoutter.", "Dans un bol, écraser le poisson\nà l’aide d’une fourchette,\najouter le persil et l’ail\nen poudre. Saler et poivrer.", "Casser l’œuf dans un autre bol\net le fouetter. Mettre la farine\net la chapelure dans 2 assiettes\ndifférentes.", "Former des boules de poisson\ndans vos mains puis", "Dans une poêle chaude huilée,\nfaire dorer"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b21211b4a641', 'gratin de poireau, pommes de terre et roquefort', null, 'printemps', 'avril', 4, 3, 'jeudi', 'déjeuner/dîner', 'salé', 'poireaux', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/gratin-de-poireau-pommes-de-terre-et-roquefort.jpg', '[{"name": "2 pommes de terre moyennes", "canonical": true}, {"name": "½ poireau", "canonical": true}, {"name": "Quelques morceaux de roquefort", "canonical": true}, {"name": "1 c. à s. d’emmental râpé", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Éplucher et couper en dés\nles pommes de terre.", "Laver et couper le demi poireau\nen dés.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans un plat, mettre\nles pommes de terre, le poireau\net le roquefort coupé en dés.", "Ajouter le fromage râpé et faire\nchauffer 2 à 3 min au micro-\nondes pour que le fromage\nfonde.\ngratin de poireau,\npommes de terre\net roquefort\nLes pommes de terre\nsont des féculents économiques, à\ntoujours avoir dans ses placards. Les\nconserver à l’abri de la lumière."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('28e3671654cd', 'burritos de poulet, tomates pimentées et fraîcheur de yaourt', null, 'printemps', 'avril', 4, 3, 'vendredi', 'déjeuner/dîner', 'salé', 'poireaux', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/burritos-de-poulet-tomates-pimentees-et-fraicheur-de-yaourt.jpg', '[{"name": "1 blanc de poulet", "canonical": true}, {"name": "1 yaourt", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "1 citron vert", "canonical": true}, {"name": "Quelques feuilles de salade", "canonical": true}, {"name": "1 c. à c. de piment", "canonical": true}, {"name": "2 c. à c. de ciboulette fraîche (OU SÉCHÉE EN POT)", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 c. à s. de cumin", "canonical": true}, {"name": "2 tortillas de blé", "canonical": true}]'::jsonb, '["Découper le poulet en fines\nlamelles.", "Couper tous les légumes.", "Dans une poêle chaude\nhuilée, faire cuire", "Pour la sauce : mélanger\nle yaourt, le jus du citron,\nla ciboulette et le cumin.", "Disposer la salade, la sauce\npuis le poulet sur les 2 tortillas\net les enrouler.\nburritos de poulet,\ntomates pimentées et\nfraîcheur de yaourt\nPour une version\nvégétarienne, tu peux remplacer\nle poulet par des haricots\nrouges (ils s’achètent facilement\nen conserve)."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f25a8678c44b', 'hachis parmentier sans four', null, 'printemps', 'avril', 4, 4, 'lundi', 'déjeuner/dîner', 'salé', 'épinards', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/hachis-parmentier-sans-four.jpg', '[{"name": "1 escalope de dinde ou de poulet", "canonical": true}, {"name": "2 carottes cuites", "canonical": true}, {"name": "2 pommes de terre cuites à l’eau", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 verre de crème", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "7 c. à s. de parmesan râpé", "canonical": true}, {"name": "4 c. à s. de beurre", "canonical": true}, {"name": "Persil frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de muscade", "canonical": true}, {"name": "Huile d’olive", "canonical": true}]'::jsonb, '["Dans une casserole, porter le lait,\nla crème et le beurre à ébullition.\nAjouter la muscade.", "Hors du feu, mélanger\nla préparation avec les pommes\nde terre et les carottes cuites..", "Découper le poulet en petit\ndés. Couper finement le persil.\nCouper le demi oignon en dés.", "Dans une poêle huilée, faire cuire", "Dans un ramequin, déposer\nsuccessivement"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('38c6fc3f6d95', 'salade de lentilles et pousses d’épinards', null, 'printemps', 'avril', 4, 4, 'mardi', 'déjeuner/dîner léger', 'salé', 'épinards', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-lentilles-et-pousses-d-epinards.jpg', '[{"name": "1 boîte de conserve de lentilles", "canonical": true}, {"name": "1 poignée de pousses d’épinards frais", "canonical": true}, {"name": "4 radis", "canonical": true}, {"name": "10 noisettes", "canonical": true}, {"name": "Quelques feuilles de persil frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter et rincer les lentilles.", "Rincer et couper les radis en fines\nrondelles.", "Rincer et équeuter les feuilles\nd’épinards. Enlever les éventuelles\ntiges dures.", "Concasser les noisettes et couper\nle persil.", "Dans un bol, mélanger l’huile,", "Dans un saladier, mélanger tous"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ac3d72c439b7', 'lasagnes épinards et crème fraîche à la poêle', null, 'printemps', 'avril', 4, 4, 'mercredi', 'déjeuner/dîner', 'salé', 'épinards', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/lasagnes-epinards-et-creme-fraiche-a-la-poele.jpg', '[{"name": "6 pâtes à lasagnes", "canonical": true}, {"name": "1 barquette d’épinards (125g)", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. de beurre", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 c. à c. de muscade", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire une béchamel : verser\nle beurre dans une casserole\net ajouter la farine. Mélanger\npuis ajouter le lait petit à petit.\nMélanger en continu, la béchamel\ndoit épaissir. Saler, poivrer\net ajouter la muscade.", "Rincer et équeuter les feuilles\nd’épinards. Enlever les éventuelles\ntiges dures.", "Dans une grande poêle chaude\nhuilée, faire cuire", "Verser la béchamel dans la poêle\npuis ajouter les pâtes à lasagnes dans\nla préparation (les couper si besoin).", "Laisser cuire à feu moyen 30\nà 35 min ("]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e47966759748', 'verrines de saumon et avocat', null, 'printemps', 'avril', 4, 4, 'jeudi', 'apéritif/entrée', 'salé', 'épinards', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/verrines-de-saumon-et-avocat.jpg', '[{"name": "2 tranches de saumon fumé", "canonical": true}, {"name": "1 avocat", "canonical": true}, {"name": "1 petit suisse", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "1 c. à c. d’aneth séché", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un bol, mélanger le petit\nsuisse, l’ail en poudre, le jus\nde citron et l’aneth séché.\nSaler et poivrer.", "Couper le saumon fumé et\nl’avocat en dés.", "Dans un verre ou un grand\nbol, déposer successivement"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2e0b5557c662', 'quiche sans pâte, épinards et chèvre aumicro-ondes', null, 'printemps', 'avril', 4, 4, 'vendredi', 'déjeuner/dîner', 'salé', 'épinards', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/quiche-sans-pate-epinards-et-chevre-aumicro-ondes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "3 poignées de feuilles d’épinards", "canonical": true}, {"name": "4 tranches de bûche de chèvre", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "1 c. à s. de lait", "canonical": true}, {"name": "1 c. à c. d’ail en poudre", "canonical": true}, {"name": "1 c. à c. de muscade", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Quelques feuilles de menthe", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer et équeuter les feuilles\nd’épinards. Enlever les éventuelles\ntiges dures.", "Dans une poêle chaude huilée,\nfaire cuire", "Couper le fromage de chèvre\nen dés. Tailler finement la menthe.", "Dans un saladier, mélanger\nla farine, le lait, la crème\net les œufs. Saler et poivrer.", "Incorporer les épinards, la menthe\net le fromage de chèvre au mélange.", "Verser le tout dans un plat et faire\ncuire au micro-ondes pendant\n8 min à puissance maximale.\nquiche sans pâte,\népinards et chèvre\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('4e21486a90d9', 'banana bread au micro-ondes', null, 'printemps', 'avril', 4, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/banana-bread-au-micro-ondes.jpg', '[{"name": "1 banane (bien mûre)", "canonical": true}, {"name": "1 c. à s. de pépites de chocolat", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 c. à c. de lait", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}]'::jsonb, '["Écraser la banane à l’aide d’une\nfourchette.", "Dans un bol, mélanger tous\nles ingrédients. Faire cuire 1 min\nau micro-ondes à puissance\nmaximale.\nbanana bread\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('224160c4d300', 'blanc manger au pamplemousse', null, 'printemps', 'avril', 4, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/blanc-manger-au-pamplemousse.jpg', '[{"name": "1 pamplemousse", "canonical": true}, {"name": "1 grand verre de lait", "canonical": true}, {"name": "1 petit pot de fromage blanc", "canonical": true}, {"name": "1 feuille de gélatine", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}]'::jsonb, '["Faire tremper la gélatine dans\nun bol d’eau froide, puis l’essorer.", "Dans une casserole, faire\nchauffer", "Quand le lait commence\nà bouillir, enlever la casserole\ndu feu et ajouter la gélatine.\nFouetter afin de dissoudre\nla gélatine.", "Ajouter le fromage blanc\net mélanger à nouveau.", "Verser la préparation dans\n2 ramequins et réserver au frais\npendant environ 2h.", "Éplucher et couper\nle pamplemousse en petits\ncubes et les poser sur le blanc\nmanger lorsqu’il a pris.\nblanc manger\nau pamplemousse\n4\nTu peux réaliser cette\nrecette avec d’autres fruits de\nsaison (fraises, pommes, kiwis…)."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e36e7a90e136', 'fondant au chocolat au micro-ondes', null, 'printemps', 'avril', 4, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/fondant-au-chocolat-au-micro-ondes.jpg', '[{"name": "10 carreaux de chocolat", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "2 c. à s. bombées de farine", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "2 c. à c. d’extrait de vanille liquide", "canonical": true}]'::jsonb, '["Faire fondre le beurre\net 8 carreaux de chocolat\nau micro-ondes avec le\nprogramme décongélation.", "Dans un saladier, mélanger l’œuf,\nl’arôme de vanille et la farine.", "Ajouter le beurre et le chocolat\nfondu à la pâte. Bien mélanger.", "Verser la préparation dans\n2 ramequins.", "Faire cuire pendant 2 à 3 min au\nmicro-ondes puissance maximale.\nfondant au chocolat\nau micro-ondes\n1\nPour plus de coulant, tu\npeux mettre un carré de chocolat\nau centre de"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('694f41436089', 'poires pochées et coulis de framboises', null, 'printemps', 'avril', 4, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/poires-pochees-et-coulis-de-framboises.jpg', '[{"name": "2 poires", "canonical": true}, {"name": "½ citron", "canonical": true}, {"name": "2 c. à s. de sucre", "canonical": true}, {"name": "1 c. à c. d’extrait de vanille liquide", "canonical": true}, {"name": "1 verre d’eau", "canonical": true}, {"name": "4 c. à s. de coulis de framboises", "canonical": true}]'::jsonb, '["Pour le sirop : porter à ébullition\nle sucre et l’eau. Ajouter les\ntranches de citron et la vanille.", "Éplucher les poires, les couper\nen 2 et enlever le cœur. Les cuire\ndans le sirop porté à ébullition\npendant 20 min. Égoutter les\npoires et les laisser refroidir.", "Dresser la poire dans une assiette\net verser le coulis autour.\npoires pochées\net coulis\nde framboises\n3"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('651b1f67e6fa', 'salade d’agrumes et menthe', null, 'printemps', 'avril', 4, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-d-agrumes-et-menthe.jpg', '[{"name": "1 pamplemousse", "canonical": true}, {"name": "1 orange", "canonical": true}, {"name": "Quelques feuilles de menthe", "canonical": true}, {"name": "½ citron", "canonical": true}]'::jsonb, '["Éplucher et couper\nle pamplemousse et l’orange\nen dés.", "Tailler la menthe finement.", "Presser le jus de citron.", "Dans un bol mélanger tous les\ningrédients.\nsalade d’agrumes\net menthe\n2"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b92ae6e939df', 'radis rôtis au thym', null, 'printemps', 'mai', 5, 1, 'lundi', 'déjeuner/dîner', 'salé', 'radis', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/radis-rotis-au-thym.jpg', '[{"name": "½ botte de radis", "canonical": true}, {"name": "1 c. à c. de thym frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper les radis en 2.", "Dans une poêle, faire fondre\nle beurre et ajouter les radis.", "Ajouter le thym.\nSaler et poivrer.", "Lorsque les radis sont rôtis,\nservir.\nLes herbes\naromatiques comme le thym,\nen plus de donner du goût, sont\nbénéfiques pour la santé grâce\naux vitamines et anti‑oxydants\nqu’elles contiennent. Tu peux\ncompléter cette recette avec\ndu riz et des lentilles de ton choix."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c64f09b535af', 'tagliatelles sauce Alfredo', null, 'printemps', 'mai', 5, 1, 'mardi', 'déjeuner/dîner', 'salé', 'radis', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tagliatelles-sauce-alfredo.jpg', '[{"name": "1 poignée de tagliatelles", "canonical": true}, {"name": "Quelques tomates cerises", "canonical": true}, {"name": "1 oignon rouge", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "1 verre de crème liquide", "canonical": true}, {"name": "1 verre de vin blanc (EN OPTION)", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. de parmesan râpé", "canonical": true}, {"name": "1 c. à s. de beurre", "canonical": true}, {"name": "1 c. à s. de ciboulette fraîche (OU SÉCHÉE EN POT)", "canonical": true}, {"name": "1 c. à s. de basilic frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire cuire les pâtes dans une eau\nbouillante salée (temps de cuisson\nindiqué sur le paquet). Les égoutter.", "Éplucher, couper l’ail et l’oignon\nen dés.", "Dans une poêle huilée, faire revenir", "Une fois le vin porté à ébullition,\najouter le beurre et la farine.", "Une fois la farine et le beurre\nfondus, ajouter la crème et le lait.\nPuis ajouter la ciboulette hachée.", "Tout en remuant, baisser le feu\npour obtenir une sauce épaisse.", "Déposer la sauce sur les pâtes avec\nles feuilles de basilic, tomates cerises\ncoupées et le parmesan\nrâpé.\ntagliatelles\nsauce Alfredo"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('38daaf9ea9fe', 'salade de lentilles vertes', null, 'printemps', 'mai', 5, 1, 'mercredi', 'déjeuner/dîner léger', 'salé', 'radis', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-lentilles-vertes.jpg', '[{"name": "1 boîte de conserve de lentilles", "canonical": true}, {"name": "1 petite barquette de lardons", "canonical": true}, {"name": "3 radis", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter les lentilles.", "Laver et couper les radis\nen fines rondelles. Peler\net couper le demi oignon\nfinement.", "Dans une poêle chaude,\nfaire cuire", "Mélanger tous les ingrédients\ndans un saladier.\nsalade\nde lentilles vertes\nIl existe\nde nombreuses variétés\nd’oignons (rouges, blancs,\njaunes…) à différents prix."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('74c5809db8ed', 'omelette provençale', null, 'printemps', 'mai', 5, 1, 'jeudi', 'déjeuner/dîner', 'salé', 'radis', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/omelette-provencale.jpg', '[{"name": "4 œufs", "canonical": true}, {"name": "2 rondelles de bûche de chèvre", "canonical": true}, {"name": "6 tomates séchées", "canonical": true}, {"name": "10 olives noires dénoyautées", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 c. à c. d’herbes de Provence", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Couper les olives noires\nen rondelles, les tomates\nséchées et le fromage de chèvre\nen petits cubes.", "Dans un bol, casser les œufs\net les fouetter. Ajouter les\nherbes de Provence, les\nolives, le fromage de chèvre\net les tomates séchées. Poivrer.", "Dans une poêle chaude huilée,\nfaire cuire"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('79c043778a93', 'rouleaux de printemps', null, 'printemps', 'mai', 5, 1, 'vendredi', 'déjeuner/dîner', 'salé', 'radis', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/rouleaux-de-printemps.jpg', '[{"name": "3 feuilles de riz", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "3 rondelles de bûche de chèvre", "canonical": true}, {"name": "Quelques feuilles de laitue", "canonical": true}, {"name": "Quelques feuilles de menthe", "canonical": true}]'::jsonb, '["Mettre les feuilles de riz dans\nune assiette creuse remplie\nd’eau afin de les ramollir.\nLes essorer délicatement\nà la main.", "Laver, éplucher puis faire des\ntagliatelles de carotte à l’aide\nd’un épluche-légumes.", "Sur une feuille de riz, placer\nune feuille de laitue au centre,", "Enrouler la feuille de riz à partir\ndu bas, puis plier les côtés vers\nle centre et finir d’enrouler.", "Répéter les étapes 3 et 4\npour les 2 autres rouleaux\nde printemps.\nrouleaux\nde printemps\nCette recette est une\nversion végétarienne, tu peux\najouter du thon à la recette si\ntu le souhaites."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e8a8dac5b3a6', 'taboulé de chou-fleur', null, 'printemps', 'mai', 5, 2, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/taboule-de-chou-fleur.jpg', '[{"name": "½ chou-fleur", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "½ concombre", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "1 c. à s. de persil frais (OU SÉCHÉ EN POT) (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer le chou-fleur et le couper\ntrès finement pour en faire de\nla « semoule ».", "Laver, couper le concombre et\nla tomate en petits cubes. Peler\net couper le demi oignon.", "Dans un saladier, mélanger les\nlégumes, l’huile,"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0c2aa30d2368', 'cheesecake au saumon', null, 'printemps', 'mai', 5, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/cheesecake-au-saumon.jpg', '[{"name": "2 tranches de saumon fumé", "canonical": true}, {"name": "2 biscottes ou ¼ de baguette séchée et mixée", "canonical": true}, {"name": "3 c. à s. de ricotta", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à c. d’aneth frais (OU SÉCHÉ EN POT) (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de ciboulette fraiche (OU SÉCHÉE EN POT) (EN OPTION)", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Dans un bol, concasser les\nbiscottes. Laisser des morceaux.", "Faire fondre le beurre au\nmicro-ondes et le mélanger\naux biscottes. Tasser cette\npréparation au fond d’un plat.", "Dans un autre bol, mélanger\nla ricotta, le jus de citron,\nl’aneth et le poivre. Couper\nle saumon en petits cubes\net l’ajouter à la préparation.", "Verser la préparation sur\nles biscottes. Mettre au\nréfrigérateur au moins 3h\navant de le déguster.\ncheesecake\nau saumon\nAvec le saumon,\ntu fais le plein d’oméga 3 pour\noptimiser ta mémoire pendant des\npériodes de révision !"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('9917564ed5a2', 'galettes de lentilles corail et chèvre', null, 'printemps', 'mai', 5, 2, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/galettes-de-lentilles-corail-et-chevre.jpg', '[{"name": "4 c. à s. de lentilles corail crues", "canonical": true}, {"name": "2 tranches de bûche de chèvre", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de curry en poudre (EN OPTION)", "canonical": true}, {"name": "½ c. à c. de curcuma en poudre (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Couper le fromage de chèvre\nen petits cubes.", "Dans un bol, mélanger\nles lentilles corail, la farine,\nle fromage de chèvre\net 1 c. à c. d’huile d’olive.\nAjouter les épices.", "Former 2 galettes et les cuire\ndans une poêle chaude avec\n1 c. à c. d’huile d’olive.\ngalettes de lentilles\ncorail et chèvre\nAvec la farine et\ndes lentilles corail, tu apportes des\nglucides mais aussi des protéines\ncomplètes à ton corps ! Tu peux\ncompléter ce plat par le légume\nde saison de ton choix (asperges,\ncarottes, salade de mâche)."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e9e40a97ea2a', 'ballotines de volaille au basilic', null, 'printemps', 'mai', 5, 2, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/ballotines-de-volaille-au-basilic.jpg', '[{"name": "2 escalopes de dinde", "canonical": true}, {"name": "2 c. à s. de ricotta", "canonical": true}, {"name": "Quelques feuilles de basilic", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Assaisonner les escalopes avec\ndu sel et du poivre.", "Étaler la ricotta sur une face\nde l''escalope puis déposer\nquelques feuilles de basilic.", "Disposer les escalopes sur\ndu film alimentaire et les rouler\nen ballotines.", "Dans une casserole d’eau\nbouillante, cuire", "Retirer le film alimentaire et\nfaire dorer les ballotines dans\nune poêle chaude beurrée.\nballotines\nde volaille au basilic"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('61b797ce90d5', 'salade de quinoa et cerises', null, 'printemps', 'mai', 5, 2, 'vendredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-quinoa-et-cerises.jpg', '[{"name": "4 c. à s. de quinoa cru", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 cuillère à soupe de ricotta", "canonical": true}, {"name": "Des cerises (environ 10)", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "Des noisettes (environ 10)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une autre casserole d’eau\nbouillante, faire cuire", "Laver, dénoyauter les cerises\net les couper en 2. Couper\nla carotte lavée et le demi\noignon pelé en petits cubes.\nConcasser les noisettes.", "Mélanger l''huile, le vinaigre,\nle sel et le poivre pour réaliser\nla vinaigrette. Dans un saladier,\nmélanger l''ensemble des\ningrédients avec la vinaigrette.\nsalade de quinoa\net cerises\nLe quinoa fait\npartie de la famille des féculents.\nIl se cuit facilement dans\nde l’eau bouillante pendant\nquelques minutes. C’est une bonne\nalternative aux pâtes ou au riz."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8b87303e4c48', 'couscous de printemps', null, 'printemps', 'mai', 5, 3, 'lundi', 'déjeuner/dîner', 'salé', 'petits pois', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/couscous-de-printemps.jpg', '[{"name": "1 verre de semoule", "canonical": true}, {"name": "2 c. à s. de petits pois frais (ou en conserve ou surgelés)", "canonical": true}, {"name": "2 asperges fraîches", "canonical": true}, {"name": "½ boîte de conserve de fèves", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Si les petits pois sont frais,\nles enlever de leur cosse\n(enveloppe).", "Verser la semoule dans un\nsaladier. Ajouter 1 c. à c. d’huile,\nsaler et poivrer. Faire bouillir\n1 verre d’eau avec du sel. Verser\nl’eau sur la semoule. Couvrir et\nlaisser gonfler pendant 10 min.\nÉgrainer avec une fourchette.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Égoutter les fèves.", "Mélanger les légumes,\nla semoule et 1 c. à c. d’huile.\nSaler et poivrer."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('84dc3727cb7f', 'hachis parmentier de poisson blanc', null, 'printemps', 'mai', 5, 3, 'mardi', 'déjeuner/dîner', 'salé', 'petits pois', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/hachis-parmentier-de-poisson-blanc.jpg', '[{"name": "2 pommes de terre moyennes", "canonical": true}, {"name": "¼ de verre de lait", "canonical": true}, {"name": "1 filet de poisson blanc", "canonical": true}, {"name": "Quelques feuilles de persil (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de muscade en poudre (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper en\nrondelles", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une autre casserole d’eau\nbouillante, faire cuire", "Dans un plat, écraser le poisson\nà l’aide d’une fourchette\net ajouter le persil coupé.", "Dans un bol, écraser les\npommes de terre et"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ef2887c96ee8', 'bagel aux petits pois et œuf', null, 'printemps', 'mai', 5, 3, 'mercredi', 'déjeuner/dîner', 'salé', 'petits pois', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/bagel-aux-petits-pois-et-oeuf.jpg', '[{"name": "1 pain à bagel", "canonical": true}, {"name": "2 c. à s. de petits pois frais (OU EN CONSERVE OU SURGELÉS)", "canonical": true}, {"name": "½ boîte de conserve de fèves", "canonical": true}, {"name": "1 c. à s. de ricotta", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "2 c. à c. de jus de citron", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Si les petits pois sont frais, les\nenlever de leur cosse (enveloppe).", "Dans une casserole d’eau\nbouillante salée, faire cuire les\npetits pois pendant 7 min. Les\négoutter.", "Égoutter les fèves.", "Écraser les fèves et les petits\npois à l’aide d’une fourchette.\nAjouter le jus de citron et la\nricotta. Saler et poivrer.", "Dans une poêle chaude\nbeurrée, casser", "Faire griller le pain à bagel à la\npoêle ou au grille-pain.", "Étaler la préparation de fèves et\npetits pois sur les 2 parties du\npain. Ajouter l’œuf au plat et\nrefermer le bagel.\nbagel aux petits pois\net œuf\nTu peux remplacer l’œuf\npar une tranche de jambon, à\nprivilégier sans nitrites."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2b3be09bb5d3', 'steak aux herbes', null, 'printemps', 'mai', 5, 3, 'jeudi', 'déjeuner/dîner', 'salé', 'petits pois', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/steak-aux-herbes.jpg', '[{"name": "1 steak haché frais (ou 100g de viande hachée)", "canonical": true}, {"name": "1 dizaine de feuilles de persil", "canonical": true}, {"name": "1 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper finement le persil.", "Dans un bol, écraser la viande\nhachée à la fourchette. Ajouter\nle persil et le fromage râpé.\nSaler et poivrer.", "Former un steak et le faire\ncuire dans une poêle huilée\ndes 2 côtés.", "Tu peux accompagner le steak\naux herbes avec des restes\nde petits pois et de fèves.\nsteak aux herbes\nS’il te reste un œuf,\ndu pain dur ou des herbes qui\ncommencent à s’abîmer, tu peux\nles ajouter dans la préparation."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0550b7a83466', 'riz pilao des comores', null, 'printemps', 'mai', 5, 3, 'vendredi', 'déjeuner/dîner', 'salé', 'petits pois', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/riz-pilao-des-comores.jpg', '[{"name": "2 verres de riz", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "3 verres d’eau", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "½ c. à c. de cannelle", "canonical": true}, {"name": "½ c. à c. de cumin", "canonical": true}, {"name": "½ c. à c. de gingembre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper l’oignon et la tomate en\npetits dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Incorporer le riz. Mélanger\n1 à 2 min pour que le riz soit\ntranslucide. Ajouter 3 verres\nd’eau.", "Laisser cuire à feu doux\npendant 17 min avec\nun couvercle. Remuer\nrégulièrement.\nriz pilao des comores"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0ed8726826fb', 'linguines à l’ artichaut', null, 'printemps', 'mai', 5, 4, 'lundi', 'déjeuner/dîner', 'salé', 'cœurs d''artichauts', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/linguines-a-l-artichaut.jpg', '[{"name": "1 bocal de cœurs d’artichauts", "canonical": true}, {"name": "2 poignées de linguines", "canonical": true}, {"name": "1 c. à s. de parmesan", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d''eau\nbouillante salée, faire cuire", "Égoutter les cœurs d’artichauts.", "Dans une poêle, faire griller les\ncœurs d’artichauts", "Servir les linguines avec\nles cœurs d’artichauts.\nParsemer de parmesan.\nlinguines\nà l’ artichaut\nTu peux remplacer\nle parmesan par de l’emmental\nrâpé. Le fromage est riche\nen protéines. Il permet d’ajouter\nun apport en protéines à ton plat."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('20fbeb428353', 'rillettes de thon au basilic', null, 'printemps', 'mai', 5, 4, 'mardi', 'apéritif/entrée', 'salé', 'cœurs d''artichauts', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/rillettes-de-thon-au-basilic.jpg', '[{"name": "1 boîte de thon", "canonical": true}, {"name": "4 tranches de pain de mie", "canonical": true}, {"name": "1 c. à s. de crème fraîche", "canonical": true}, {"name": "2 c. à c. de fromage blanc", "canonical": true}, {"name": "Quelques feuilles fraîches de basilic (EN OPTION)", "canonical": true}, {"name": "Le jus d’ ½ citron", "canonical": true}, {"name": "1 c. à c. de moutarde à l’ancienne (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper finement les feuilles\nde basilic.", "Dans un saladier, ajouter tous\nles ingrédients. Saler et poivrer.\nMélanger jusqu’à obtenir\nune texture homogène.", "À la poêle avec du beurre\n(ou au grille-pain) faire griller\nles tranches de pain de mie.", "Disposer la rillette sur\nles tranches de pain de mie.\nAjouter une pincée de curry.\nrillettes de thon\nau basilic\nTu peux remplacer\nla crème fraîche par le fromage\nblanc. Le fromage blanc est un\nindispensable à avoir dans ses\nplacards : riche en protéines,\nil se consomme au petit déjeuner,\nau goûter ou dans des sauces\nau citron."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a65aa5e307ae', 'poulet sauce aux olives', null, 'printemps', 'mai', 5, 4, 'mercredi', 'déjeuner/dîner', 'salé', 'cœurs d''artichauts', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poulet-sauce-aux-olives.jpg', '[{"name": "1 escalope de poulet", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "10 olives noires", "canonical": true}, {"name": "10 olives vertes", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. d’origan en poudre (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper le poulet en lamelles.", "Peler et couper l’ail et l’oignon.", "Dans une poêle huilée, faire\ncuire", "Dénoyauter les olives si besoin.\nLes verser dans la poêle puis\najouter le coulis de tomate.", "Ajouter l’origan, saler et poivrer.\npoulet\nsauce aux olives\nTu peux en préparer\nd’avance en multipliant les\nquantités. Idéal pour amener son\nrepas le lendemain midi dans un\nbento."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ce777e484828', 'salade orange', null, 'printemps', 'mai', 5, 4, 'jeudi', 'déjeuner/dîner léger', 'salé', 'cœurs d''artichauts', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-orange.jpg', '[{"name": "2 verres de lentilles corail crues", "canonical": true}, {"name": "2 carottes", "canonical": true}, {"name": "¼ de melon", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "3 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "½ c. à c. de curcuma", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire les\nlentilles corail pendant 7 min.", "Éplucher les carottes et\nfaire des tagliatelles à l’aide\nd’un épluche-légumes. Couper\nle melon en petits dés. Peler\net couper l’échalotte en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Disposer et mélanger tous les\ningrédients dans un saladier."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('16396725a4e3', 'tartinade d''artichaut', null, 'printemps', 'mai', 5, 4, 'vendredi', 'apéritif/entrée', 'salé', 'cœurs d''artichauts', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tartinade-d-artichaut.jpg', '[{"name": "1 petit bocal de cœurs d’artichauts", "canonical": true}, {"name": "Quelques feuilles de persil", "canonical": true}, {"name": "1 c. à c. d’huile de colza", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter les cœurs d''artichauts.", "Couper en petits dés les cœurs\nd''artichauts.", "Couper finement le persil.", "Dans un récipient, écraser\nles cœurs d’artichauts à l’aide\nd’une fourchette. Ajouter\nle persil, l’huile, saler et poivrer.\ntartinade\nd''artichaut"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('af3073903bac', 'biscuits aux flocons d’avoine', null, 'printemps', 'mai', 5, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNES', null, null, '/assets/recipe_images/pexels/biscuits-aux-flocons-d-avoine.jpg', '[{"name": "3 c. à s. de flocons d’avoine", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "½ c. à c. de cannelle", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}]'::jsonb, '["Mélanger l’ensemble\ndes ingrédients dans un bol\net former des biscuits à l''aide\nd''une cuillère à soupe.", "Dans une poêle huilée, faire\ncuire"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ba25b3dbaaa8', 'clafoutis à la cerise au micro-ondes', null, 'printemps', 'mai', 5, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/clafoutis-a-la-cerise-au-micro-ondes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "10 cerises", "canonical": true}, {"name": "1 petit verre de lait", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nles œufs, le sucre et la farine.\nVerser le lait petit à petit\net mélanger.", "Couper les cerises en 2\net retirer le noyau.", "Déposer les cerises au fond\nde 2 ramequins et verser le\nmélange aux œufs par-dessus.", "Cuire 5 min au micro-ondes\npuissance maximale, puis 5 min\nde plus.\nEn hiver,"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5c03ae306737', 'gâteau au chocolat sans cuisson', null, 'printemps', 'mai', 5, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gateau-au-chocolat-sans-cuisson.jpg', '[{"name": "8 carrés de chocolat pâtissier", "canonical": true}, {"name": "2 jaunes d’œufs", "canonical": true}, {"name": "2 petits-beurre", "canonical": true}, {"name": "3 c. à s. de beurre", "canonical": true}, {"name": "2 c. à c. de sucre", "canonical": true}]'::jsonb, '["Faire fondre le chocolat et\nle beurre au micro-ondes,\nen mode décongélation.", "Casser les œufs et séparer\nle jaune du blanc.", "Dans un saladier, mélanger\nle sucre et les jaunes d’œufs.", "Émietter les petits-beurre et\nles ajouter à la préparation.\nAjouter le mélange\nchocolat-beurre.", "Verser le tout dans un petit plat\net laisser au freezer au moins\n1h30 puis au réfrigérateur 2h.\ngâteau au chocolat\nsans cuisson\n1"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('48fa8112824d', 'pain brioché à la poêle', null, 'printemps', 'mai', 5, null, null, 'petit déjeuner', 'sucré', null, 'POUR 4 PAINS BRIOCHÉS', null, null, '/assets/recipe_images/pexels/pain-brioche-a-la-poele.jpg', '[{"name": "Pépites de chocolat", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "30g de compote de pommes (1/3 d’un petit pot)", "canonical": true}, {"name": "9 c. à s. de farine", "canonical": true}, {"name": "1 c. à c. d’huile de colza", "canonical": true}, {"name": "2 c. à c. de levure chimique", "canonical": true}, {"name": "1 noisette de beurre (pour la cuisson)", "canonical": true}, {"name": "Sel", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nl’ensemble des ingrédients,\nen commençant par", "Mélanger à la main jusqu’à obtenir\nune boule de pâte légèrement\ncollante. Séparer la pâte en 4.", "Dans une poêle légèrement\nbeurrée, déposer", "Faire cuire à feu doux environ\n5 min de chaque côté.\npain brioché\nà"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8715ddb2d61c', 'verrines fraise et rhubarbe', null, 'printemps', 'mai', 5, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/verrines-fraise-et-rhubarbe.jpg', '[{"name": "1 tige de rhubarbe", "canonical": true}, {"name": "12 fraises", "canonical": true}, {"name": "3 c. à s. de fromage blanc", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "2 c. à s. de sucre", "canonical": true}, {"name": "1 c. à s. d’eau", "canonical": true}]'::jsonb, '["Laver et couper la rhubarbe\nen petits morceaux.", "Dans une casserole chaude,\nfaire cuire", "Dans un bol, mélanger\nle fromage blanc, le jus\nde citron et 1 c. à s. de sucre.", "Laver et couper les fraises\nen cubes.", "Dans la casserole chaude,\nmélanger les fraises crues\navec la compotée de rhubarbe.", "Dans 2 verrines, verser\nla compotée fraise/rhubarbe\net le fromage blanc en alternant\nles couches.\nverrines fraise\net rhubarbe\nLa rhubarbe, fruit\nemblématique du printemps,\nest riche en vitamines."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2036b7f00897', 'flan à la courgette au micro-ondes', null, 'printemps', 'juin', 6, 1, 'lundi', 'déjeuner/dîner', 'salé', 'fenouil', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/flan-a-la-courgette-au-micro-ondes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "1 c. à s. d’emmental râpé", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "½ c. à c. de curry en poudre (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, découper le demi\noignon et la courgette en dés.", "Dans un bol, mélanger les œufs,\nl’emmental râpé, la crème\nliquide et le curry. Ajouter\nla courgette et l’oignon. Saler\net poivrer.", "Verser la préparation dans\n2 ramequins (adaptés à\nla cuisson au micro-ondes).", "Faire cuire 10 min puissance\nmaximale au micro-ondes tout\nen surveillant."]'::jsonb, 'la courgette au micro-ondes LUNDI', true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a9484a38d4d8', 'salade de fenouil', null, 'printemps', 'juin', 6, 1, 'mardi', 'déjeuner/dîner léger', 'salé', 'fenouil', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-fenouil.jpg', '[{"name": "½ fenouil", "canonical": true}, {"name": "½ grenade", "canonical": true}, {"name": "½ orange", "canonical": true}, {"name": "½ bloc de feta", "canonical": true}, {"name": "2 c. à c. d’huile de colza", "canonical": true}, {"name": "1 c. à c. de jus de citron", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper le fenouil\nen fines lamelles. Éplucher\net enlever les grains de la\ngrenade. Peler et couper\nl’orange en lamelles.", "Couper la feta en dés.", "Dans un saladier, mélanger\nle fenouil, l’orange, la grenade\net la feta.", "Ajouter l’huile de colza et le jus\nde citron. Saler et poivrer.\nsalade de fenouil"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('496e8f7e378a', 'samoussas au thon', null, 'printemps', 'juin', 6, 1, 'mercredi', 'déjeuner/dîner', 'salé', 'fenouil', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/samoussas-au-thon.jpg', '[{"name": "1 boîte de thon au naturel de 265g", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 fromage frais", "canonical": true}, {"name": "4 feuilles de brick (COUPÉES EN 2 SOIT 8 SAMOUSSAS)", "canonical": true}, {"name": "½ cuillère à café de curry en poudre (EN OPTION)", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Peler et couper en dés l’oignon\net l’ail.", "Dans un saladier, mélanger\nle thon, l’ail, l’oignon,\nle fromage frais et le curry.", "Découper des feuilles de brick\nen 2. Replier", "Garnir la feuille de brick et\nla plier en forme de triangle\net refermer le samoussa.", "Dans une poêle chaude huilée,\nfaire dorer"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6b87f8d6b37d', 'fenouil gratiné au bacon', null, 'printemps', 'juin', 6, 1, 'jeudi', 'déjeuner/dîner', 'salé', 'fenouil', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/fenouil-gratine-au-bacon.jpg', '[{"name": "½ fenouil", "canonical": true}, {"name": "5 tranches de filet de bacon", "canonical": true}, {"name": "1 c. à s. de fromage râpé", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper le fenouil\nen morceaux.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Couper le bacon en lamelles\net le faire griller dans une poêle.", "Lorsque le fenouil est cuit,\nl’égoutter et le mettre dans\nun plat (adapté à la cuisson\nau micro-ondes). Ajouter\nle bacon et la crème liquide.\nSaler et poivrer.", "Ajouter le fromage râpé par-\ndessus. Faire fondre 3 min\nau micro-ondes.\nfenouil gratiné\nau bacon\nLes filets de\nbacon (rondelles) sont moins\ngras que le bacon (lanières)."]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('23402883f6d3', 'bruschetta de tomate et abricot', null, 'printemps', 'juin', 6, 1, 'vendredi', 'déjeuner/dîner', 'salé', 'fenouil', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/bruschetta-de-tomate-et-abricot.jpg', '[{"name": "1 tomate", "canonical": true}, {"name": "1 abricot", "canonical": true}, {"name": "1 tranche de pain de campagne", "canonical": true}, {"name": "2 fromages type carré frais", "canonical": true}, {"name": "½ c. à c. d’huile de colza", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en tranches\nla tomate et l’abricot.", "Faire griller le pain à la poêle\navec du beurre (ou au grille-\npain).", "Étaler le fromage frais sur\nla tartine. Ajouter les tranches\nde tomate et d''abricot,\nles herbes de Provence et l’huile\nde colza. Saler et poivrer.\nbruschetta\nde tomate et abricot\nTu peux utiliser\nde l’huile de colza pour\nassaisonner les salades. C’est\nune source d’oméga 3 assez\néconomique, utile pour booster\nsa concentration et sa mémoire."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f0eaa8e943c9', 'millefeuille de betterave et bacon grillé', null, 'printemps', 'juin', 6, 2, 'lundi', 'déjeuner/dîner', 'salé', 'betterave', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/millefeuille-de-betterave-et-bacon-grille.jpg', '[{"name": "1 betterave cuite", "canonical": true}, {"name": "10 tranches de filet de bacon", "canonical": true}, {"name": "5 c. à s. de fromage de chèvre frais", "canonical": true}, {"name": "2 c. à c. de persil séché (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper la betterave en fines\nlamelles.", "Dans une poêle chaude, faire\ngriller", "Mélanger le fromage de chèvre\nfrais avec le persil. Saler\net poivrer.", "Dans une assiette, dresser\nle millefeuille en alternant\nles couches de betterave,\nbacon et fromage de chèvre.\nmillefeuille\nde betterave\net bacon grillé\nTu peux remplacer le\nfromage de chèvre frais par un\nfromage frais."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('06988833c621', 'cheesecake au saumon', null, 'printemps', 'juin', 6, 2, 'mardi', 'déjeuner/dîner', 'salé', 'betterave', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/cheesecake-au-saumon.jpg', '[{"name": "1 filet de poisson blanc", "canonical": true}, {"name": "2 c. à s. de chapelure ou pain dur mixé", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans 3 assiettes différentes,\nverser", "Saler, poivrer et ajouter le curry\ndans la farine. Bien mélanger.", "Passer le filet de poisson dans\nla farine, puis dans l’œuf et\nenfin dans la chapelure.", "Dans une poêle chaude huilée,\nfaire cuire"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('869c643d9257', 'salade de pâtes printanières', null, 'printemps', 'juin', 6, 2, 'mercredi', 'déjeuner/dîner léger', 'salé', 'betterave', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-pates-printanieres.jpg', '[{"name": "4 petits verres de pâtes crues", "canonical": true}, {"name": "4 c. à s. de pois chiches en boîte", "canonical": true}, {"name": "1 betterave cuite", "canonical": true}, {"name": "1 oignon rouge", "canonical": true}, {"name": "½ bloc de feta", "canonical": true}, {"name": "4 c. à c. d’huile de colza", "canonical": true}, {"name": "2 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Couper la betterave et la feta\nen dés. Éplucher et tailler\nfinement l’oignon rouge.", "Égoutter les pois chiches.", "Dans un saladier, mélanger\ntous"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7a8796ead7af', 'riz sauté aux légumes', null, 'printemps', 'juin', 6, 2, 'jeudi', 'déjeuner/dîner', 'salé', 'betterave', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/riz-saute-aux-legumes.jpg', '[{"name": "1 verre de riz", "canonical": true}, {"name": "2 champignons de Paris", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 petite boîte de petits pois", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Peler et couper en dés l’oignon,\nl’ail, les champignons et la carotte.", "Égoutter les petits pois.", "Dans une poêle huilée,\nfaire cuire", "Ajouter le riz et la sauce soja\ndans la poêle. Poivrer. Mélanger.\nriz sauté aux légumes"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cfb5f83b2b87', 'chips de betterave au micro ondes', null, 'printemps', 'juin', 6, 2, 'vendredi', 'déjeuner/dîner', 'salé', 'betterave', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/chips-de-betterave-au-micro-ondes.jpg', '[{"name": "1 betterave", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper la betterave en fines\nlamelles.", "Poser les lamelles de betterave\nsur un papier absorbant dans\nune assiette. Les badigeonner\nd’huile. Saler et poivrer.", "Faire cuire 4 min au\nmicro-ondes en vérifiant\nrégulièrement", "Enlever le papier absorbant\net refaire cuire 2 min\nsupplémentaires.\nchips de betterave\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c3a2cb033f43', 'nuggets de poulet au curry', null, 'printemps', 'juin', 6, 3, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/nuggets-de-poulet-au-curry.jpg', '[{"name": "2 escalopes de dinde", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "3 c. à s. de chapelure", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 verre d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de curry en poudre (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Mettre la farine, la chapelure\net les œufs battus dans 3\nassiettes différentes. Ajouter\ndu curry dans la chapelure.\nSaler et poivrer la farine.", "Couper les escalopes de dinde\nen gros dés. Rouler les dés dans\nla farine, puis dans l’œuf et dans\nla chapelure.", "Dans une poêle bien chaude\nhuilée, déposer", "Laisser cuire 1 à 2 min\n(en fonction de", "Égoutter les nuggets sur\ndu papier absorbant."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e073b8857e28', 'poêlée de haricots verts à l’ail', null, 'printemps', 'juin', 6, 3, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/poelee-de-haricots-verts-a-l-ail.jpg', '[{"name": "½ boîte de haricots en conserve de 400g", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Peler et couper l’ail en dés.", "Égoutter les haricots.", "Dans une poêle huilée, faire\ncuire l’ail et"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6a6793e8d9ea', 'salade de riz', null, 'printemps', 'juin', 6, 3, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-riz.jpg', '[{"name": "2 petits verres de riz", "canonical": true}, {"name": "4 œufs", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "½ concombre", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante, faire cuire", "Dans une autre casserole d’eau\nbouillante salée, faire cuire", "Laver et couper les légumes\nen dés.", "Dans un saladier, mélanger le\nriz et"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8513d5de271b', 'one pot quinoa', null, 'printemps', 'juin', 6, 3, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/one-pot-quinoa.jpg', '[{"name": "2 petits verres de quinoa", "canonical": true}, {"name": "1 poignée d’épinards frais", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "1 courgette", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 petit verre de coulis de tomate", "canonical": true}, {"name": "4 petits verres d’eau", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer les épinards. Enlever\néventuellement les tiges dures.", "Laver et couper le poivron et\nla courgette en petits dés. Peler\net couper l’oignon finement.", "Dans une casserole chaude\nhuilée, faire cuire", "Le liquide doit être totalement\nabsorbé. Si les ingrédients\nne sont pas encore cuits\naprès l’évaporation de\nl’eau, en rajouter un peu\net poursuivre la cuisson.\none pot quinoa\nLe one pot quinoa\nest déclinable à souhait : ajouter\ndu bouillon, des légumes, du\nfromage… et le plat cuit tout seul."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('917d17c58a60', 'avocat farci au thon', null, 'printemps', 'juin', 6, 3, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/avocat-farci-au-thon.jpg', '[{"name": "2 avocats", "canonical": true}, {"name": "1 petite boîte de thon", "canonical": true}, {"name": "2 c. à s. de fromage frais", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Dans un bol, mélanger le thon\net le fromage frais. Poivrer.", "Couper les avocats en 2,\nenlever le noyau. Farcir avec\nla préparation au thon à\nla place du noyau.\navocat farci au thon\nTu peux farcir\nd’autres légumes avec la\npréparation au thon : courgettes,\nconcombre…"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('17830560e668', 'gratin de blettes et sardines au micro-ondes', null, 'printemps', 'juin', 6, 4, 'lundi', 'déjeuner/dîner', 'salé', 'blettes', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gratin-de-blettes-et-sardines-au-micro-ondes.jpg', '[{"name": "4 branches de blettes", "canonical": true}, {"name": "1 boîte de sardines", "canonical": true}, {"name": "2 petits verres de lait", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. d’emmental râpé", "canonical": true}, {"name": "Une noisette de beurre", "canonical": true}, {"name": "1 c. à c. de muscade en poudre (EN OPTION)", "canonical": true}, {"name": "Sel et poivree", "canonical": true}]'::jsonb, '["Séparer les feuilles des côtes\nde blettes. Couper les côtes\nen morceaux et les feuilles\nen lamelles.", "Dans une casserole d’eau\nbouillante salée, faire cuire les\nblettes entières (côtes + feuilles)\npendant 10 à 15 min.", "Préparer une béchamel : dans une\ncasserole, faire chauffer", "Égoutter les sardines.", "Dans un plat adapté à la cuisson\nau micro-ondes, alterner\nles couches de blettes, béchamel\net sardines dans un plat.", "Ajouter le fromage râpé\npar‑dessus et faire chauffer au\nmicro‑ondes 2 min pour que\nle fromage fonde.\ngratin de blettes\net sardines\nau micro-ondes\nTout se mange dans\nles blettes, sauf la racine ! Le vert\ndes feuilles et les côtes servent à\npréparer de bons plats."]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b97a4324f012', 'mugcake à la courgette', null, 'printemps', 'juin', 6, 4, 'mardi', 'déjeuner/dîner', 'salé', 'blettes', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/mugcake-a-la-courgette.jpg', '[{"name": "¼ de courgette", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "3 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. de lait", "canonical": true}, {"name": "1 c. à s. de mozzarella râpée", "canonical": true}, {"name": "½ c. à c. de curry en poudre (EN OPTION)", "canonical": true}, {"name": "¼ de c. à c. de levure chimique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper\nla courgette en petits dés.", "Dans un saladier, mélanger\nl’œuf et le lait. Ajouter\nprogressivement la farine\nafin d’éviter les grumeaux.\nAjouter la levure.", "Mélanger tous les ingrédients\net les verser dans un mug.", "Cuire 2 min au micro-ondes\nà puissance maximale.\nmugcake\nà"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c8187e33c217', 'spaghettis de printemps', null, 'printemps', 'juin', 6, 4, 'mercredi', 'déjeuner/dîner', 'salé', 'blettes', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/spaghettis-de-printemps.jpg', '[{"name": "2 poignées de spaghettis", "canonical": true}, {"name": "¾ de courgette", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "2 c. à s. de mozzarella râpée", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "4 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et découper la courgette\net la carotte en bâtonnets fins.", "Éplucher et couper l’ail en dés.", "Dans une casserole d’eau\nbouillante, faire cuire", "Dans une autre casserole\nd’eau bouillante, faire cuire", "Dans une poêle chaude\nhuilée, faire cuire l’ail.", "Casser l’œuf et séparer le jaune\ndu blanc.", "Déposer le mélange dans une\nassiette, ajouter un jaune d’œuf\net un peu de mozzarella\nrâpée.\nspaghettis\nde printemps\nMarre de la\nbolognaise ? Cette recette permet\nde varier les sauces de tes pâtes."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ee2e07c81230', 'blettes farcies au poulet ', null, 'printemps', 'juin', 6, 4, 'jeudi', 'déjeuner/dîner', 'salé', 'blettes', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/blettes-farcies-au-poulet.jpg', '[{"name": "1 filet de poulet", "canonical": true}, {"name": "3 feuilles de blettes", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 c. à c. de coriandre séchée (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Séparer les feuilles de blettes.\nCouper la côte et les feuilles\nde blettes en dés.", "Dans une poêle chaude\nhuilée, faire cuire uniquement", "Couper le poulet en petits dés\net l’ajouter dans la poêle. Faire\nrevenir pendant 5 à 7 min.\nAjouter de l’eau si le mélange\naccroche. Saler et poivrer.", "Farcir les feuilles de blettes avec\nle mélange et les replier sur\nelles-mêmes.\nblettes farcies\nau poulet"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0ca85a564c9d', 'boulettes de quinoa et légumes', null, 'printemps', 'juin', 6, 4, 'vendredi', 'déjeuner/dîner', 'salé', 'blettes', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/boulettes-de-quinoa-et-legumes.jpg', '[{"name": "1 verre de quinoa cru", "canonical": true}, {"name": "1 petite courgette", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "2 c. à c. de coriandre séchée (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de curry en poudre (EN OPTION)", "canonical": true}, {"name": "4 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Laver, éplucher et couper en dés", "Dans une poêle chaude avec\n2 c. à c. d’huile, faire cuire", "Dans un saladier, mélanger\nle quinoa cuit, les légumes cuits,\nl’œuf, la farine, le curry et la\ncoriandre. Saler et poivrer.", "Former des boulettes.", "Dans une poêle chaude avec\n2 c. à c. d’huile, faire dorer"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('93dba3927d86', 'cheesecake à la framboise', null, 'printemps', 'juin', 6, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/cheesecake-a-la-framboise.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "4 c. à c. de cacao en poudre", "canonical": true}, {"name": "7 c. à s. de farine", "canonical": true}, {"name": "6 c. à s. de sucre", "canonical": true}, {"name": "5 c. à s. de beurre", "canonical": true}, {"name": "½ sachet de levure", "canonical": true}, {"name": "3 c. à s. de lait", "canonical": true}]'::jsonb, '["Dans un bol, faire fondre\nle beurre au micro-ondes,\nen mode décongélation.", "Dans un saladier, casser les\nœufs et", "Diviser la préparation dans\n2 saladiers différents. Ajouter\nle cacao et 2 c. à s. de lait dans\nune des préparations.", "Verser en alternance\nles 2 préparations dans\ndes ramequins beurrés.", "Couvrir les ramequins avec\ndu film alimentaire. Cuire\nla préparation au bain-marie\npendant 15 min (pour cette\npartie, la vidéo t’aidera).\ngâteau marbré\ncuit à la vapeur\n1"]'::jsonb, null, true, true, 'crous', 'Calendrier Recettes Printemps.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('733ab24827f2', 'crêpes express et fruits', null, 'printemps', 'juin', 6, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/crepes-express-et-fruits.jpg', '[{"name": "1 pêche", "canonical": true}, {"name": "2 à 3 fraises", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 verre de farine", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nle lait, l’œuf, la farine et le sucre.", "Dans une poêle chaude,\nverser l’huile et l’étaler à l’aide\nd’un papier absorbant.", "Déposer la pâte dans la poêle\nà l’aide d’une louche ou\nd’un verre.", "Cuire les crêpes\nquelques minutes de chaque\ncôté.", "Couper les fruits en dés et\nles déposer sur les crêpes.\ncrêpes express\net fruits\ndu mois de juin"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c3a28923dd6d', 'gâteau marbré cuit à la vapeur', null, 'printemps', 'juin', 6, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gateau-marbre-cuit-a-la-vapeur.jpg', '[{"name": "5 carrés de chocolat pâtissier", "canonical": true}, {"name": "6 spéculoos", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. de sucre blanc", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "½ c. à c. de cannelle en poudre (EN OPTION)", "canonical": true}]'::jsonb, '["Dans un bol, faire fondre le\nchocolat et", "Dans le bol, ajouter le sucre,\nla cannelle et la crème liquide.\nBien mélanger. Ajouter l’œuf\net fouetter jusqu’à obtention\nd’une crème bien lisse.", "Mettre du film plastique\nau fond d’un plat. Alterner", "Replier le film plastique\nsur le dessus.", "Placer au réfrigérateur\nau moins 3h.\nterrine chocolat\net spéculoos\n3"]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3202306eef6e', 'salade de fruits de printemps', null, 'printemps', 'juin', 6, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-fruits-de-printemps.jpg', '[{"name": "1 biscotte ou ¼ de baguette séchée et mixée", "canonical": true}, {"name": "2 poignées de framboises", "canonical": true}, {"name": "Quelques feuilles de menthe (EN OPTION)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "3 c. à s. de mascarpone", "canonical": true}]'::jsonb, '["Dans un bol, casser en petits\nmorceaux", "Faire fondre le beurre au micro-\nondes en mode décongélation\net le mélanger à la biscotte.\nTasser cette préparation\nau fond d’un plat.", "Dans un autre bol, mélanger\nle mascarpone, le jus de citron,\nla menthe coupée en morceaux\net les framboises.", "Verser la préparation\nsur la biscotte. Mettre\nau réfrigérateur au moins 3h\navant dégustation.\ncheesecake\nà la framboise\n2\nTu peux refaire\ncette recette avec des fraises,\ndes cerises ou des myrtilles."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('57160ef5d6f0', 'terrine chocolat et spéculoos', null, 'printemps', 'juin', 6, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/terrine-chocolat-et-speculoos.jpg', '[{"name": "1 pêche", "canonical": true}, {"name": "3 abricots", "canonical": true}, {"name": "1 poignée de framboises", "canonical": true}, {"name": "Quelques feuilles de menthe fraîche (EN OPTION)", "canonical": true}]'::jsonb, '["Laver, couper la pêche et\nles abricots en morceaux.", "Couper finement la menthe.", "Mélanger les fruits et la menthe\ndans un bol.\nsalade de fruits\nde printemps\n4\nAjoute des amandes,\ndes noix ou des noisettes à cette\nrecette pour ajouter un côté\ncroquant."]'::jsonb, null, false, true, 'crous', 'Calendrier Recettes Printemps.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cfbee8480ed8', 'Chakchouka aux pois chiches', null, 'été', 'juillet', 7, 1, 'lundi', 'déjeuner/dîner', 'salé', 'poivron', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/chakchouka-aux-pois-chiches.jpg', '[{"name": "1 poivron rouge", "canonical": true}, {"name": "1 bocal de tomates concassées", "canonical": true}, {"name": "1 petite boîte de conserve de pois chiches", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "½ c. à c de cumin", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Quelques feuilles de coriandre fraîche", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher puis couper l’oignon\net le poivron en fines lamelles.", "Dans une poêle chaude huilée,\nles faire cuire pendant 5 min.\nBien mélanger. Ajouter de l’eau\nsi les légumes accrochent.", "Ajouter le bocal de\ntomates concassées. Saler\net poivrer. Ajouter le cumin\net la coriandre.", "Quand le poivron commencent\nà fondre, ajouter les pois\nchiches."]'::jsonb, 'Tu peux remplacer les pois chiches par des lentilles ou des haricots rouges.', false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7dbf94e27c4a', 'linguines sauce au thon', null, 'été', 'juillet', 7, 1, 'mardi', 'déjeuner/dîner', 'salé', 'poivron', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/linguines-sauce-au-thon.jpg', '[{"name": "2 grosses poignées de linguines", "canonical": true}, {"name": "1 petite boîte de thon", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. de crème liquide", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "1 c. à s. de persil séché (EN OPTION)", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Éplucher puis couper l’oignon\net l’ail finement.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans la poêle, ajouter le thon,\nle persil, le jus de citron puis\nla crème. Saler et poivrer.\nMélanger.", "Mélanger les linguines\navec la sauce.\nlinguines sauce\nau thon"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3e861ba09462', 'omelette poivron et oignon rouge', null, 'été', 'juillet', 7, 1, 'mercredi', 'déjeuner/dîner', 'salé', 'poivron', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/omelette-poivron-et-oignon-rouge.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "½ poivron rouge", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper l’ail, le demi oignon\net le demi poivron en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans un bol, battre les œufs\nà la fourchette. Saler et poivrer.", "Dans la poêle, verser les œufs\nsur les légumes.", "Laisser cuire quelques minutes\net retourner à l’aide d’une\nassiette pour faire cuire l’autre\ncôté.\nomelette poivron\net oignon rouge"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('281e77087899', 'taboulé de boulgour', null, 'été', 'juillet', 7, 1, 'jeudi', 'déjeuner/dîner léger', 'salé', 'poivron', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/taboule-de-boulgour.jpg', '[{"name": "1 verre de boulgour cru", "canonical": true}, {"name": "1 poivron jaune", "canonical": true}, {"name": "½ concombre", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "2 c. à s. de jus de citron", "canonical": true}, {"name": "2 c. à s. d’huile de colza", "canonical": true}, {"name": "Quelques feuilles de menthe", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Laver et couper en dés tous\nles légumes. Couper finement\nla menthe.", "Mélanger les légumes\net le boulgour avec le jus\nde citron, l’huile de colza\net la menthe. Saler et poivrer.\ntaboulé\nde boulgour"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2530c1b48e3b', 'poulet à la mexicaine', null, 'été', 'juillet', 7, 1, 'vendredi', 'déjeuner/dîner', 'salé', 'poivron', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/poulet-a-la-mexicaine.jpg', '[{"name": "2 filets de poulet", "canonical": true}, {"name": "1 poivron vert", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "1 petite boîte de coulis de tomate", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de curry", "canonical": true}, {"name": "1 pincée de piment de Cayenne", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés\nles poivrons et l’oignon.", "Couper le poulet en lamelles.", "Dans une poêle huilée, faire cuire", "Lorsque le poulet est cuit, ajouter\nle coulis de tomate, le curry\net le piment. Saler et poivrer."]'::jsonb, 'la mexicaine VENDREDI Le poivron est une bonne source de vitamines C, un excellent antioxydant qui protège les cellules de notre organisme. Tu peux accompagner cette recette avec un reste de boulgour de la veille.', false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('52a89efc72c4', 'salade de lentilles corail et saumon fumé', null, 'été', 'juillet', 7, 2, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-lentilles-corail-et-saumon-fume.jpg', '[{"name": "¾ d’un verre de lentilles corail crues", "canonical": true}, {"name": "½ verre de boulgour", "canonical": true}, {"name": "1 tranche de saumon fumé", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une autre casserole\nd’eau bouillante salée, faire\ncuire", "Laver, éplucher et couper\nla carotte et l’échalote en dés.", "Couper le saumon fumé\nen petits cubes.", "Mélanger l’ensemble\ndes ingrédients"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('4f220d2bc25b', 'polenta aux légumes d’été', null, 'été', 'juillet', 7, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/polenta-aux-legumes-d-ete.jpg', '[{"name": "½ poivron", "canonical": true}, {"name": "½ aubergine", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "4 tomates cerises", "canonical": true}, {"name": "4 c. à s. de polenta", "canonical": true}, {"name": "1 grand verre de lait", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Découper tous les légumes\nen petits dés.", "Dans une casserole, faire bouillir", "Dans une casserole chaude\nhuilée, faire cuire", "Servir la polenta avec\nles légumes rôtis.\npolenta\naux légumes\nd’été\nTu peux doubler\nles quantités pour utiliser\nles légumes en entier !"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('292f03ee33f4', 'wrap poulet crudités', null, 'été', 'juillet', 7, 2, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/wrap-poulet-crudites.jpg', '[{"name": "2 tortillas de blé", "canonical": true}, {"name": "1 escalope de poulet", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "4 feuilles de salade", "canonical": true}, {"name": "1 petit pot de fromage blanc", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Quelques feuilles de menthe (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver les feuilles de salade,\nla carotte et la tomate.", "Couper la tomate et la carotte en\npetits dés.", "Dans un bol, mélanger le fromage\nblanc, le jus de citron et la menthe\nhachée finement. Saler et poivrer.", "Dans une poêle chaude huilée,\nfaire cuire", "Sur une tortilla, déposer la moitié\nde la préparation de fromage\nblanc/menthe puis 2 feuilles de\nsalade, la moitié du poulet cuit et\nenfin la moitié des légumes.", "Replier le bas de la tortilla sur la\ngarniture, plier les côtés et enrouler\nle wrap sur lui-même.\nwrap\npoulet crudités\nCette recette\nse décline à l’infini, avec tous les\naliments (ou presque) qui peuvent\nêtre au fond de ton réfrigérateur."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0d34aa7a3a50', 'salade composée', null, 'été', 'juillet', 7, 2, 'jeudi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-composee.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "1 poignée de salade", "canonical": true}, {"name": "1 petite boîte de maïs", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "½ concombre (GARDER L’AUTRE MOITIÉ POUR DEMAIN)", "canonical": true}, {"name": "Quelques olives noires dénoyautées", "canonical": true}, {"name": "2 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante, faire cuire", "Laver les feuilles de salade,\nla tomate et le concombre.", "Couper la tomate, le demi\nconcombre et les œufs lorsqu’ils\nsont cuits.", "Dans une assiette, mélanger\nl’ensemble des aliments.", "Réaliser la vinaigrette avec\nl''huile, le vinaigre, le sel\net le poivre. Mélanger\nla vinaigrette à la salade.\nsalade composée\nLe maïs est\nune céréale, il constitue donc\nune partie des féculents\ndu repas, tu peux compléter\navec une tranche de pain\nou rajouter des croûtons."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8859258baf2c', 'concombre à la crème et ciboulette', null, 'été', 'juillet', 7, 2, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/concombre-a-la-creme-et-ciboulette.jpg', '[{"name": "½ concombre", "canonical": true}, {"name": "1 c. à s. de crème", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "Ciboulette fraîche (OU SÉCHÉE EN POT)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher le demi\nconcombre et le couper en\ntranches. Couper la ciboulette.", "Dans un saladier mélanger\nl’ensemble des ingrédients.\nSaler et poivrer.\nconcombre\nà"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('749419301fd0', 'crevettes à la sauce soja', null, 'été', 'juillet', 7, 3, 'lundi', 'déjeuner/dîner', 'salé', 'courgette', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/crevettes-a-la-sauce-soja.jpg', '[{"name": "10 crevettes", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Ciboulette fraîche (OU SÉCHÉE EN POT)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Décortiquer les crevettes\net les rincer sous l’eau.", "Couper finement l’ail\net la ciboulette.", "Dans une poêle chaude\nhuilée, faire cuire"]'::jsonb, 'la sauce soja LUNDI Pour un repas complet, tu peux accompagner cette recette avec du riz et des courgettes cuites à la poêle. Et pour une alternative plus économique, tu peux utiliser du tofu à faire mariner dans la sauce soja.', false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a1e8da51813d', 'risotto de courgette', null, 'été', 'juillet', 7, 3, 'mardi', 'déjeuner/dîner', 'salé', 'courgette', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/risotto-de-courgette.jpg', '[{"name": "2 verres de riz à risotto", "canonical": true}, {"name": "½ courgette (GARDE L’AUTRE MOITIÉ POUR VENDREDI)", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "2 c. à s. de crème liquide", "canonical": true}, {"name": "4 verres d’eau", "canonical": true}, {"name": "1 c. à c. de curry", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper la demi courgette\net l’oignon en petits dés.", "Dans une casserole chaude\nhuilée, faire cuire", "Ajouter le riz et le curry\ndans la casserole. Bien\nmélanger. Ajouter 1 verre\nd’eau et attendre qu’il soit\nabsorbé, tout en mélangeant.\nRépéter l’opération 3 fois.", "À la fin, ajouter la crème.\nSaler et poivrer. Mélanger.\nrisotto\nde courgette"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('277ae58971d5', 'ratatouille provençale', null, 'été', 'juillet', 7, 3, 'mercredi', 'déjeuner/dîner', 'salé', 'courgette', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/ratatouille-provencale.jpg', '[{"name": "1 aubergine", "canonical": true}, {"name": "1 courgette", "canonical": true}, {"name": "½ poivron", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 petite boîte de coulis de tomate", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper la courgette,\nl’aubergine, le demi oignon, l’ail\net le poivron en dés.", "Dans une casserole chaude\nhuilée, faire cuire", "Ajouter le coulis de tomate\net les herbes de Provence.\nSaler et poivrer. Couvrir\net laisser mijoter 20 min.", "À la fin, ajouter l’ail et laisser\nmijoter encore 5 min.\nratatouille\nprovençale"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1e861f029668', 'cordon', null, 'été', 'juillet', 7, 3, 'jeudi', 'déjeuner/dîner', 'salé', 'courgette', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/cordon.jpg', '[{"name": "1 filet de poulet", "canonical": true}, {"name": "1 tranche de jambon", "canonical": true}, {"name": "3 tranches d’emmental", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "2 c. à s. de chapelure (OU PAIN RASSIS MIXÉ)", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Aplatir le filet de poulet à l’aide\nd’un rouleau (ou d’un verre).\nSaler et poivrer des 2 côtés\ndu filet.", "Déposer 1 tranche de jambon\net 2 tranches d’emmental sur", "Mettre la farine et la chapelure\ndans deux assiettes séparées.\nBattre l’œuf dans une assiette\ncreuse.", "Plonger le filet de poulet dans\nla farine, puis l’œuf et enfin\nla chapelure.", "Dans une poêle chaude huilée,\nfaire cuire"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('be7f2063b4ab', 'beignets de courgette', null, 'été', 'juillet', 7, 3, 'vendredi', 'déjeuner/dîner', 'salé', 'courgette', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/beignets-de-courgette.jpg', '[{"name": "½ courgette (LA MOITIÉ DE MARDI)", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "4 c. à s. de farine", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "2 c. à s. d’eau", "canonical": true}, {"name": "Huile de tournesol (POUR LA FRITURE)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper la demi courgette\nen rondelles.", "Dans un saladier, verser la farine\net former un puit. Ajouter l’œuf\net l’huile. Saler et poivrer.", "Mélanger tout en ajoutant l’eau\nprogressivement. Laisser poser", "Préparer un bain d’huile bouillant\ndans une poêle : au moins 1 cm\nd’huile au fond de", "À l’aide d’une fourchette, piquer", "Laisser cuire pendant 3 à 4 min.\nDéposer"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6e5b613d1f79', 'œuf cocotte à l’avocat au micro-ondes', null, 'été', 'juillet', 7, 4, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/oeuf-cocotte-a-l-avocat-au-micro-ondes.jpg', '[{"name": "½ avocat (GARDER L’AUTRE MOITIÉ POUR DEMAIN)", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. de jus de citron", "canonical": true}, {"name": "1 pincée de piment (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un bol, écraser le demi\navocat à la fourchette avec le jus\nde citron.", "Ajouter le piment. Saler\net poivrer. Mélanger.", "Dans un ramequin, mettre\nl’avocat et faire un puit\nau milieu.", "Dans 2 bols, séparer le blanc\ndu jaune d’œuf. Verser le blanc\ndans l’avocat. Faire cuire 1 min\nau micro-ondes.", "Ajouter le jaune sur le dessus\net refaire cuire 30 sec. Saler\net poivrer.\nœuf cocotte\nà l’avocat\nau micro-ondes\nGarde le reste\nde l’avocat au frais pour\nla prochaine recette."]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('219530126c67', 'salade de pâtes', null, 'été', 'juillet', 7, 4, 'mardi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-pates.jpg', '[{"name": "1 verre de pâtes de ton choix", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "½ avocat", "canonical": true}, {"name": "½ mozzarella", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "2 c. à c. d’huile de colza", "canonical": true}, {"name": "1 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une autre casserole d’eau\nbouillante, faire cuire", "Couper l’échalote, la tomate,\nla mozzarella, l’avocat et l’œuf\ndur en dés.", "Dans une assiette, mélanger\nl’ensemble des ingrédients."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('24150c722f5a', 'colin en papillote au micro-ondes', null, 'été', 'juillet', 7, 4, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/colin-en-papillote-au-micro-ondes.jpg', '[{"name": "1 filet de colin", "canonical": true}, {"name": "2 carottes", "canonical": true}, {"name": "1 blanc de poireau", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "½ citron", "canonical": true}, {"name": "1 c. à s. de lait de coco", "canonical": true}, {"name": "1. c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Persil frais ou séché en pot (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper le poireau,\nl’échalote et les carottes. Couper\nle demi citron en rondelles.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans un bol, mélanger les légumes\ncuits avec l’échalote et le persil.\nSaler et poivrer.", "Sur une feuille de papier cuisson,\ndéposer", "Replier la feuille de papier cuisson\npour former une papillote.", "Faire cuire la papillote au\nmicro-ondes pendant 2 à 3 min\nà puissance maximale.\ncolin en papillote\nau micro-ondes\nTu peux utiliser\nle vert du poireau pour faire\nun velouté froid par exemple."]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('51b710ab1e9a', 'salade de tomate et melon', null, 'été', 'juillet', 7, 4, 'jeudi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-tomate-et-melon.jpg', '[{"name": "½ melon", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "½ mozzarella", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Quelques feuilles de basilic frais ou séché en pot (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper le melon, la tomate\net la mozzarella en dés.\nCouper finement le basilic.", "Dans une assiette, mélanger\nl’ensemble des ingrédients.\nSaler et poivrer.\nsalade\nde tomate\net melon"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cdad28f8b892', 'apéritif melon et jambon cru', null, 'été', 'juillet', 7, 4, 'vendredi', 'apéritif/entrée', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/aperitif-melon-et-jambon-cru.jpg', '[{"name": "½ melon", "canonical": true}, {"name": "6 tranches de jambon cru", "canonical": true}]'::jsonb, '["Couper le melon en petits cubes.", "Enrouler chaque morceau\nde melon"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3a41dec943ef', 'flan au micro-ondes', null, 'été', 'juillet', 7, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/flan-au-micro-ondes.jpg', '[{"name": "¾ de verre de lait", "canonical": true}, {"name": "4 c. à s. de sucre", "canonical": true}, {"name": "1 c. à s. d’eau", "canonical": true}, {"name": "1 œuf", "canonical": true}]'::jsonb, '["Pour le caramel : faire chauffer\n2 c. à s. de sucre avec 1 c. à s.\nd’eau environ 5 min au micro-\nondes à puissance maximale.\nVerser au fond de 2 ramequins.", "Faire chauffer le lait avec\nle reste de sucre pendant 5 min\nau micro-ondes également\n(vérifier régulièrement).", "Dans un bol, battre l’œuf\net ajouter le lait sucré\nen battant énergiquement.", "Verser le mélange dans\nles ramequins. Faire cuire 2 fois\n5 min au micro-ondes, vérifier\nà mi-cuisson.", "Mettre au réfrigérateur avant\nde manger.\nflan\nau micro-ondes\n2"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('d1d8530d6832', 'fraises enrobées de chocolat et graines', null, 'été', 'juillet', 7, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/fraises-enrobees-de-chocolat-et-graines.jpg', '[{"name": "10 fraises", "canonical": true}, {"name": "4 carrés de chocolat", "canonical": true}, {"name": "2 c. à s. de graines de sésame", "canonical": true}]'::jsonb, '["Laver les fraises et enlever\nles feuilles à l’aide d’un couteau.", "Faire fondre le chocolat\nau micro-ondes.", "Mettre les graines\ndans un petit ramequin.", "Piquer les fraises avec des\nfourchettes ou des cure-dents\net les tremper dans le chocolat\nfondu puis dans les graines.", "Laisser refroidir\n1h au réfrigérateur.\nfraises enrobées\nde chocolat\net graines\n4"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('d2c93d185d6b', 'mugcake aux pépites de chocolat', null, 'été', 'juillet', 7, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/mugcake-aux-pepites-de-chocolat.jpg', '[{"name": "1 c. à s. de beurre", "canonical": true}, {"name": "4 carrés de chocolat", "canonical": true}, {"name": "1 c. à c. de sucre", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 œuf", "canonical": true}]'::jsonb, '["Dans un bol, faire fondre\nle beurre au micro-ondes.", "Ajouter l’œuf, le sucre\net la farine. Mélanger\nà la fourchette.", "À l’aide d’un couteau, couper\nle chocolat en pépites\net les ajouter au mélange.", "Verser la préparation dans\nun mug et faire cuire 30 sec\nau micro-ondes.\nmugcake\naux pépites\nde chocolat"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('253f412f0a34', 'pêche rôtie au miel', null, 'été', 'juillet', 7, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/peche-rotie-au-miel.jpg', '[{"name": "1 pêche", "canonical": true}, {"name": "1 c. à s. de beurre", "canonical": true}, {"name": "2 c. à c. de miel", "canonical": true}, {"name": "½ c. à c. de cannelle", "canonical": true}]'::jsonb, '["Laver, couper en 2\net dénoyauter", "Dans une poêle, faire fondre\nle beurre et déposer la pêche\nface plate vers le haut.", "Ajouter 1 c. à c. de miel sur\nchaque demi pêche. Ajouter\nun peu de cannelle par-dessus.", "Laisser cuire 10 min en arrosant\nsouvent"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('aee003ddf7e9', 'tartare de fraises, citron et menthe', null, 'été', 'juillet', 7, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tartare-de-fraises-citron-et-menthe.jpg', '[{"name": "10 fraises", "canonical": true}, {"name": "Quelques feuilles de menthe", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}]'::jsonb, '["Laver et couper les fraises\nen petits cubes.", "Couper les feuilles de menthe\nfinement.", "Dans un bol, mélanger\nles fraises, la menthe\net le citron.\ntartare de fraises,\ncitron et menthe\n1"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('acffb7182ff6', 'tagliatelles de courgette et mozzarella', null, 'été', 'août', 8, 1, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tagliatelles-de-courgette-et-mozzarella.jpg', '[{"name": "½ courgette", "canonical": true}, {"name": "½ mozzarella", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et éplucher la demi\ncourgette.", "À l’aide d’un épluche-\nlégumes, faire des tagliatelles\nde courgette.", "Dans un bol mélanger\nles tagliatelles de courgette\navec l’huile, le citron, le sel\net le poivre.", "Couper la mozzarella en petits\ncubes et l’ajouter à la courgette.\ntagliatelles de\ncourgette et\nmozzarella\nGarde l’autre\nmoitié de la mozzarella et\nde la courgette pour mercredi."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3e1765ee4590', 'blanquette de poisson blanc', null, 'été', 'août', 8, 1, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/blanquette-de-poisson-blanc.jpg', '[{"name": "2 pavés de poisson blanc (FRAIS OU SURGELÉ)", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "2 gros champignons de Paris", "canonical": true}, {"name": "1 verre de riz blanc", "canonical": true}, {"name": "1 oignon rouge", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "3 c. à s. de crème liquide", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Persil frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante, faire cuire", "Couper la carotte,\nles champignons, l’oignon\net l’ail en dés.", "Dans une casserole chaude\nhuilée, faire cuire", "Couper le poisson en gros\ncubes et l’ajouter aux légumes.", "Verser la crème et le persil.\nSaler et poivrer. Mélanger.", "Dans une casserole d’eau\nbouillante salée, faire cuire"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('61e4aaaae9d6', 'salade tomate, mozzarella et courgette', null, 'été', 'août', 8, 1, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-tomate-mozzarella-et-courgette.jpg', '[{"name": "1 tomate", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "½ mozzarella", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "2 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper la tomate,\nla demi courgette\net la mozzarella en dés.", "Dans un saladier, mélanger\nles ingrédients. Ajouter l’huile\net le vinaigre. Saler et poivrer.\nsalade tomate,\nmozzarella\net courgette"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0e5d3987b672', 'quiche lorraine sans pâte au micro-ondes', null, 'été', 'août', 8, 1, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/quiche-lorraine-sans-pate-au-micro-ondes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "½ verre de crème liquide", "canonical": true}, {"name": "3 c. à s. de lait", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 petit paquet de lardons", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nles œufs et la farine.", "Ajouter le lait et la crème.\nBien mélanger.", "Dans une poêle chaude, faire\ncuire", "Ajouter les lardons\ndans la préparation.", "Verser la préparation dans\nun moule compatible avec\nla cuisson au micro-ondes.\nFaire cuire 6 à 8 min à puissance\nmaximale.\nquiche lorraine\nsans pâte\nau micro-ondes\nPour un repas complet,\nrefais la recette de la veille\navec les légumes. Complète\navec une tranche de pain."]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('de9ebf426352', 'Chakchouka au poivron rouge', null, 'été', 'août', 8, 1, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/chakchouka-au-poivron-rouge.jpg', '[{"name": "1 poivron rouge", "canonical": true}, {"name": "1 bocal de tomates concassées", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Cumin en poudre", "canonical": true}, {"name": "Coriandre fraîche (OU SÉCHÉE EN POT)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper l’oignon et le poivron\nen fines lamelles.", "Dans une poêle chaude huilée,\nfaire cuire", "Verser le bocal de tomates\nconcassées. Saler et poivrer.\nAjouter le cumin et la coriandre.\nBien mélanger.", "Quand le poivron commence\nà fondre, casser les œufs\net les déposer sur les légumes.\nLaisser cuire jusqu’à ce que\nle blanc d’œuf soit cuit.\nChakchouka\nau poivron rouge\nTu peux refaire cette\nrecette avec des poivrons\njaunes ou verts."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1b955661a846', 'œufs cocottes', null, 'été', 'août', 8, 2, 'lundi', 'déjeuner/dîner', 'salé', 'tomate', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/oeufs-cocottes.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "2 tomates", "canonical": true}, {"name": "2 tranches de pain de mie", "canonical": true}, {"name": "2 c. à s. de crème liquide", "canonical": true}, {"name": "Quelques feuilles de basilic frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Vider les tomates et ajouter\nune cuillère de crème\nà l’intérieur.", "Découper finement le basilic\net le déposer sur la crème.", "Casser un œuf dans la tomate.\nSaler et poivrer.", "Enfourner au micro-ondes\npendant 1 min 30.", "Faire dorer le pain de mie à\nla poêle avec du beurre.\nœufs cocottes"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5ed52df9af41', 'tomate provençale au micro-ondes', null, 'été', 'août', 8, 2, 'mardi', 'déjeuner/dîner', 'salé', 'tomate', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tomate-provencale-au-micro-ondes.jpg', '[{"name": "1 tomate", "canonical": true}, {"name": "2 c. à s. de chapelure", "canonical": true}, {"name": "Quelques feuilles de persil frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer et couper la tomate en 2.", "Saler la tomate puis la retourner\ndu côté plat sur une assiette\npour laisser l’eau s’évacuer.", "Couper finement l’ail\net le persil.", "Dans un bol, mélanger l''ail\net", "Mettre la chapelure sur la\ndemi tomate. Faire cuire 4 min\nau micro-ondes sur une assiette.\ntomate provençale\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('744e60f1b06c', 'samoussas poulet et poivron', null, 'été', 'août', 8, 2, 'mercredi', 'déjeuner/dîner', 'salé', 'tomate', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/samoussas-poulet-et-poivron.jpg', '[{"name": "2 filets de poulet", "canonical": true}, {"name": "4 feuilles de brick", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "1 c. à c. de curry", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, couper le poivron\net l’oignon en petits dés.", "Couper le poulet en petits\nmorceaux.", "Dans une poêle chaude huilée,\nfaire cuire", "Couper les feuilles de brick\nen 2. Plier la moitié en 2.\nAjouter un peu de mélange\npoulet/poivron puis plier\nla feuille en triangle.", "Faire dorer les samoussas\nquelques minutes dans\nune casserole chaude huilée.\nsamoussas poulet\net poivron"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('13b0ce6c2976', 'pâtes et sardines à la sauce tomate', null, 'été', 'août', 8, 2, 'jeudi', 'déjeuner/dîner', 'salé', 'tomate', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/pates-et-sardines-a-la-sauce-tomate.jpg', '[{"name": "1 petite boîte de sardines natures", "canonical": true}, {"name": "1 verre de pâtes", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 petite brique de coulis de tomate", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Couper finement le demi\noignon. Couper les sardines\nen morceaux.", "Dans une poêle chaude huilée,\nfaire cuire", "Verser le coulis de tomate\ndans la poêle. Saler et poivrer.\nMélanger.", "Égoutter les pâtes et verser\nla sauce dessus.\npâtes et sardines\nà la sauce tomate"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6761f915e352', 'tiramisu tomates pesto ', null, 'été', 'août', 8, 2, 'vendredi', 'déjeuner/dîner', 'salé', 'tomate', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tiramisu-tomates-pesto.jpg', '[{"name": "2 tomates", "canonical": true}, {"name": "4 biscottes", "canonical": true}, {"name": "½ bloc de feta (GARDER LA MOITIÉ POUR LUNDI PROCHAIN)", "canonical": true}, {"name": "1 dizaine de feuilles de basilic (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "3 c. à s. de mascarpone", "canonical": true}, {"name": "½ verre de lait", "canonical": true}, {"name": "4 c. à c. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un bol, mélanger\nle mascarpone, la feta et le lait.\nAjouter 1 c. à c. d’huile d’olive,\nsaler et poivrer.", "Laver et couper les tomates\nen petits cubes.", "Couper finement le basilic\net le mélanger avec l’huile\nrestante et les tomates.", "Dans un bol, écraser\ngrossièrement", "Dans une verrine (ou un verre),\nalterner entre une couche\nde biscotte, une couche\nde mascarpone et une couche\nde tomate/basilic.\ntiramisu\ntomates pesto"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('223429b98a17', 'salade à la grecque', null, 'été', 'août', 8, 3, 'lundi', 'déjeuner/dîner léger', 'salé', 'concombre', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-a-la-grecque.jpg', '[{"name": "1 tomate", "canonical": true}, {"name": "½ concombre", "canonical": true}, {"name": "½ bloc de feta", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 dizaine d’olives noires", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper la feta, la tomate,\nle demi concombre et le demi\noignon en cubes.", "Placer tous les ingrédients\ndans un saladier. Ajouter les olives\nnoires.", "Verser l’huile d’olive.\nSaler et poivrer.\nsalade\nà"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1819728880bd', 'curry de pois chiches et légumes d’été', null, 'été', 'août', 8, 3, 'mardi', 'déjeuner/dîner', 'salé', 'concombre', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/curry-de-pois-chiches-et-legumes-d-ete.jpg', '[{"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "1 verre de riz", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "2 c. à s. de crème liquide", "canonical": true}, {"name": "2 c. à s. de lait de coco", "canonical": true}, {"name": "2 c. à c. de curry", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en dés l’oignon\net le poivron.", "Éplucher la demi courgette\net faire des spaghettis à l’aide\nd’un épluche-légumes.", "Dans une poêle huilée,\nfaire cuire", "Ajouter les pois chiches,\nle curry, la crème et le lait de coco.\nSaler et poivrer. Mélanger.", "Dans une casserole d’eau\nbouillante salée, faire cuire le\nriz (temps de cuisson indiqué\nsur"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c1409b27238d', 'poisson au lait de coco, ail', null, 'été', 'août', 8, 3, 'mercredi', 'déjeuner/dîner', 'salé', 'concombre', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poisson-au-lait-de-coco-ail.jpg', '[{"name": "1 pavé de poisson blanc", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "2 c. à s. de lait de coco", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "½ oignon jaune", "canonical": true}, {"name": "½ c. à c. de gingembre moulu", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante, faire cuire", "Peler et couper en dés l’ail,\nl’oignon et la courgette.", "Dans une poêle huilée, faire\ncuire", "Ajouter le poisson, le gingembre\net le lait de coco. Saler et poivrer.\npoisson au\nlait de coco, ail\net gingembre"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('9586345047d1', 'salade de pommes de terre et lardons ', null, 'été', 'août', 8, 3, 'jeudi', 'déjeuner/dîner léger', 'salé', 'concombre', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-pommes-de-terre-et-lardons.jpg', '[{"name": "4 pommes de terre moyennes", "canonical": true}, {"name": "1 paquet de lardons", "canonical": true}, {"name": "4 poignées de salade", "canonical": true}, {"name": "2 tomates", "canonical": true}, {"name": "2 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper\nen dés", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une poêle chaude, faire\ncuire", "Mélanger la salade lavée avec\nles pommes de terre, les tomates\net les lardons. Ajouter le vinaigre.\nSaler et poivrer. Manger froid.\nsalade de pommes\nde terre et lardons"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('9190ef4549fb', 'tzatzíki', null, 'été', 'août', 8, 3, 'vendredi', 'déjeuner/dîner', 'salé', 'concombre', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tzatziki.jpg', '[{"name": "1 concombre", "canonical": true}, {"name": "1 yaourt grec", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à c. d’aneth séchée", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, enlever les pépins\net couper le concombre en dés.", "Éplucher et couper l’ail en dés.", "Dans un bol, mélanger tous\nles ingrédients. Saler et poivrer.\ntzatzíki"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a7e05374f51f', 'linguines sauce feta et tomates cerises', null, 'été', 'août', 8, 4, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/linguines-sauce-feta-et-tomates-cerises.jpg', '[{"name": "2 poignées de linguines", "canonical": true}, {"name": "1 dizaine de tomates cerises", "canonical": true}, {"name": "½ bloc de feta", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Couper les tomates cerises en 2.", "Dans une casserole chaude,\némietter et faire fondre", "Ajouter la crème et les herbes\nde Provence. Poivrer.", "Mélanger la sauce\navec les linguines.\nlinguines sauce\nfeta et tomates\ncerises\nTu peux également\nfaire cette recette au micro-ondes.\nMets la feta dans un plat\navec les tomates et les herbes\nde Provence. Fais chauffer\npendant 2 à 3 minutes puis\najoute la crème et mélange."]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('d7908d4d5fbb', 'clafoutis provençal à la poêle', null, 'été', 'août', 8, 4, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/clafoutis-provencal-a-la-poele.jpg', '[{"name": "1 tomate", "canonical": true}, {"name": "1 dizaine d’olives noires dénoyautées", "canonical": true}, {"name": "½ poivron rouge", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "½ verre de lait", "canonical": true}, {"name": "½ verre de crème liquide", "canonical": true}, {"name": "1 verre de farine de blé", "canonical": true}, {"name": "1 dizaine de feuilles de basilic frais (OU SÉCHÉ EN POT)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver le demi poivron et la\ntomate. Les couper en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Couper finement le basilic.", "Dans un saladier, mélanger\nles œufs avec la farine.\nAjouter le lait et la crème tout\nen mélangeant. Saler, poivrer\net ajouter le basilic.", "Dans une poêle chaude huilée,\nverser", "Retourner le clafoutis à l’aide\nd’une assiette et finir la cuisson\npendant 2 à 3 min.\nclafoutis provençal\nà la poêle\nQuand il fait très chaud,\nje peux fragmenter mes repas\net faire plusieurs petits repas\ndans la journée. Cela m’évite\nde gros efforts de digestion."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0d78ed7e43ef', 'salade de pâtes au thon', null, 'été', 'août', 8, 4, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-pates-au-thon.jpg', '[{"name": "2 verres de pâtes crues", "canonical": true}, {"name": "2 tomates", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "1 petite boîte de thon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Laver et couper les tomates,\nle poivron et l’ail en dés.", "Dans un saladier, mélanger tous"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('603f36b66554', 'poulet caramélisé à la sauce soja', null, 'été', 'août', 8, 4, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poulet-caramelise-a-la-sauce-soja.jpg', '[{"name": "1 filet de poulet", "canonical": true}, {"name": "1 c. à c. sucre", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 petit oignon rouge", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Couper le poulet en petits\ncubes.", "Couper l’oignon en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans la même poêle, faire\ncuire le poulet pendant 5 min\net ajouter la sauce soja.", "Ajouter le sucre.\nPoivrer et mélanger.\npoulet caramélisé\nà la sauce soja\nSi tu prends\nde la sauce soja salée, tu n’as pas\nbesoin de rajouter de sel. Tu peux\naccompagner ce plat avec du riz."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b8fb23c3de66', 'tartare de légumes', null, 'été', 'août', 8, 4, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tartare-de-legumes.jpg', '[{"name": "3 tomates", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "1 poivron vert", "canonical": true}, {"name": "1 poivron jaune", "canonical": true}, {"name": "1 courgette", "canonical": true}, {"name": "1 botte de ciboulette fraîche (OU SÉCHÉE EN POT)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Découper tous les légumes\nen dés.", "Dans un saladier, ajouter\nles ingrédients.", "Mélanger le tout et assaisonner\nd’huile d’olive et de vinaigre.\nSaler et poivrer.", "Verser dans un ramequin,\ntasser"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('9faf79b92dce', 'bricks pomme-chocolat', null, 'été', 'août', 8, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/bricks-pomme-chocolat.jpg', '[{"name": "1 pomme", "canonical": true}, {"name": "4 carreaux de chocolat", "canonical": true}, {"name": "2 feuilles de brick", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}]'::jsonb, '["Laver, éplucher et couper\nla pomme en petits cubes.", "Faire fondre le chocolat\nau micro-ondes.", "Couper les feuilles de brick\nen 2.", "Plier les demi feuilles en\n2, déposer les morceaux\nde pomme puis verser un peu\nde chocolat fondu par-dessus.", "Plier les bricks en triangle.", "Faire cuire dans une casserole\nchaude huilée.\nbricks\npomme-chocolat\n2"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6637cda02235', 'cinnamon rolls express', null, 'été', 'août', 8, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/cinnamon-rolls-express.jpg', '[{"name": "2 tranches de brioche", "canonical": true}, {"name": "10g de beurre", "canonical": true}, {"name": "2 c. à c. de sucre", "canonical": true}, {"name": "1 c. à c. de cannelle", "canonical": true}]'::jsonb, '["Faire fondre le beurre et le sucre\nau micro-ondes.", "Ajouter la cannelle et mélanger.", "Couper les tranches de brioche\nen 3 et les aplatir à l’aide d’un\nverre. Superposer les trois\nmorceaux dans la longueur.", "À l’aide d’une cuillère, déposer", "Mettre dans un ramequin.\nFaire chauffer 2 à 3 min\nau micro-ondes.\ncinnamon rolls\nexpress\n3"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('10b120d96c7f', 'porridge froid au chocolat et à la pêche', null, 'été', 'août', 8, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/porridge-froid-au-chocolat-et-a-la-peche.jpg', '[{"name": "½ verre de flocons d’avoine", "canonical": true}, {"name": "½ verre de lait", "canonical": true}, {"name": "1 pêche", "canonical": true}, {"name": "2 carrés de chocolat", "canonical": true}]'::jsonb, '["Dans un bol, verser les flocons\nd’avoine avec le lait.", "Laver, éplucher et couper\nla pêche en morceaux.\nLa déposer sur le mélange lait\net flocons d’avoine.", "Faire fondre le chocolat\nau micro-ondes puis le verser\nsur les morceaux de pêche..", "Laisser poser toute la nuit\nau réfrigérateur.\nporridge froid\nau chocolat\net à la pêche"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('35fe960391d2', 'roses des sables aux flocons d’avoine', null, 'été', 'août', 8, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/roses-des-sables-aux-flocons-d-avoine.jpg', '[{"name": "1 verre de flocons d’avoine", "canonical": true}, {"name": "8 carreaux de chocolat pâtissier", "canonical": true}]'::jsonb, '["Faire fondre le chocolat\nau micro-ondes.", "Dans un saladier, mélanger\nles flocons d’avoine et\nle chocolat.", "Mettre le mélange dans\ndes petits ramequins ou dans\ndes moules en silicone pour\nformer les roses des sables.", "Faire figer au réfrigérateur\nau moins 1h.\nroses des sables\naux flocons\nd’avoine\n1\nLorsqu''"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7776bf1ba487', 'salade de fruits d’été', null, 'été', 'août', 8, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-fruits-d-ete.jpg', '[{"name": "1 pêche", "canonical": true}, {"name": "1 petite barquette de framboises", "canonical": true}, {"name": "3 abricots", "canonical": true}]'::jsonb, '["Laver tous les fruits.", "Couper la pêche et les abricots\nen cubes.", "Mélanger tous les fruits\ndans un saladier.\nsalade\nde fruits d’été\n4\nFais le plein de vitamines\navec cette salade de fruits\nestivale et désaltérante."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2ca12a3edde2', 'salade de lentilles, chou rouge et tofu', null, 'été', 'septembre', 9, 1, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-lentilles-chou-rouge-et-tofu.jpg', '[{"name": "¾ d’un verre de lentilles vertes en conserve", "canonical": true}, {"name": "¼ de chou rouge", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "1 bloc de tofu nature", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Égoutter les lentilles\nen conserve.", "Couper le chou rouge,\nl’échalote, la tomate et le tofu\nen dés.", "Dans une poêle huilée, faire\ncuire", "Mélanger tous les ingrédients\ndans un saladier. Ajouter\nle vinaigre. Saler et poivrer.\nsalade de lentilles,\nchou rouge et tofu\nLe tofu provient\ndu caillage du lait de soja.\nIl est riche en protéines."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c96ef61c90eb', 'œuf cocotte au jambon', null, 'été', 'septembre', 9, 1, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/oeuf-cocotte-au-jambon.jpg', '[{"name": "1 œuf", "canonical": true}, {"name": "1 tranche de jambon", "canonical": true}, {"name": "2 c. à s. de coulis de tomate", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (en option)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un bol, mélanger le coulis\nde tomate avec les herbes\nde Provence. Saler et poivrer.", "Couper la tranche de jambon\nen dés.", "Dans un ramequin, mettre\nles dés de jambon au fond puis\nverser le coulis de tomate.", "Casser l’œuf par-dessus.\nSaler et poivrer.", "Faire cuire au micro-ondes\npendant 4 à 5 min à puissance\nmaximale.\nœuf cocotte\nau jambon"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6142626da160', 'salade de pois chiches', null, 'été', 'septembre', 9, 1, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-pois-chiches.jpg', '[{"name": "1 petite boîte de conserve de pois chiches", "canonical": true}, {"name": "1 poivron rouge", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "1 tomate", "canonical": true}, {"name": "½ botte de coriandre fraîche (ou séchée en pot) EN OPTION", "canonical": true}, {"name": "½ botte de persil plat frais (ou séché en pot) EN OPTION", "canonical": true}, {"name": "1 citron vert", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}]'::jsonb, '["Découper les légumes en dés.", "Couper finement les herbes.", "Dans un saladier, ajouter\ntous les ingrédients, l’huile,\nle vinaigre, le zeste de citron\net les herbes.", "Saler et poivrer. Presser le citron\net ajouter le jus.\nsalade\nde pois chiches\nLes pois chiches\nsont des légumineuses. Ils sont\nune source de protéines et de\nfibres économiques. Ils permettent\nd’être rassasié longtemps."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8fb8cf0fa606', 'poke bowl saumon crudités', null, 'été', 'septembre', 9, 1, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poke-bowl-saumon-crudites.jpg', '[{"name": "1 pavé de saumon cru", "canonical": true}, {"name": "1 verre de riz blanc", "canonical": true}, {"name": "½ avocat", "canonical": true}, {"name": "¼ de chou rouge", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de graines de sésame", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "½ c. à c. de gingembre en poudre", "canonical": true}]'::jsonb, '["Dans une casserole d’eau\nbouillante salée, faire cuire", "Couper le saumon en cubes.", "Dans un bol mélanger l’huile,\nla sauce soja et le gingembre.\nMettre les dés de saumon\ndedans. Mettre au réfrigérateur.", "Couper le demi avocat\nen lamelles. Couper finement\nle demi oignon et le chou rouge.", "Dans un grand bol, verser le riz\nau fond, ajouter le saumon et\nsa sauce puis les légumes crus.", "Parsemer de graines de sésame.\npoke bowl\nsaumon crudités"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a7d054634c92', 'tian de légumes', null, 'été', 'septembre', 9, 1, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tian-de-legumes.jpg', '[{"name": "4 pommes de terre moyennes", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "2 tomates", "canonical": true}, {"name": "1 aubergine", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 oignons rouges", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, couper les légumes\net les pommes de terre en fines\nlamelles. Couper l’ail finement.", "Dans un plat compatible\nau micro-ondes, placer", "Verser l’huile et les herbes de\nProvence. Ajouter l’ail coupé.", "Faire cuire pendant 8 min\nau micro-ondes à puissance\nmaximale.\ntian de légumes"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a6e5c0c239de', 'aubergine à la parmigiana', null, 'été', 'septembre', 9, 2, 'lundi', 'déjeuner/dîner', 'salé', 'aubergine', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/aubergine-a-la-parmigiana.jpg', '[{"name": "1 aubergine", "canonical": true}, {"name": "1 grande brique de coulis de tomate", "canonical": true}, {"name": "3 c. à s. de parmesan râpé", "canonical": true}, {"name": "1 boule de mozzarella", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "3 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et découper de fines\ntranches d’aubergine dans", "Éplucher et couper les gousses\nd’ail en dés.", "Répartir toutes les tranches\nd’aubergine dans un petit plat\ncompatible au micro-ondes. Faire\ncuire au micro-ondes pendant 4 min\nà puissance maximale. Mettre de\ncôté les tranches d’aubergine. Vider\nl’excédent de liquide.", "Placer une couche de sauce\ntomate au fond du plat à gratin\npuis recouvrir d’une couche\nd’aubergine précuite. Saupoudrer\nde parmesan râpé. Réaliser\n2 couches supplémentaires.", "Terminer avec la mozzarella coupée\nen tranches, 1 cuillère à soupe\nde parmesan râpé et l’ail coupé.", "Faire cuire au micro-ondes à\npuissance maximale pendant 10 min.\naubergine\nà"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ae51f5b7ec3d', 'tomates farcies au thon', null, 'été', 'septembre', 9, 2, 'mardi', 'déjeuner/dîner', 'salé', 'aubergine', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tomates-farcies-au-thon.jpg', '[{"name": "2 tomates", "canonical": true}, {"name": "1 petite boîte de thon (80g)", "canonical": true}, {"name": "1 petit suisse", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un bol, mélanger le thon,\nle petit suisse et le jus de citron.\nSaler et poivrer.", "Couper le haut des tomates\net conserver le chapeau, vider\nl’intérieur et l’ajouter dans\nle mélange thon /petit suisse.\nMélanger. Saler et poivrer.", "Farcir les tomates avec la farce\npréparée (thon/petit suisse/\ntomates).", "Mettre dans un plat et faire\ncuire", "Mettre les chapeaux sur\nles tomates et refaire cuire\n2 min.\ntomates farcies\nau thon"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cbef2677dfee', 'moussaka au micro-ondes', null, 'été', 'septembre', 9, 2, 'mercredi', 'déjeuner/dîner', 'salé', 'aubergine', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/moussaka-au-micro-ondes.jpg', '[{"name": "1 aubergine", "canonical": true}, {"name": "200g de viande hachée", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "1 c. à s. de beurre", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "2 c. à s. de fromage râpé", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 verre de coulis de tomate", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper l’aubergine en fines\nrondelles.", "Peler et couper finement l’oignon\net l’ail.", "Dans une poêle chaude huilée,\nles faire cuire pendant 3 à 4 min.\nAjouter la viande hachée et la faire\ncuire pendant 5 min.", "Ajouter le coulis de tomate et les\nherbes de Provence. Saler et poivrer.", "Dans une casserole, faire fondre", "Dans un plat, alterner les couches\nd’aubergine et de bœuf. Ajouter\nla béchamel à la fin.", "Mettre le fromage râpé par-dessus\net faire cuire 5 min au micro-ondes.\nmoussaka\nau micro-ondes"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('20e1f561398b', 'tortizza au fromage', null, 'été', 'septembre', 9, 2, 'jeudi', 'déjeuner/dîner', 'salé', 'aubergine', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tortizza-au-fromage.jpg', '[{"name": "1 tortilla de blé", "canonical": true}, {"name": "2 c. à s. de coulis de tomate", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "4 tranches de bûche de chèvre", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à c. d’origan séché (EN OPTION)", "canonical": true}, {"name": "1 c. à s. de fromage râpé", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Peler et couper finement l’oignon\net la demi courgette.", "Dans une poêle chaude huilée, faire\ncuire", "Dans un bol, mélanger le coulis de\ntomate avec l’origan. Saler et poivrer.", "Dans une autre poêle, faire cuire", "Couper 4 tranches de bûche\nde chèvre et"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('33df475ee08d', 'caviar d’aubergine au micro-ondes', null, 'été', 'septembre', 9, 2, 'vendredi', 'déjeuner/dîner', 'salé', 'aubergine', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/caviar-d-aubergine-au-micro-ondes.jpg', '[{"name": "1 aubergine", "canonical": true}, {"name": "2 gousses d’ail", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 pain de campagne", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Peler les gousses d’ail et ne pas\nles couper.", "Laver et couper l’aubergine\nen petits morceaux.", "Mettre l’aubergine et l’ail dans\nun plat et verser l’huile. Saler\net poivrer.", "Faire cuire au micro-ondes\npendant 15 min à puissance\nmaximale. Vérifier\nrégulièrement", "Écraser l’ensemble\nà la fourchette.", "Couper une tranche\n(ou plusieurs) de pain et tartiner"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ceb41b5c6791', 'filet de colin aux petits légumes', null, 'été', 'septembre', 9, 3, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/filet-de-colin-aux-petits-legumes.jpg', '[{"name": "2 filets de colin ou de poisson blanc (frais ou surgelés)", "canonical": true}, {"name": "1 citron jaune", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "Quelques tomates cerises", "canonical": true}, {"name": "1 poignée de croûtons de pain", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper la demi courgette,\nle citron et les tomates cerises\nen dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Dans un plat, disposer\nles légumes avec les filets\nde poisson blanc. Saler et\npoivrer.", "Filmer le plat et enfourner\nau micro-ondes pendant 10 min\nà puissance maximale.", "Ajouter les croûtons\net les morceaux de citron avant\nde déguster.\nfilet de colin\naux petits légumes\nPour accompagner\nle poisson et les légumes, tu peux\nfaire cuire du riz dans une\ncasserole d’eau bouillante salée."]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b1d321e5129c', 'one pot pasta courgette', null, 'été', 'septembre', 9, 3, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/one-pot-pasta-courgette.jpg', '[{"name": "1 verre de pâtes de ton choix", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "3 c. à s. de coulis de tomate en conserve", "canonical": true}, {"name": "2 verres d’eau", "canonical": true}, {"name": "1 c. à c. de curry en poudre (en option)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon et\nla demi courgette en dés.", "Dans une casserole huilée, faire\ncuire", "Ajouter le curry, le coulis\nde tomate, les pâtes et l’eau.\nRemuer constamment pour\néviter que les pâtes ne collent.", "Laisser cuire 8 à 10 min jusqu’à\nce que"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2cc36da6acdc', 'bruschettas tomate basilic', null, 'été', 'septembre', 9, 3, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/bruschettas-tomate-basilic.jpg', '[{"name": "2 tomates", "canonical": true}, {"name": "2 tranches de pain de campagne", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 dizaine de feuilles de basilic frais (en option)", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper les tomates\nen petits cubes. Couper\nfinement le basilic.", "Dans une poêle, faire dorer\nles tranches de pain avec\nun peu de beurre.", "Peler et couper la gousse d’ail\nen 2. Frotter la moitié sur\nles tranches de pain puis couper\nfinement le reste.", "Mélanger l’ail, les tomates,\nle basilic et l’huile dans un bol.", "Verser le mélange sur\nles tranches de pain.\nbruschettas\ntomate basilic\nPour compléter ton\nrepas, tu peux ajouter une portion\nde protéines (2 œufs, 100g\nde viande ou 120g de poisson)."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('eac9980f56a0', 'sandwich au jambon', null, 'été', 'septembre', 9, 3, 'jeudi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/sandwich-au-jambon.jpg', '[{"name": "1 tranche de jambon", "canonical": true}, {"name": "2 tranches de pain de campagne", "canonical": true}, {"name": "2 feuilles de salade", "canonical": true}, {"name": "2 c. à s. de beurre", "canonical": true}, {"name": "½ tomate", "canonical": true}]'::jsonb, '["Beurrer les 2 tranches de pain.", "Couper la demi tomate\nen tranches et le jambon en 2.", "Mettre une feuille de salade sur", "Refermer le sandwich avec\nla deuxième tranche de pain.\nsandwich\nau jambon\nCe sandwich maison\nest facile et rapide à faire,\nidéal à emporter pour le repas\ndu midi entre les cours.\nIl sera plus économique qu’un\nsandwich acheté tout prêt\nau supermarché ou en boulangerie."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2605de9e0a33', 'chou-fleur pané', null, 'été', 'septembre', 9, 3, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/chou-fleur-pane.jpg', '[{"name": "1 chou-fleur", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "3 c. à s. de chapelure", "canonical": true}, {"name": "3 c. à s. de farine", "canonical": true}, {"name": "½ verre d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver le chou-fleur et le couper\nen morceaux.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Casser l’œuf dans un bol\net le battre en omelette. Saler\net poivrer.", "Verser la farine et la chapelure\ndans 2 assiettes différentes.", "Tremper les morceaux de chou-\nfleur cuits dans la farine, puis\nl’œuf et enfin dans la chapelure.", "Dans une poêle chaude huilée,\nfaire griller"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('08e23f24cf11', 'pâtes sauce roquefort et brocoli', null, 'été', 'septembre', 9, 4, 'lundi', 'déjeuner/dîner', 'salé', 'brocoli', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pates-sauce-roquefort-et-brocoli.jpg', '[{"name": "2 verres de pâtes de ton choix", "canonical": true}, {"name": "1 morceau de roquefort", "canonical": true}, {"name": "1 c. à s. de crème liquide", "canonical": true}, {"name": "¼ de brocoli", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et découper en morceaux\nle brocoli.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans une autre casserole d’eau\nbouillante salée, faire cuire", "Dans une casserole chaude,\nfaire fondre", "Quand tout est cuit, mélanger\nl’ensemble des aliments.\npâtes sauce\nroquefort et brocoli"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('72e11107e1a3', 'galettes de brocoli', null, 'été', 'septembre', 9, 4, 'mardi', 'déjeuner/dîner', 'salé', 'brocoli', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/galettes-de-brocoli.jpg', '[{"name": "½ brocoli", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "3 c. à s. de farine de blé", "canonical": true}, {"name": "1 oignon jaune", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et découper en morceaux\nle brocoli.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Laver et couper en dés l’oignon\net l’ail.", "Mettre le brocoli cuit dans\nun saladier et l’écraser\nà la fourchette.", "Ajouter les œufs, l’oignon, l’ail\net la farine. Saler et poivrer.\nMélanger tous les ingrédients avec\nla fourchette.", "Dans une poêle chaude huilée,\ndéposer", "Déposer les galettes sur du papier\nabsorbant.\ngalettes\nde brocoli"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3df1d7e81b57', 'salade au poulet grillé', null, 'été', 'septembre', 9, 4, 'mercredi', 'déjeuner/dîner léger', 'salé', 'brocoli', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-au-poulet-grille.jpg', '[{"name": "2 blancs de poulet", "canonical": true}, {"name": "4 poignées de salade", "canonical": true}, {"name": "1 dizaine de croûtons", "canonical": true}, {"name": "1 oignon rouge", "canonical": true}, {"name": "½ barquette de tomates cerises", "canonical": true}, {"name": "1 c. à s. de jus de citron", "canonical": true}, {"name": "1 pot de yaourt nature", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "Quelques feuilles de menthe fraîche (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper les blancs de poulet en dés.", "Dans une poêle chaude huilée,\nfaire cuire", "Couper l’oignon rouge et les\ntomates cerises en dés.", "Nettoyer la salade.", "Dans un saladier, mélanger\nla salade, le poulet cuit,\nl’oignon, les croûtons\net les tomates cerises.", "Faire la sauce au yaourt : couper\nfinement la menthe, mélanger\navec le yaourt et le jus de\ncitron. Saler et poivrer.\nsalade au\npoulet grillé"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0a66c9ed4765', 'quiche sans pâte sardines et brocoli', null, 'été', 'septembre', 9, 4, 'jeudi', 'déjeuner/dîner', 'salé', 'brocoli', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/quiche-sans-pate-sardines-et-brocoli.jpg', '[{"name": "¼ de brocoli", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 petite boîte de sardines au naturel", "canonical": true}, {"name": "½ verre de crème liquide", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et découper en morceaux\nle brocoli.", "Dans une casserole d’eau\nbouillante salée, faire cuire", "Dans un bol, fouetter les œufs\navec la crème et le lait.", "Ajouter la farine et mélanger.", "Couper en petits morceaux\nles sardines. Ajouter\nles sardines et le brocoli cuit\ndans la préparation d’œufs.\nSaler et poivrer.", "Verser dans un plat et faire\ncuire pendant 6 à 8 min\nau micro-ondes à puissance\nmaximale.\nquiche sans pâte\nsardines et brocoli"]'::jsonb, null, true, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7a7dfd839251', 'salade de haricots blancs', null, 'été', 'septembre', 9, 4, 'vendredi', 'déjeuner/dîner léger', 'salé', 'brocoli', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-haricots-blancs.jpg', '[{"name": "1 petite boîte de haricots blancs", "canonical": true}, {"name": "1 petite boîte de maïs", "canonical": true}, {"name": "½ courgette", "canonical": true}, {"name": "½ barquette de tomates cerises", "canonical": true}, {"name": "1 oignon rouge", "canonical": true}, {"name": "Persil frais (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper\nla demi courgette et l’oignon\nrouge en petits dés.", "Laver et couper le persil. Laver\net couper les tomates cerises\nen deux.", "Égoutter et rincer le maïs\net les haricots blancs.", "Dans un saladier, mélanger\nl’ensemble des ingrédients."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b9d1ce701da8', 'brioche perdue caramel au beurre salé', null, 'été', 'septembre', 9, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/brioche-perdue-caramel-au-beurre-sale.jpg', '[{"name": "4 tranches de brioche", "canonical": true}, {"name": "½ plaquette de beurre demi-sel", "canonical": true}, {"name": "4 c. à s. de sucre", "canonical": true}, {"name": "1 petit verre de lait", "canonical": true}, {"name": "2 œufs", "canonical": true}]'::jsonb, '["Dans un bol, battre les œufs\nen omelette. Ajouter le lait et 2 c.\nà s. de sucre.", "Dans une casserole chaude, faire\nfondre", "Quand le caramel est liquide et\nhomogène, le verser dans un bol.", "Dans une poêle chaude, faire\nchauffer", "Disposer les tranches de brioche\ndans des assiettes et napper\nde caramel.\nbrioche perdue\ncaramel au beurre\nsalé\n1\nTu peux ajouter une\nboule de glace à la vanille si tu le\nsouhaites."]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('048c0c0fb076', 'galettes aux flocons d’avoine', null, 'été', 'septembre', 9, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/galettes-aux-flocons-d-avoine.jpg', '[{"name": "½ verre de quinoa cru", "canonical": true}, {"name": "½ verre de lait", "canonical": true}, {"name": "1 c. à c. de miel ou de sucre", "canonical": true}]'::jsonb, '["Dans une casserole chaude,\nverser", "Faire cuire pendant 15 à 20\nmin à feu doux en mélangeant.", "Ajouter le miel ou le sucre\nen dehors du feu et mélanger.", "Verser dans un bol et déguster.\nquinoa façon\nriz au lait\n4"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('906736cf6bfd', 'pana cotta au coulis de fruits rouges', null, 'été', 'septembre', 9, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pana-cotta-au-coulis-de-fruits-rouges.jpg', '[{"name": "1 dizaine de framboises", "canonical": true}, {"name": "1 dizaine de mûres", "canonical": true}, {"name": "1 feuille de gélatine", "canonical": true}, {"name": "2 c. à s. de sucre", "canonical": true}, {"name": "½ pot de mascarpone", "canonical": true}, {"name": "½ verre de lait", "canonical": true}]'::jsonb, '["Laisser tremper la feuille\nde gélatine dans un bol d’eau\nfroide.", "Dans une casserole chaude\nà feu doux,", "Ajouter le mascarpone et 1 c.\nà s. de sucre. Mélanger. Arrêter\njuste avant ébullition.", "Ajouter la feuille de gélatine.\nMélanger. Verser dans des\nramequins et laisser prendre\nau réfrigérateur pendant 1h.", "Dans un bol, écraser les\nframboises et"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cfff99d65e31', 'petits suisses glacés aux fruits', null, 'été', 'septembre', 9, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/petits-suisses-glaces-aux-fruits.jpg', '[{"name": "2 petits suisses", "canonical": true}, {"name": "1 c. à c. de miel", "canonical": true}, {"name": "6 framboises", "canonical": true}]'::jsonb, '["Dans un bol, mélanger les petits\nsuisses avec le miel et\nles framboises. Garder et laver\nles pots des petits suisses,\nils vont servir de moules.", "Verser la préparation dans\nles pots puis placer un batônnet\nen bois ou des cure-dents.", "Mettre au freezer pendant\nau moins 2h.\npetits suisses glacés\naux fruits\n2"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c2f89b856e46', 'quinoa façon riz au lait', null, 'été', 'septembre', 9, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/quinoa-facon-riz-au-lait.jpg', '[{"name": "½ verre de flocons d’avoine", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 pot de fromage blanc (100g)", "canonical": true}, {"name": "2 c. à c. d’huile de tournesol", "canonical": true}]'::jsonb, '["Battre l’œuf dans un bol.", "Ajouter le fromage blanc\net les flocons d’avoine.", "Dans une poêle chaude huilée,\ndéposer des galettes du\nmélange à l’aide de 2 cuillères.", "Laisser cuire 2-3 min puis\nretourner pour faire cuire\nl’autre côté.\ngalettes aux flocons\nd’avoine"]'::jsonb, null, false, true, 'crous', 'CalendrierRecetteEte_2025.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('fb418278fe79', 'filet de poulet à l’estragon et pommes de terre', null, 'automne', 'octobre', 10, 1, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/filet-de-poulet-a-l-estragon-et-pommes-de-terre.jpg', '[{"name": "2 filets de poulet", "canonical": true}, {"name": "1 c. à s. d''estragon (EN OPTION)", "canonical": true}, {"name": "2 grosses pommes de terre", "canonical": true}, {"name": "Une noisette de beurre", "canonical": true}, {"name": "1 c. à s. de crème", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et découper\nles pommes de terre. Dans\nune casserole d’eau bouillante\nsalée, les faire cuire 15 min.", "Dans une poêle avec une\nnoisette de beurre, faire dorer\nles pommes de terre à feu\nmoyen puis les mettre de côté.", "Dans la même poêle, faire cuire\nle poulet 3 min de chaque\ncôté puis ajouter la crème et\nl’estragon. Saler et poivrer."]'::jsonb, 'Pour un repas complet, ajoute une salade de crudités (carottes, salade, champignons…).', false, true, 'crous', 'Calendrier recettes_automne.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a9d38d95e253', 'champignons farcis à la feta', null, 'automne', 'octobre', 10, 1, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/champignons-farcis-a-la-feta.jpg', '[{"name": "4 gros champignons", "canonical": true}, {"name": "1 petite barquette de feta", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "Brins de persil (EN OPTION)", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "Poivre", "canonical": true}, {"name": "1 c. à s. d''huile d''olive", "canonical": true}]'::jsonb, '["Nettoyer les champignons et\nenlever le pied.", "Couper l’échalote et le persil.\nÉcraser la feta à la fourchette et\najouter l’œuf, l’échalote coupée\nen dés, le persil et le poivre.\nMélanger.", "Garnir les champignons avec\nla farce.", "Verser un peu d’huile dans\nune poêle puis faire dorer"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2561b2f8cd2b', 'tagliatelles au saumon et aux épinards', null, 'automne', 'octobre', 10, 1, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tagliatelles-au-saumon-et-aux-epinards.jpg', '[{"name": "Une poignée de tagliatelles", "canonical": true}, {"name": "2 tranches de saumon fumé", "canonical": true}, {"name": "1 petite boîte d’épinards", "canonical": true}, {"name": "1 verre de crème", "canonical": true}, {"name": "1 c. à c. d’aneth (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire cuire les tagliatelles\ndans une eau bouillante salée\n(temps de cuisson indiqué sur\nle paquet).", "Découper le saumon en\npetits cubes.", "Dans une casserole, faire\ncuire", "Mélanger les pâtes avec\nla sauce.\ntagliatelles\nau saumon\net aux épinards\nAvec le saumon, fais\nle plein d’oméga 3 pour optimiser\nta mémoire et prendre soin de ton\nmicrobiote intestinal !"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('95ef59912202', 'œufs brouillés carotte et oignon', null, 'automne', 'octobre', 10, 1, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/oeufs-brouilles-carotte-et-oignon.jpg', '[{"name": "2 œufs", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "2 tranches de pain de campagne", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer et éplucher la carotte.\nÀ l’aide d’un épluche-légumes\nfaire des fines lamelles (comme\ndes tagliatelles).", "Couper l’oignon en dés. Le faire\ncuire dans une poêle huilée\navec la carotte.", "Casser les œufs par-dessus et\najouter sel et poivre. Mélanger\nconstamment à l’aide d’une\nspatule en bois. Ajouter\nle lait et mélanger à nouveau\nafin d‘obtenir une texture\nonctueuse.", "Tartiner sur 2 morceaux\nde pain de campagne.\nœufs brouillés\ncarotte et oignon"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1186aca1a0e7', 'falafels faciles', null, 'automne', 'octobre', 10, 1, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/falafels-faciles.jpg', '[{"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "1 petite boîte de petits pois", "canonical": true}, {"name": "6 c. à s. de boulgour", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. de cumin (EN OPTION)", "canonical": true}, {"name": "5 c. à c. de tahini (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Placer le boulgour dans un bol et\nverser de l’eau bouillante jusqu’à\n1 cm au-dessus. Couvrir et laisser\ngonfler doucement. S’il reste de\nl’eau, placer 3 min au micro-ondes.", "Dans un autre bol, écraser\ngrossièrement à", "Faire cuire les boulettes 10 min\ndoucement dans une poêle avec\nde l’huile, 5 min sur chaque face.\nfalafels faciles\nCéréales\n(boulgour) et légumineuses (pois\nchiches), le combo parfait pour\ndes protéines complètes lorsqu’on\nne souhaite pas manger de viande."]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 5, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('43374dfc8f63', 'salade de pois chiches et chou rouge', null, 'automne', 'octobre', 10, 2, 'lundi', 'déjeuner/dîner léger', 'salé', 'chou rouge', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-pois-chiches-et-chou-rouge.jpg', '[{"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "¼ de chou rouge", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "½ paquet de lardons", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "1 c. à c. de cumin (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer, couper le chou rouge\net l’oignon.", "Faire cuire les lardons dans\nune poêle et ajouter un peu de\nvinaigre balsamique.", "Égoutter et rincer les pois\nchiches.", "Mélanger le chou rouge,\nl’oignon, les lardons et les\npois chiches. Saler et poivrer.\nAjouter le cumin et l’huile.\nMélanger le tout.\nsalade\nde pois chiches\net chou rouge"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('696a27dabcd5', 'croque-monsieur croustillant à la poêle', null, 'automne', 'octobre', 10, 2, 'mardi', 'déjeuner/dîner', 'salé', 'chou rouge', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/croque-monsieur-croustillant-a-la-poele.jpg', '[{"name": "2 tranches de pain de mie (COMPLET DE PRÉFÉRENCE)", "canonical": true}, {"name": "1 tranche de jambon blanc", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "2 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 c. à c. de crème fraîche", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à c. de muscade (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de ciboulette (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger\nla crème et l’œuf. Ajouter\nl’emmental, la muscade et\nla ciboulette.", "Beurrer les faces extérieures du\npain de mie.", "Déposer la préparation crème et\nœuf sur les faces intérieures du\npain de mie. Ajouter le jambon\npuis refermer le croque-monsieur.", "Dans une poêle à feu doux,\nfaire dorer sur"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('fe3d8d576dcd', 'brandade de poisson blanc à la béchamel', null, 'automne', 'octobre', 10, 2, 'mercredi', 'déjeuner/dîner', 'salé', 'chou rouge', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/brandade-de-poisson-blanc-a-la-bechamel.jpg', '[{"name": "1 filet de poisson blanc", "canonical": true}, {"name": "7 pommes de terre (EN GARDER 2 POUR VENDREDI)", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "10 cl de lait (1 PETIT VERRE)", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. de muscade (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et éplucher les pommes de\nterre. Les couper en dés puis les\ncuire 10 à 15 min dans une eau\nbouillante salée. Les égoutter.\nMettre de côté ¼ des pommes\nde terre cuites pour la recette\nde vendredi. Écraser les pommes\nde terre.", "Faire cuire le poisson dans l’eau\nde cuisson des pommes de terre.", "Pour la béchamel, verser le\nbeurre dans une casserole et\najouter la farine. Mélanger\npuis ajouter le lait. Mélanger\nen continu, la béchamel doit\népaissir. Ajouter la muscade, le\npersil, saler et poivrer.", "Écraser le poisson blanc, l’ajouter\nà la béchamel et mélanger.\nAjouter cette préparation aux\npommes de terre.\nbrandade de poisson\nblanc à la béchamel"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7a1a4690ec87', 'gratin de chou rouge au micro-ondes', null, 'automne', 'octobre', 10, 2, 'jeudi', 'déjeuner/dîner', 'salé', 'chou rouge', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gratin-de-chou-rouge-au-micro-ondes.jpg', '[{"name": "½ chou rouge", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "2 noisettes de beurre", "canonical": true}, {"name": "20 cl de lait (1 GRAND VERRE)", "canonical": true}, {"name": "2 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 c. à s. de muscade (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper le chou rouge en\nfines lamelles et le cuire dans une\neau bouillante salée.", "Pour la béchamel, verser le\nbeurre dans une casserole et\najouter la farine. Mélanger\npuis ajouter le lait. Mélanger\nen continu, la béchamel doit\népaissir. Ajouter la muscade, saler\net poivrer.", "Disposer le chou rouge dans un\nplat, recouvrir de béchamel et\najouter l’emmental sur le dessus.", "Faire cuire 5 min au micro-ondes\npour que"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('77d0eb8e8269', 'purée de carotte et pommes de terre', null, 'automne', 'octobre', 10, 2, 'vendredi', 'déjeuner/dîner', 'salé', 'chou rouge', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/puree-de-carotte-et-pommes-de-terre.jpg', '[{"name": "1 carotte", "canonical": true}, {"name": "2 grosses pommes de terre (UTILISER LES POMMES DE TERRE CUITES DU MERCREDI)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 c. à c. de muscade (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer et éplucher la carotte. La\ncouper et la faire cuire dans une\neau bouillante salée.", "Écraser la carotte et les\npommes de terre cuites dans\nun bol à l’aide d’une fourchette,\najouter le beurre et le lait.\nBien mélanger.", "Saler, poivrer et ajouter la\nmuscade. Bien mélanger.\npurée de carotte\net pommes de terre"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 6, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7b38cb278f78', 'wrap saumon fumé et fromage frais', null, 'automne', 'octobre', 10, 3, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/wrap-saumon-fume-et-fromage-frais.jpg', '[{"name": "2 tortillas au blé complet", "canonical": true}, {"name": "2 tranches de saumon fumé", "canonical": true}, {"name": "2 c. à s. de fromage frais", "canonical": true}, {"name": "2 poignées de mâche", "canonical": true}]'::jsonb, '["Étaler le fromage frais sur\nles wraps.", "Disposer une tranche de\nsaumon et un peu de mâche\nsur chaque tortilla.", "Refermer les wraps en\nles pliant.\nCette recette se\ndécline à l’infini, avec tous les\naliments (ou presque) qui peuvent\nêtre au fond de ton réfrigérateur."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('dfe15cd09fb8', 'poulet à la crème et aux champignons', null, 'automne', 'octobre', 10, 3, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poulet-a-la-creme-et-aux-champignons.jpg', '[{"name": "1 escalope de poulet", "canonical": true}, {"name": "1 verre de riz", "canonical": true}, {"name": "3 champignons de Paris", "canonical": true}, {"name": "1 c. à s. de jus d''1 citron", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}, {"name": "1 petit verre de crème fraîche", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper l’escalope de poulet en\nmorceaux et", "Couper les champignons et les\najouter dans la poêle. Ajouter\nle jus de citron et les herbes\nde Provence.", "Ajouter la crème. Mélanger.\nSaler et poivrer.", "Dans une casserole d’eau\nbouillante salée, faire cuire le\nriz pendant 8 à 10 min.", "Déguster le riz avec le poulet.\npoulet à la crème\net aux champignons"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0f21c543797d', 'burritos aux haricots rouges', null, 'automne', 'octobre', 10, 3, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/burritos-aux-haricots-rouges.jpg', '[{"name": "2 tortillas au blé complet", "canonical": true}, {"name": "1 petite boîte de haricots rouges", "canonical": true}, {"name": "1 petite boîte de coulis de tomates", "canonical": true}, {"name": "1 petite boîte de maïs", "canonical": true}, {"name": "2 c. à s. de fromage râpé", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "2 c. à s. de yaourt nature (MANGER LE RESTE EN DESSERT)", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de paprika (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper l’oignon.", "Dans une casserole huilée,\nfaire cuire", "Sur chaque tortilla, étaler une\nc. à s. de yaourt puis répartir la\npréparation de haricots rouges.\nRecouvrir de fromage râpé.", "Rabattre les bords, rouler et\ndéposer le burrito dans une\npoêle chaude. Le laisser griller 30\nsec à 1 min de chaque côté.\nburritos aux haricots\nrouges"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2cbeadc63169', 'omelette à la ciboulette et chèvre frais', null, 'automne', 'octobre', 10, 3, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/omelette-a-la-ciboulette-et-chevre-frais.jpg', '[{"name": "4 œufs", "canonical": true}, {"name": "2 c. à s. de chèvre frais", "canonical": true}, {"name": "1 c. à s. de ciboulette (EN OPTION)", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "1 c. à s. de piment d’Espelette en poudre (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Battre les 4 œufs dans un\nsaladier. Ajouter la ciboulette\net le piment d’Espelette.", "Faire fondre le beurre dans\nune poêle et cuire les œufs en\nremuant pendant une min.", "Ajouter le fromage de chèvre.\nPoivrer.", "Replier l’omelette.\nomelette\nà"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8d9d4a89d6ff', 'samoussas de patate douce', null, 'automne', 'octobre', 10, 3, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/samoussas-de-patate-douce.jpg', '[{"name": "6 feuilles de brick", "canonical": true}, {"name": "1 petite patate douce", "canonical": true}, {"name": "1 petite boîte de petits pois", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à c. de cumin", "canonical": true}, {"name": "1 c. à c. de curry", "canonical": true}, {"name": "1 c. à c. de paprika", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer, éplucher et couper la\npatate douce en morceaux. La\nfaire cuire dans une casserole\nd’eau bouillante salée pendant\n10 à 15 min.", "Éplucher et couper l’oignon. Le\nfaire cuire dans une poêle huilée.", "Dans une assiette creuse, écraser", "Prendre une c. à s. de la\npréparation et", "Dans une poêle avec 2 c. à s.\nd’huile de tournesol, faire cuire\nles samoussas.\nsamoussas\nde patate douce"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 7, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c68cb93e1e53', 'salade de haricots, pommes de terre et thon', null, 'automne', 'octobre', 10, 4, 'lundi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-haricots-pommes-de-terre-et-thon.jpg', '[{"name": "3 pommes de terre", "canonical": true}, {"name": "1 boîte de haricots verts", "canonical": true}, {"name": "1 petite boîte de thon", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "2 échalotes", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de vinaigre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper les\npommes de terre en dés. Les\ncuire dans une eau bouillante\nsalée pendant 10 à 15 min.", "Cuire les œufs pendant 10 min\ndans une autre casserole d’eau\nbouillante. Enlever la coquille et\nles couper en morceaux.", "Couper les échalotes en dés.", "Dans un saladier, mélanger les\npommes de terre cuites, les\nharicots égouttés,", "Ajouter l’huile et le vinaigre, saler\net poivrer.\nsalade de haricots,\npommes de terre\net thon\nLe thon est dit\n« bioaccumulateur ». Il a tendance\nà accumuler les polluants\ndans sa chair. Il est important\nde limiter sa consommation."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('4dc4d23791bf', 'pizza tartine', null, 'automne', 'octobre', 10, 4, 'mardi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/pizza-tartine.jpg', '[{"name": "2 tranches de pain de campagne", "canonical": true}, {"name": "2 c. à s. de coulis de tomates", "canonical": true}, {"name": "2 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 petit paquet de feta", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "2 champignons", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. d’origan (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper l’oignon et les\nchampignons en dés et les faire\ncuire dans une poêle huilée.", "Dans un bol, mélanger le coulis\nde tomates avec l’origan. Saler\net poivrer.", "Verser 1 c. à s. de coulis de\ntomates", "Déposer le mélange d’oignon\net champignons.", "Émietter la feta et l’ajouter\nsur chaque tartine. Ajouter\nl’emmental.", "Passer au micro-ondes 5 min\npour que"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('ec398197ac31', 'riz complet façon cantonais', null, 'automne', 'octobre', 10, 4, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/riz-complet-facon-cantonais.jpg', '[{"name": "1 verre de riz complet", "canonical": true}, {"name": "1 tranche de jambon", "canonical": true}, {"name": "1 petite boîte de petits pois", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 petit oignon", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de sauce soja", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire cuire le riz dans une eau\nbouillante salée (temps indiqué\nsur le paquet).", "Découper le jambon en dés.", "Éplucher et couper un oignon, le\nfaire cuire dans une poêle avec\nl’huile d’olive.", "Battre l’œuf à l’aide d’une\nfourchette puis le verser dans la\npoêle sur les oignons.", "Dès que l’omelette est cuite,\nla couper en petits morceaux.\nAjouter le riz cuit, les petits\npois et les dés de jambon. Saler,\npoivrer puis mélanger.", "Retirer la poêle du feu et ajouter\nla sauce soja avant de servir\nriz complet façon\ncantonais\nIl est recommandé\nde consommer les produits\ncéréaliers complets (semi-complets\npour une meilleure digestion)\ncar ils sont riches en fibres."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e3a88c1dc893', 'curry de pois chiches', null, 'automne', 'octobre', 10, 4, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/curry-de-pois-chiches.jpg', '[{"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 petit verre de crème de coco", "canonical": true}, {"name": "1 verre de coulis de tomates", "canonical": true}, {"name": "½ c. à c. de curry", "canonical": true}, {"name": "½ c. à c. de curcuma", "canonical": true}, {"name": "1 c. à c. de coriandre (EN OPTION)", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Peler et tailler finement l’oignon\net l’ail.", "Faire cuire l’oignon et l’ail\ndans une casserole chaude et\nhuilée. Ajouter les épices et\nla coriandre.", "Ajouter les pois chiches, la\ncrème de coco et le coulis de\ntomates. Saler et poivrer.", "Poursuivre la cuisson 5 min\nà découvert.\ncurry de pois chiches\nTu peux acheter des pois\nchiches en boîte. Ils sont\ndéjà cuits, c’est plus économique\net rapide."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('333cc471a4bb', 'gnocchis sauce feta et épinards', null, 'automne', 'octobre', 10, 4, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/gnocchis-sauce-feta-et-epinards.jpg', '[{"name": "1 petit paquet de gnocchis", "canonical": true}, {"name": "1 petit paquet de feta", "canonical": true}, {"name": "1 verre de crème", "canonical": true}, {"name": "1 petite boîte d’épinards", "canonical": true}, {"name": "1 c. à c. de muscade (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Couper la feta en morceaux\net la faire fondre dans une\ncasserole avec la crème.", "Ajouter les épinards et la\nmuscade. Poivrer.", "Faire cuire les gnocchis dans\nune eau bouillante salée\npendant quelques minutes\n(jusqu’à ce qu’ils remontent à la\nsurface).", "Mélanger les gnocchis dans\nla sauce.\ngnocchis sauce feta\net épinards"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 8, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6a73a78edab8', 'clafoutis à la poire au micro-ondes', null, 'automne', 'octobre', 10, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/clafoutis-a-la-poire-au-micro-ondes.jpg', '[{"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "70 ml de lait (ENV. ½ VERRE)", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "1 petite poire ou ½ grande poire", "canonical": true}]'::jsonb, '["Mélanger l’œuf et le sucre.\nAjouter la farine et mélanger.", "En mélangeant, verser le lait\npetit à petit.", "Laver, éplucher et couper la\npoire en morceaux.", "Disposer les morceaux de\npoire au fond d’un ramequin et\nverser le mélange par-dessus.", "Faire cuire 5 à 10 min au\nmicro‑ondes."]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6d1b0d8b4116', 'compote de pomme à la cannelle', null, 'automne', 'octobre', 10, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/compote-de-pomme-a-la-cannelle.jpg', '[{"name": "1 pomme", "canonical": true}, {"name": "½ c. à c. de cannelle en poudre", "canonical": true}, {"name": "1 sachet de sucre vanillé", "canonical": true}]'::jsonb, '["Laver, éplucher et couper la\npomme en petits morceaux. La\nmettre dans une casserole sur\nfeu doux", "Ajouter le sucre vanillé et la\ncannelle. Mélanger et faire cuire\njusqu’à ce que la pomme soit\nréduite en purée.\ncompote de pomme à\nla cannelle\n2"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3a98d3801440', 'gâteau au chocolat à la poêle', null, 'automne', 'octobre', 10, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gateau-au-chocolat-a-la-poele.jpg', '[{"name": "¾ d’une tablette de chocolat", "canonical": true}, {"name": "50 g de beurre (1/5 D’UNE PLAQUETTE DE BEURRE DE 250G)", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "8 c. à s. de farine", "canonical": true}, {"name": "1 c. à c. de levure chimique", "canonical": true}, {"name": "1 c. à s. de poudre de coco", "canonical": true}, {"name": "3 c. à s. de sucre", "canonical": true}, {"name": "10 cl de lait (1 PETIT VERRE)", "canonical": true}]'::jsonb, '["Faire fondre le beurre et le\nchocolat au micro-ondes.", "Dans un saladier, mélanger les\nœufs et", "Ajouter le beurre et le chocolat\nfondu à la pâte.", "Déposer une feuille de papier\ncuisson au fond d’une poêle\npour éviter que"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('20d8c0e2f8ed', 'porridge banane chocolat', null, 'automne', 'octobre', 10, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/porridge-banane-chocolat.jpg', '[{"name": "3 c. à s. de flocons d’avoine", "canonical": true}, {"name": "15 cl de lait (1 PETIT VERRE PLEIN)", "canonical": true}, {"name": "1 banane", "canonical": true}, {"name": "4 carrés de chocolat", "canonical": true}, {"name": "1 c. à c. de graines de chia", "canonical": true}]'::jsonb, '["Couper la banane en deux.\nÉcraser à l’aide d’une fourchette\nune moitié.", "Dans une casserole, faire cuire", "Ajouter la demi banane écrasée\net les graines de chia dans la\ncasserole. Mélanger. Laisser les\nflocons absorber le lait.", "Verser dans un bol. Ajouter\nles carrés de chocolat dans le\nporridge pour qu’ils fondent.", "Couper l’autre moitié de la\nbanane en tranche et disposer"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3be5a0f93cfb', 'semoule au lait', null, 'automne', 'octobre', 10, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/semoule-au-lait.jpg', '[{"name": "2 c. à s. de semoule", "canonical": true}, {"name": "20 cl de lait (1 GRAND VERRE)", "canonical": true}, {"name": "1 c. à s. de raisins secs", "canonical": true}, {"name": "½ c. à c. de cannelle", "canonical": true}, {"name": "1 sachet de sucre vanillé", "canonical": true}]'::jsonb, '["Faire bouillir le lait avec le\nsucre vanillé.", "Ajouter la semoule\net la cannelle. Sur feu\ndoux, mélangez jusqu''à\népaississement (5 min environ).", "Ajouter les raisins secs.\nMélanger. Verser dans\nun ramequin.\nsemoule au lait\n3"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 9, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a79e7dd0a0f7', 'tortilla de maïs auxlégumes', null, 'automne', 'novembre', 11, 1, 'lundi', 'déjeuner/dîner', 'salé', 'panais', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tortilla-de-mais-auxlegumes.jpg', '[{"name": "2 c. à s. de semoule de maïs (polenta)", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 panais (GARDER LA MOITIÉ POUR LA RECETTE DE JEUDI)", "canonical": true}, {"name": "2 champignons", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. de crème fraîche", "canonical": true}, {"name": "1 c. à c. de muscade (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, rincer et couper\nl’oignon, l’ail, les champignons et\nle panais en petits dés.", "Cuire le panais pendant 10\nmin dans une casserole d’eau\nbouillante salée.", "Faire cuire tous les légumes (avec\nle panais cuit) dans une poêle\navec 1 c. à s. d’huile d’olive.\nAjouter la crème et la muscade.\nSaler, poivrer et mélanger.", "Verser la semoule de maïs et 1\nverre d’eau dans une casserole.\nSaler et poivrer. Mettre à\nchauffer et mélanger. Le mélange\ndoit épaissir. Ajouter la semoule\nde maïs dans une autre poêle\navec 1 c. à s. d’huile d’olive.\nVerser la garniture sur la semoule\nde maïs."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('09393b03a115', 'pâtes et lentilles au persil ', null, 'automne', 'novembre', 11, 1, 'mardi', 'déjeuner/dîner', 'salé', 'panais', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/pates-et-lentilles-au-persil.jpg', '[{"name": "5 c. à s. de pâtes", "canonical": true}, {"name": "2 c. à s. de lentilles vertes en conserve", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire les pâtes dans une\ncasserole d’eau bouillante salée\n(temps indiqué sur le paquet).", "Égoutter les lentilles vertes.", "Couper l’échalote en dés. Dans\nun bol, mélanger l’échalote,\nl’huile et", "Lorsque les pâtes sont cuites,\nles égoutter. Les mélanger aux\nlentilles. Mélanger les pâtes et\nles lentilles à la sauce au persil\net à l’échalote.\npâtes et lentilles\nau persil"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('90c61138bcd9', 'samoussas au poulet, curry et chorizo ', null, 'automne', 'novembre', 11, 1, 'mercredi', 'déjeuner/dîner', 'salé', 'panais', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/samoussas-au-poulet-curry-et-chorizo.jpg', '[{"name": "1 paquet de feuilles de brick", "canonical": true}, {"name": "1 filet de poulet", "canonical": true}, {"name": "2 petits fromages (TYPE FROMAGE FRAIS)", "canonical": true}, {"name": "Chorizo (À TA CONVENANCE)", "canonical": true}, {"name": "1 c. à s. de ciboulette (EN OPTION)", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 c. à s. de crème fraîche épaisse", "canonical": true}, {"name": "1 c. à c. de moutarde à l’ancienne", "canonical": true}, {"name": "½ c. à c. de curry", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Découper le poulet et le\nchorizo en petits morceaux.", "Dans une poêle huilée, faire\ncuire", "Ajouter la moutarde, le curry,\nla ciboulette et le poivre puis\nlaisser reposer.", "Ajouter le chorizo\nà la préparation.", "Garnir des demi feuilles de\nbrick et plier", "Faire dorer les\nsamoussas à feu doux\ndans de l’huile.\nsamoussas au poulet,\ncurry et chorizo"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6546f42653d8', 'polenta aux légumes d’automne', null, 'automne', 'novembre', 11, 1, 'jeudi', 'déjeuner/dîner', 'salé', 'panais', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/polenta-aux-legumes-d-automne.jpg', '[{"name": "4 c. à s. de polenta (semoule de maïs)", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "½ panais (LA MOITIÉ DU PANAIS DE LA RECETTE DU LUNDI)", "canonical": true}, {"name": "1 petite carotte", "canonical": true}, {"name": "2 champignons de Paris", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et éplucher les légumes.\nLes couper en petits dés et\nles faire cuire dans une poêle\nhuilée. Ajouter le demi panais\ncuit lundi.", "Ajouter des herbes de\nProvence, saler et poivrer.", "Faire chauffer le lait dans une\ncasserole et ajouter la polenta.\nSaler, poivrer et mélanger. Le\nmélange doit épaissir.", "Ajouter les légumes à la\npolenta. Mélanger à nouveau.\npolenta aux légumes\nd’automne"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('8255e6465b81', 'endives au thon', null, 'automne', 'novembre', 11, 1, 'vendredi', 'déjeuner/dîner', 'salé', 'panais', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/endives-au-thon.jpg', '[{"name": "1 grosse endive", "canonical": true}, {"name": "3 petits fromages (type fromage frais)", "canonical": true}, {"name": "1 petite boîte de conserve de thon", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer l’endive. Enlever et\nmettre de côté", "Dans un bol, mélanger le thon,\nles morceaux du cœur de\nl’endive, le fromage frais et le\npersil. Saler et poivrer.", "Ajouter la farce dans les feuilles\nexternes des endives.\nendives au thon"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 12, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c25b193735ac', 'galettes tortillas aux légumes d’automne', null, 'automne', 'novembre', 11, 2, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/galettes-tortillas-aux-legumes-d-automne.jpg', '[{"name": "1 chou-fleur (GARDER LA MOITIÉ POUR MERCREDI)", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "2 tortillas de blé complet", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "2 fromages frais", "canonical": true}, {"name": "2 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer le chou-fleur et le couper\nen petits morceaux. Mettre de\ncôté la moitié pour mercredi.", "Rincer, éplucher et couper la\ncarotte et", "Dans un bol, mélanger le chou, la\ncarotte, l’oignon, l’huile d’olive et\nle fromage frais.", "Mélanger les œufs à l’aide\nd’une fourchette. Dans une\npoêle huilée, verser les œufs et\nlaisser cuire l’omelette pendant\nquelques minutes. Saler, poivrer\net bien mélanger.", "Lorsqu’elle est cuite, couper\nl’omelette en 2. Ajouter les\ngalettes tortilla par-dessus et\nretourner le tout. Ajouter les\nlégumes et le fromage frais à\nl’intérieur et plier les tortillas\nen 2.\ngalettes tortillas aux\nlégumes d’automne"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('97e496446f3a', 'salade d’endives et sardines', null, 'automne', 'novembre', 11, 2, 'mardi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-d-endives-et-sardines.jpg', '[{"name": "1 petite endive", "canonical": true}, {"name": "1 grosse pomme de terre", "canonical": true}, {"name": "1 boite de sardines", "canonical": true}, {"name": "Quelques cerneaux de noix (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Rincer la pomme de terre, la\ncouper en dés et la faire cuire\ndans une eau bouillante salée\npendant 10 à 15 min.", "Rincer l’endive et la couper.\nCouper les sardines\nen morceaux.", "Dans un bol, mélanger les\nmorceaux de pomme de terre\ncuite, de sardines et d’endive.", "Ajouter des cerneaux de noix\ncoupés, l’huile et le vinaigre.\nSaler et poivrer puis mélanger\nà nouveau.\nsalade d’endives et\nsardines\nAvec la sardine,\nles noix et l’huile de colza, fais le\nplein d’oméga 3 pour optimiser ta\nmémoire pendant des périodes\nde révision."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e530e7c0870f', 'porridge salé', null, 'automne', 'novembre', 11, 2, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/porridge-sale.jpg', '[{"name": "3 c. à s. de flocons d’avoine", "canonical": true}, {"name": "3 c. à s. de lentilles corail", "canonical": true}, {"name": "1 verre de lait", "canonical": true}, {"name": "½ chou-fleur (UTILISÉ DANS LA RECETTE DU LUNDI)", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 c. à c. de graines de sésame", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, couper l’oignon et la\ncarotte en dés.", "Dans une poêle huilée, cuire\npendant 15 min", "Dans une casserole, cuire les\nflocons d’avoine et", "Ajouter les légumes cuits et les\ngraines de sésame. Mélanger et\nle servir dans un bol.\nporridge salé\nLes flocons\nd’avoine et les lentilles corail\nsont riches en fibres (ce qui\nrassasie plus longtemps)."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cdda114fa2f0', 'sticks de feta', null, 'automne', 'novembre', 11, 2, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/sticks-de-feta.jpg', '[{"name": "1 petit paquet de feta", "canonical": true}, {"name": "2 feuilles de brick", "canonical": true}, {"name": "4 c. à c. de miel (EN OPTION)", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}]'::jsonb, '["Couper la feta en 4 batônnets.", "Découper les feuilles de brick\nen deux. Déposer un bâtonnet\nde feta en bas de la feuille et\najouter une c. à c. de miel et\ndes herbes de Provence.", "Rouler la feuille vers le haut\njusqu’au tiers de la feuille. Plier\nchaque côté de la feuille vers\nl’intérieur et continuer à rouler.", "Cuire les sticks de feta dans une\npoêle huilée. Faire dorer\nchaque côté.\nsticks de feta\nCette recette peut être\nréalisée pour un apéritif. Elle peut\naussi se consommer comme un\nplat, avec une salade verte, une\nsalade d’endives ou une salade de\ncrudités."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3a5ea5d887d8', 'lasagnes à la poêle', null, 'automne', 'novembre', 11, 2, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/lasagnes-a-la-poele.jpg', '[{"name": "450 g de bœuf haché", "canonical": true}, {"name": "1 boule de mozzarella", "canonical": true}, {"name": "1 grande brique de coulis de tomates", "canonical": true}, {"name": "9 pâtes à lasagnes", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de de paprika (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une poêle chaude huilée,\nfaire cuire", "Ajouter le coulis de tomates\net laisser mijoter à feu moyen\npendant 10 min.", "Placer les pâtes à lasagnes dans\nla poêle et les recouvrir de la\nsauce bolognaise.", "Déposer les tranches de\nmozzarella sur la préparation\npuis les recouvrir de la\nsauce bolognaise.", "Laisser cuire à feu moyen 30\nà 35 min ("]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 13, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('bd39e7a91070', 'cordon bleu maki et son écrasé de pommes de terre', null, 'automne', 'novembre', 11, 3, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/cordon-bleu-maki-et-son-ecrase-de-pommes-de-terre.jpg', '[{"name": "2 escalopes de volaille", "canonical": true}, {"name": "8 tranches d’emmental", "canonical": true}, {"name": "2 tranches de jambon", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "1 bol de farine", "canonical": true}, {"name": "1 bol de chapelure", "canonical": true}, {"name": "4 pommes de terre moyennes", "canonical": true}, {"name": "2 échalotes", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper les pommes de terre\nen 4. Les cuire dans l’eau bouillante\nsalée pendant 10 à 15 min.", "Dans une casserole chaude huilée,\nfaire cuire l’échalote coupée en dés.", "Une fois les pommes de terre cuites,\nles écraser à l’aide d’une fourchette.\nSaler et poivrer. Ajouter les échalotes\net mélanger.", "Couper les escalopes en 2 afin de les\nouvrir « en portefeuille ». Les aplatir.\nAjouter 2 tranches d’emmental sur\nchaque escalope, une tranche de\njambon pliée en 2 et à nouveau\n2 tranches d’emmental. Enrouler\nl’escalope sur elle-même à l’aide d’un\npapier film. Nouer les 2 côtés.", "Cuire l’escalope pendant 20 min dans\nune eau bouillante.", "Battre les œufs à la fourchette. Saler\net poivrer.", "Lorsque les escalopes sont cuites\n(bien retirer le papier film), les passer\ndans la farine puis dans l’œuf et enfin\ndans la chapelure.", "Cuire et dorer les\nescalopes dans une poêle\nchaude huilée."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1f13228b8070', 'galettes de quinoa et lentilles vertes', null, 'automne', 'novembre', 11, 3, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/galettes-de-quinoa-et-lentilles-vertes.jpg', '[{"name": "6 c. à s. de quinoa", "canonical": true}, {"name": "6 c. à s. de lentilles vertes (OU PRENDRE DES LENTILLES EN CONSERVE)", "canonical": true}, {"name": "1 c. à s. de farine", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de paprika (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire les lentilles vertes dans\nune eau bouillante salée 15 min\n(ou simplement les égoutter si\nelles sont en conserve).", "Cuire le quinoa dans une eau\nbouillante salée pendant\n10 min.", "Mélanger le quinoa, les lentilles\net la farine. Ajouter les épices,\nsaler et poivrer.", "Former des boules en pressant\nbien", "Aplatir les boules pour former\ndes galettes puis les cuire dans\nune poêle huilée.\ngalettes de quinoa\net lentilles vertes"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('df290643a3cb', 'soupe anti-gaspi aux lentilles et pâtes', null, 'automne', 'novembre', 11, 3, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/soupe-anti-gaspi-aux-lentilles-et-pates.jpg', '[{"name": "Légumes qu’il te reste (LÉGUMES ABÎMÉS, FANES, LÉGUMES DÉJÀ CUITS …)", "canonical": true}, {"name": "2 c. à s. de lentilles corail (OU LENTILLES DE TON CHOIX)", "canonical": true}, {"name": "2 c. à s. de pâtes (OU UN RESTE DE QUINOA PAR EXEMPLE…)", "canonical": true}, {"name": "1 bouillon cube", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Éplucher, laver et couper les\nlégumes en petits morceaux.", "Cuire les pâtes et les lentilles.", "Dans une assiette creuse,\nmettre"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('7ace0d7a1bb3', 'gratin de pâtes au butternut et miel', null, 'automne', 'novembre', 11, 3, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gratin-de-pates-au-butternut-et-miel.jpg', '[{"name": "10 à 11 c. à s. de pâtes", "canonical": true}, {"name": "½ butternut (CONSERVER L’AUTRE MOITIÉ AU FRAIS POUR LA CUISINER LA SEMAINE PROCHAINE)", "canonical": true}, {"name": "2 c. à c. de miel (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "2 poignées d’emmental râpé", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper le butternut en\ncubes et le faire cuire dans une\ncasserole d’eau bouillante salée\npendant 15 min. Conserver la\nmoitié dans une boîte au frais\npour lundi.", "Cuire les pâtes dans une eau\nbouillante salée (temps de\ncuisson indiqué sur le paquet).", "Faire revenir les morceaux de\nbutternut dans une poêle huilée.\nAjouter le miel, les herbes de\nProvence et l’emmental râpé.\nSaler et poivrer. Mélanger avec les\npâtes cuites.\ngratin de pâtes\nau butternut et miel\nConserve au frais la\nmoitié du butternut pour la\nrecette de lundi prochain."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('cbe9be185b8a', 'fondue de poireaux et poisson blanc au curry', null, 'automne', 'novembre', 11, 3, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/fondue-de-poireaux-et-poisson-blanc-au-curry.jpg', '[{"name": "1 filet de poisson blanc", "canonical": true}, {"name": "1 poireau", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "2 c. à s. de crème", "canonical": true}, {"name": "2 à 4 c. à c. de curry", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire le poisson blanc dans une\ncasserole d’eau bouillante salée\npendant 10 min.", "Laver et couper le poireau et\nl’oignon. Les faire cuire dans\nune casserole avec un fond\nd’eau. Saler et poivrer.", "Dans une poêle, mettre le\npoisson,"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 14, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0a47643ce4b2', 'flan au butternut', null, 'automne', 'novembre', 11, 4, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/flan-au-butternut.jpg', '[{"name": "½ butternut", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 petit verre de crème épaisse", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de curcuma (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire colorer les morceaux de\nbutternut (cuits jeudi dernier)\ndans une poêle chaude huilée.\nAjouter les herbes de Provence.", "Battre les œufs dans un saladier.\nAjouter la farine, la crème, le\ncurry et le curcuma.\nSaler et poivrer.", "Déposer les morceaux de\nbutternut dans un plat. Verser le\nmélange œuf/crème par-dessus.", "Faire cuire 5 min au micro-ondes.\nflan au butternut"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('fb421dbeae8e', 'pommes de terre farcies aux maquereaux', null, 'automne', 'novembre', 11, 4, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/pommes-de-terre-farcies-aux-maquereaux.jpg', '[{"name": "2 pommes de terre moyennes", "canonical": true}, {"name": "1 boîte de maquereaux", "canonical": true}, {"name": "4 fromages frais", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper les\npommes de terre en 2 dans", "Peler et couper la gousse d’ail.", "Dans un bol, écraser les\nmaquereaux en purée puis", "Sortir les pommes de terre\nde l’eau et creuser un trou au\ncentre. Garder la chair pour en\nfaire de la purée et l’ajouter à\nla farce de maquereaux.", "Garnir les pommes de terre\navec la farce et les passer 5\nmin au micro-ondes.\npommes de terre\nfarcies aux\nmaquereaux\nLes maquereaux,\ncomme tous les poissons dits\n« gras » (thon, anchois, sardines…)\nsont riches en oméga 3, qui\nsont utiles au fonctionnement\ndu cerveau."]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b6218b834ee0', 'salade de quinoa, betterave et tofu', null, 'automne', 'novembre', 11, 4, 'mercredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-quinoa-betterave-et-tofu.jpg', '[{"name": "10 c. à s. de quinoa", "canonical": true}, {"name": "1 betterave cuite", "canonical": true}, {"name": "1 à 2 paquets de tofu fumé", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de vinaigre balsamique", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire le quinoa dans une\ncasserole d’eau bouillante salée\npendant 10 min.", "Couper la betterave et le tofu\nen petits cubes.", "Une fois le quinoa cuit, le\npasser sous l’eau froide.", "Mélanger le quinoa, la\nbetterave, le tofu et le persil,\nl’huile et le vinaigre.\nSaler et poivrer.\nsalade de quinoa,\nbetterave et tofu\nTu peux doubler les\nquantités pour pouvoir emporter\nle reste dans une boîte pour\nton déjeuner."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('9154529333e6', 'galettes bretonnes', null, 'automne', 'novembre', 11, 4, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/galettes-bretonnes.jpg', '[{"name": "13 c. à s. de farine de sarrasin", "canonical": true}, {"name": "5 œufs", "canonical": true}, {"name": "½ litre d’eau", "canonical": true}, {"name": "4 tranches de jambon blanc", "canonical": true}, {"name": "6 champignons de Paris frais (OU EN CONSERVE)", "canonical": true}, {"name": "6 c. à s. d’emmental râpé", "canonical": true}, {"name": "1 noisette de beurre", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Couper les champignons et le\njambon en fines lamelles.", "Dans un saladier, mélanger 2\nœufs et", "Dans une poêle beurrée et\nchaude, faire cuire", "Dans une autre poêle beurrée,\nverser une louche de pâte à\ngalette. Après 1 min, retourner", "Après 1 min, ajouter le jambon,\nles œufs au plat, les\nchampignons et le\nfromage râpé.\ngalettes bretonnes"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e54176f84018', 'dahl orange', null, 'automne', 'novembre', 11, 4, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/dahl-orange.jpg', '[{"name": "¾ d’un mug de lentilles corail", "canonical": true}, {"name": "1 petite patate douce", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "½ verre de coulis de tomates", "canonical": true}, {"name": "1 verre de lait de coco", "canonical": true}, {"name": "1 c. à c. de curry", "canonical": true}, {"name": "1 c. à c. de curcuma", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire les lentilles corail dans une\ncasserole d’eau bouillante salée\nenviron 8 min.", "Laver, éplucher et couper la\ncarotte et", "Peler et couper l’oignon et l’ail.", "Dans une casserole chaude\nhuilée, cuire quelques minutes"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 15, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('b4ad4ebf007b', 'crème au chocolat express', null, 'automne', 'novembre', 11, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/creme-au-chocolat-express.jpg', '[{"name": "2 verres de lait", "canonical": true}, {"name": "4 carrés de chocolat pâtissier (NOIR OU AU LAIT)", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "2 c. à s. de farine de blé", "canonical": true}]'::jsonb, '["Mélanger la farine avec un\ndemi verre de lait.", "Faire chauffer le reste du lait\navec le chocolat et le sucre\ndans une casserole.", "Quand le lait est chaud mais\npas bouillant, verser le premier\nmélange farine et lait. Mélanger\naussitôt au fouet. Maintenir\nun léger bouillonnement. Le\nmélange doit épaissir.", "Verser dans des ramequins\net garder au frais pendant au\nmoins 2 h.\ncrème au chocolat\nexpress\n3"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('18a14991d037', 'pancakes à la banane express', null, 'automne', 'novembre', 11, null, null, 'petit déjeuner', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/pancakes-a-la-banane-express.jpg', '[{"name": "1 banane bien mûre", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à c. d’huile de tournesol", "canonical": true}]'::jsonb, '["Dans un bol, écraser la\nbanane en purée à l’aide\nd’une fourchette.", "Casser l’œuf dans le bol et\nmélanger avec la banane.", "Dans une poêle huilée, cuire\nles pancakes.\npancakes à la banane\nexpress\nRajoute le topping de\nton choix (fruits, pâte à tartiner,\nconfiture…)"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('efd1512d0c40', 'salade de fruits d’automne', null, 'automne', 'novembre', 11, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-fruits-d-automne.jpg', '[{"name": "1 poire", "canonical": true}, {"name": "1 kiwi", "canonical": true}, {"name": "2 oranges", "canonical": true}, {"name": "1 banane", "canonical": true}]'::jsonb, '["Presser le jus d’une orange.", "Laver, éplucher et couper\nen petits cubes", "Verser le jus d’orange dessus.\nLes bananes noircissent\nau contact de l’air prolongé.\nCoupe-les et ajoute les juste avant\nde servir le dessert.\nsalade de fruits\nd’automne\n4"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('da567032945d', 'tiramisu orange et spéculoos', null, 'automne', 'novembre', 11, null, null, 'dessert', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/tiramisu-orange-et-speculoos.jpg', '[{"name": "2 c. à s. de mascarpone", "canonical": true}, {"name": "1 orange", "canonical": true}, {"name": "4 spéculoos", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}]'::jsonb, '["Séparer le jaune et le blanc de\nl’œuf. Mettre de côté le blanc\nd’œuf. Dans un saladier, mélanger\nle jaune d’œuf et le sucre à\nl’aide d’un fouet. Ajouter le\nmascarpone, mélanger.", "Presser le jus de la moitié de\nl’orange et l’ajouter. Mélanger.", "Monter les blancs en neige et\nles incorporer au mascarpone\n(passer cette étape si pas de\nfouet électrique).", "Casser les spéculoos en petits\nmorceaux. Faire de fines\ntranches d’orange avec la\ndeuxième moitié.", "Dans une verrine, mettre un peu\nde spéculoos et des tranches\nd’orange, puis du mascarpone.\nRépéter l’opération une 2ème\nfois. Sur"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6a8570965ad0', 'verrines de poires et crème de marrons', null, 'automne', 'novembre', 11, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/verrines-de-poires-et-creme-de-marrons.jpg', '[{"name": "2 petits pots de fromage blanc", "canonical": true}, {"name": "4 c. à c. de crème de marrons", "canonical": true}, {"name": "4 sablés bretons", "canonical": true}, {"name": "2 poires", "canonical": true}, {"name": "1 c. à s. de sucre", "canonical": true}, {"name": "Une noisette de beurre", "canonical": true}]'::jsonb, '["Éplucher et découper les poires\nen petits morceaux.", "Émietter les sablés bretons.", "Dans une poêle, faire fondre du\nbeurre.", "Faire cuire les poires dans le\nsucre et le beurre.", "Dans une verrine, déposer les\nsablés émiettés,"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 16, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('c2a1522ee9b6', 'poulet pane maison', null, 'automne', 'décembre', 12, 1, 'lundi', 'déjeuner/dîner', 'salé', 'potimarron', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poulet-pane-maison.jpg', '[{"name": "1 escalope de poulet", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "2 c. à s. de chapelure", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Battre l’œuf dans un bol à\nl’aide d’une fourchette.\nSaler et poivrer.", "Verser l’œuf, la farine et la\nchapelure dans 3 assiettes\ncreuses différentes.", "Tremper l’escalope dans la\nfarine, puis dans", "Faire cuire l’escalope dans une\npoêle huilée."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2b6e0c524fe4', 'œufs cocottes au potimarron', null, 'automne', 'décembre', 12, 1, 'mardi', 'déjeuner/dîner', 'salé', 'potimarron', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/oeufs-cocottes-au-potimarron.jpg', '[{"name": "¼ de potimarron", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "2 c. à s. de crème épaisse", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper le\npotimarron en dés.", "Couper l’oignon finement.\nLe faire cuire dans une poêle\nhuilée. Ajouter le potimarron\ncuit, la crème et les herbes de\nProvence. Saler et poivrer.", "Verser la préparation dans 2\nramequins puis casser un œuf\nau-dessus de chacun. Saler et\npoivrer les œufs.", "Faire cuire au micro-ondes\npendant 1 min et 30 sec.\nœufs cocottes\nau potimarron"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('bb112a5a5888', 'spaghettis aux anchois, ail et persil', null, 'automne', 'décembre', 12, 1, 'mercredi', 'déjeuner/dîner', 'salé', 'potimarron', 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/spaghettis-aux-anchois-ail-et-persil.jpg', '[{"name": "1 à 2 poignées de spaghettis", "canonical": true}, {"name": "1 petite boîte d’anchois", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à c. de persil (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Cuire les spaghettis dans une\ncasserole d’eau bouillante salée\n(temps de cuisson indiqué sur\nle paquet).", "Peler et couper l’ail. Couper les\nanchois en petits morceaux.\nCouper", "Mélanger l’ail, l’huile, les\nanchois,"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1c61b4ddcc65', 'bananes plantain', null, 'automne', 'décembre', 12, 1, 'jeudi', 'déjeuner/dîner', 'salé', 'potimarron', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/bananes-plantain.jpg', '[{"name": "3 bananes plantain", "canonical": true}, {"name": "2 à 4 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 c. à c. de sauce piquante (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Découper les bananes\nen morceaux.", "Verser généreusement l’huile\nde tournesol dans une poêle\npuis", "Faire frire les bananes à feu\nmoyen pendant 10 min.", "Les déposer sur du papier\nabsorbant et assaisonner avec\ndu sel et du poivre.", "Servir avec une sauce piquante\n(en option).\nbananes plantain"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('22fcec4b648c', 'gratin de potimarron au micro-ondes', null, 'automne', 'décembre', 12, 1, 'vendredi', 'déjeuner/dîner', 'salé', 'potimarron', 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gratin-de-potimarron-au-micro-ondes.jpg', '[{"name": "½ potimarron", "canonical": true}, {"name": "2 c. à s. de crème épaisse", "canonical": true}, {"name": "2 poignées de fromage râpé", "canonical": true}, {"name": "1 c. à c. de miel (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver, éplucher et couper le\npotimarron en dés.", "Faire revenir le potimarron\navec un peu d’huile, le miel et\nles herbes de Provence dans la\nmême casserole. Saler et poivrer.", "Écraser les morceaux de\npotimarron en purée et ajouter la\ncrème. Mélanger.", "Disposer dans un plat à gratin,\nsaupoudrer d’emmental râpé.\nMettre au micro-ondes 5 min afin\nque"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 19, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0826f4c52b5b', 'nouilles aux légumes et œufs mollets', null, 'automne', 'décembre', 12, 2, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/nouilles-aux-legumes-et-oeufs-mollets.jpg', '[{"name": "4 c. à s. de nouilles de ton choix", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "2 champignons", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "2 c. à s. de sauce soja", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à c. de curry (EN OPTION)", "canonical": true}, {"name": "1 c. à c. de paprika (EN OPTION)", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Cuire les nouilles dans une\ncasserole d’eau bouillante salée\n(temps de cuisson indiqué sur\nle paquet).", "Laver et éplucher la carotte,\nl’oignon et l’ail.", "Avec un éplucheur, faire de fines\nlamelles de carotte (comme\ndes spaghettis). Couper en dés\nl’oignon, l’ail et les champignons.", "Dans une poêle huilée, faire cuire", "Poivrer, ajouter les épices et la\nsauce soja. Mélanger. Ajouter\nles nouilles.", "Cuire les œufs dans une casserole\nd’eau bouillante pendant 6 min.\nEnlever la coquille et les ajouter à\nla préparation.\nnouilles aux légumes\net œufs mollets"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('2176e2908aa7', 'tajine de poulet et olives vertes facile et parfumé', null, 'automne', 'décembre', 12, 2, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tajine-de-poulet-et-olives-vertes-facile-et-parfume.jpg', '[{"name": "4 pilons de poulet", "canonical": true}, {"name": "10 c. à s. de semoule", "canonical": true}, {"name": "1 poche d’olives vertes", "canonical": true}, {"name": "1 botte de coriandre (EN OPTION)", "canonical": true}, {"name": "1 botte de persil plat (EN OPTION)", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "3 gousses d’ail", "canonical": true}, {"name": "1 c. à c. de gingembre", "canonical": true}, {"name": "1 c. à c. de cumin", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans une poêle chaude huilée,\ncuire", "Couper en dés l’oignon et l’ail.\nLes ajouter au poulet. Ajouter\nle cumin, le gingembre et les\nolives. Verser de l’eau à hauteur\nd’aliments. Ajouter le persil et\nla coriandre. Saler et poivrer.\nMélanger et laisser mijoter 40\nmin avec un couvercle.", "Dans un saladier, verser un\npeu d’eau bouillante, d’huile\nd’olive et du sel sur", "Déposer le poulet et\nla semoule dans une\nassiette.\ntajine de poulet\net olives vertes facile\net parfumé\nUtilise une poêle avec\ndes rebords hauts. Tu peux aussi\nutiliser une casserole, en remuant\nrégulièrement la préparation."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5117c49a6a78', 'poisson à la sauce tomate', null, 'automne', 'décembre', 12, 2, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/poisson-a-la-sauce-tomate.jpg', '[{"name": "1 filet de poisson blanc", "canonical": true}, {"name": "½ oignon", "canonical": true}, {"name": "1 petite boîte de coulis de tomates", "canonical": true}, {"name": "1 c. à c. d’huile d’olive", "canonical": true}, {"name": "1 c. à c. d’herbes de Provence (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Faire cuire le poisson dans une\ncasserole d’eau bouillante salée\npendant 10 min.", "Peler et couper finement\nl’oignon. Le faire cuire dans une\npoêle huilée.", "Ajouter le coulis de tomates\net les herbes de Provence avec\nl’oignon. Saler et poivrer.", "Dans une assiette, verser le\ncoulis sur"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('928ee61bae84', 'risotto aux champignons et poireaux', null, 'automne', 'décembre', 12, 2, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/risotto-aux-champignons-et-poireaux.jpg', '[{"name": "1 verre de riz à risotto", "canonical": true}, {"name": "2 verres de lentilles vertes crues ou en conserve", "canonical": true}, {"name": "2 gros champignons de Paris", "canonical": true}, {"name": "1 poireau", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 bouillon de légumes en cube (POUR 1 GRAND VERRE D’EAU CHAUDE)", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. de parmesan râpé", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Cuire les lentilles dans une casserole\nd’eau bouillante salée environ 15\nmin (si en conserve, les égoutter).", "Peler et couper l’oignon, l’ail, les\nchampignons et le poireau.", "Dans une casserole huilée, faire\ncuire", "Mélanger le bouillon de légumes\nen cube dans un grand verre d’eau\nchaude. Ajouter un peu de bouillon,\nle poireau et les champignons dans\nla préparation précédente. Mélanger,\nle riz doit absorber le bouillon\net épaissir.", "Poursuivre la cuisson en versant le\nreste du bouillon progressivement\nen remuant pendant 20 min.\nAjouter le parmesan.", "2 ou 3 min avant la fin de la cuisson,\najouter les lentilles (garder la moitié\ndes lentilles pour la recette du\nvendredi). Saler et poivrer.\nrisotto\naux champignons\net poireaux"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('70e98d59c105', 'salade de lentilles', null, 'automne', 'décembre', 12, 2, 'vendredi', 'déjeuner/dîner léger', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/salade-de-lentilles.jpg', '[{"name": "1 verre de lentilles vertes (CUITES LA VEILLE)", "canonical": true}, {"name": "2 poignées de feuilles d’épinards", "canonical": true}, {"name": "1 échalote", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "½ pomme", "canonical": true}, {"name": "Quelques cerneaux de noix (EN OPTION)", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à c. de vinaigre balsamique", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, laver et couper\nl’échalote et", "Éplucher et laver la carotte. À\nl’aide d’un éplucheur, faire des\nlanières de carotte.", "Dans un saladier, mélanger\nles lentilles (cuites la veille),\nl’échalotte, la pomme, la\ncarotte et les épinards.", "Ajouter quelques cerneaux\nde noix coupés, de l’huile et\ndu vinaigre. Saler et poivrer.\nMélanger.\nsalade de lentilles\nPour éviter le gaspillage,\ntu peux garder l’autre moitié de la\npomme pour le dessert."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 20, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('4874611ecf70', 'poulet teriyaki et riz', null, 'automne', 'décembre', 12, 3, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/poulet-teriyaki-et-riz.jpg', '[{"name": "2 filets de poulet", "canonical": true}, {"name": "2 quenelles natures (POUR LA VERSION VÉGÉ)", "canonical": true}, {"name": "1 verre de riz", "canonical": true}, {"name": "1 c. à s. de gingembre", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "1 c. à s. de cassonade", "canonical": true}, {"name": "1 c. à c. de miel", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "½ verre de sauce teriyaki", "canonical": true}, {"name": "2 c. à s. de farine", "canonical": true}, {"name": "½ c. à s. de maïzena", "canonical": true}, {"name": "¼ d’ananas", "canonical": true}, {"name": "1 conserve de petit pois", "canonical": true}]'::jsonb, '["Cuire le riz dans une casserole d’eau\nbouillante pendant 8 min.", "Dans une casserole, faire chauffer", "Couper les filets de poulet en dés.\nMettre de la farine dessus. Pour la\nversion végé, cuire les quenelles\ncoupées dans une poêle huilée.", "Mélanger la maïzena et l’eau froide.\nVerser le mélange petit à petit dans\nla sauce teriyaki pour lier. Verser la\nsauce sur le poulet ou les quenelles.", "Dans une casserole huilée, faire\nrevenir l’ananas coupé\nen petits dés."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('0bfb1570cf7f', 'salade de pâtes et haricots rouges', null, 'automne', 'décembre', 12, 3, 'mardi', 'déjeuner/dîner léger', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/salade-de-pates-et-haricots-rouges.jpg', '[{"name": "1 verre de pâtes crues", "canonical": true}, {"name": "1 verre de haricots rouges cuits", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "1 poignée de mâche", "canonical": true}, {"name": "1 petite boîte de maïs", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. d’huile de colza", "canonical": true}, {"name": "1 c. à c. de vinaigre (DE TON CHOIX)", "canonical": true}, {"name": "1 c. à c. de sauce soja", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Cuire les pâtes dans une\ncasserole d’eau bouillante salée\n(temps de cuisson indiqué sur\nle paquet). Les égoutter puis les\npasser sous l’eau froide.", "Peler et couper l’oignon rouge.", "Mélanger les pâtes, les\nharicots rouges égouttés et\nrincés, la mâche, le maïs et\nl’oignon rouge.", "Faire la vinaigrette avec le\nvinaigre, les huiles, la sauce\nsoja et le poivre. Mélanger la\nvinaigrette à la préparation\nprécédente. Bien mélanger.\nsalade de pâtes\net haricots rouges\nL’huile de colza\ncontient des omégas 3, parfaits\npour une mémoire au top."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('bc3feb66b2dc', 'pissaladière express à la poêle', null, 'automne', 'décembre', 12, 3, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PISSALADIÈRE', null, null, '/assets/recipe_images/pexels/pissaladiere-express-a-la-poele.jpg', '[{"name": "9 c. à s. de lait", "canonical": true}, {"name": "10 c. à s. d’huile d’olive", "canonical": true}, {"name": "8 c. à s. de farine", "canonical": true}, {"name": "2 c. à s. d’huile de tournesol", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 sachet de levure chimique", "canonical": true}, {"name": "3 oignons", "canonical": true}, {"name": "1 boîte d’anchois", "canonical": true}, {"name": "olives noires", "canonical": true}, {"name": "1 c. à s. d’herbes de Provence", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Dans un saladier, mélanger le\nlait, l’huile et", "Peler, laver et couper les oignons\net les faire cuire dans une poêle\navec 1 c. à s. d’huile. Ajouter les\nherbes de Provence.\nSaler et poivrer.", "Dans une autre poêle huilée,\ndéposer", "Couvrir partiellement avec du\npapier aluminium et laisser cuire\n15 à 20 min à feu très doux.\npissaladière express\nà la poêle\nPour compléter ton\nrepas, tu peux réaliser une salade\navec la mâche que tu as utilisée\nla veille."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f073daa1169b', 'galettes de chou-fleur', null, 'automne', 'décembre', 12, 3, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/galettes-de-chou-fleur.jpg', '[{"name": "1 petit chou-fleur", "canonical": true}, {"name": "3 c. à s. de farine de blé", "canonical": true}, {"name": "3 œufs", "canonical": true}, {"name": "1 gousse d’ail", "canonical": true}, {"name": "2 c. à s. d’huile d’olive", "canonical": true}, {"name": "1 c. à s. de persil (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Laver et couper en morceaux le\nchou-fleur. Couper l’ail en dés.", "Dans une casserole d’eau\nbouillante salée, faire cuire les\nmorceaux de chou-fleur pendant\n20 min. Une fois qu’ils sont cuits,", "Dans un bol, écraser le chou-fleur\nà la fourchette. Ajouter les œufs,\nl’ail coupé, le persil et la farine.\nSaler et poivrer. Mélanger à la\nfourchette.", "Dans une poêle huilée chaude,\ndéposer des cuillerées de pâte et\naplatir pour former des galettes.\nFaire cuire environ 5 min sur\nchaque face.\ngalettes de chou-fleur\nL’ail a de\nnombreuses propriétés, dont celle\nd''éloigner"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('a4e35fcadcd8', 'nems de chou frisé au tofu', null, 'automne', 'décembre', 12, 3, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/nems-de-chou-frise-au-tofu.jpg', '[{"name": "½ chou frisé", "canonical": true}, {"name": "1 plaquette de tofu", "canonical": true}, {"name": "1 c. à s. de sauce soja", "canonical": true}, {"name": "3 c. à s. de vermicelles de riz", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "½ oignon rouge", "canonical": true}, {"name": "Poivre", "canonical": true}]'::jsonb, '["Laver le chou et prendre les plus\ngrandes feuilles autour. Faire cuire\nles feuilles dans une casserole\nd’eau bouillante salée pendant\n5 min.", "Cuire les vermicelles dans une\ndeuxième casserole d’eau\nbouillante salée (temps indiqué\nsur le paquet).", "Peler et couper finement l’oignon\nrouge. Le faire cuire dans une\npoêle avec de l’huile d’olive.", "Émietter le tofu et l’ajouter dans\nla poêle. Ajouter les vermicelles\ncuits puis la sauce soja. Poivrer.", "Garnir chaque feuille de chou\navec la préparation et les\nenrouler de sorte à former\ndes nems.\nnems de chou frisé\nau tofu\nGarde le reste du chou\nfrisé pour en faire une potée\n(recette du lundi pour la semaine 4\ndu mois de décembre)."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 21, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('5c0e41ece53c', 'potée de chou frisé et pommes de terre', null, 'automne', 'décembre', 12, 4, 'lundi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/potee-de-chou-frise-et-pommes-de-terre.jpg', '[{"name": "½ chou frisé", "canonical": true}, {"name": "2 grosses pommes de terre", "canonical": true}, {"name": "2 carottes", "canonical": true}, {"name": "1 c. à s. d’huile d’olive", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Effeuiller et laver le chou\nfrisé. Couper les feuilles\ngrossièrement.", "Éplucher, laver et couper en\n4", "Dans une grande casserole\nd’eau bouillante salée, mettre"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e1dfd30e3033', 'couscous express', null, 'automne', 'décembre', 12, 4, 'mardi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/couscous-express.jpg', '[{"name": "½ verre de semoule", "canonical": true}, {"name": "1 petite boîte de pois chiches", "canonical": true}, {"name": "1 carotte", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "1 c. à s. de raisins secs", "canonical": true}, {"name": "½ c. à c. de Ras el Hanout", "canonical": true}, {"name": "½ cuillère de cumin", "canonical": true}, {"name": "1 filet d’huile d’olive", "canonical": true}, {"name": "1 c. à c. de muscade", "canonical": true}, {"name": "Quelques feuilles de coriandre (EN OPTION)", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, couper puis laver la\ncarotte et", "Dans un saladier, verser un peu\nd’eau bouillante, d’huile d’olive,\nde muscade, de coriandre, de\nRas el Hanout, de cumin et du\nsel sur", "Mélanger la semoule avec les pois\nchiches, les légumes cuits et les\nraisins secs. Saler et poivrer.\ncouscous express"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('90605b431462', 'tartiflette au micro-ondes', null, 'automne', 'décembre', 12, 4, 'mercredi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/tartiflette-au-micro-ondes.jpg', '[{"name": "½ de reblochon", "canonical": true}, {"name": "1 petite barquette de lardons", "canonical": true}, {"name": "1 grosse pomme de terre", "canonical": true}, {"name": "1 oignon", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher et couper la pomme\nde terre en dés.", "Peler et couper l’oignon.", "Dans une poêle chaude, faire\ncuire", "Dans un plat à gratin et\npassant au micro-ondes,\nmettre", "Mettre la tartiflette 7 min\nau micro-ondes afin que le\nfromage fonde.\ntartiflette\nau micro-ondes\nRecette conviviale à\npartager entre amis, avec une\nsalade (mâche, endives…)."]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('3504df6c9d6a', 'terrine de thon au micro-ondes', null, 'automne', 'décembre', 12, 4, 'jeudi', 'déjeuner/dîner', 'salé', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/terrine-de-thon-au-micro-ondes.jpg', '[{"name": "1 petite boîte de thon", "canonical": true}, {"name": "½ petit pot de crème fraîche", "canonical": true}, {"name": "1 c. à s. de concentré de tomates", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "1 citron", "canonical": true}, {"name": "1 c. à s. de ciboulette (EN OPTION)", "canonical": true}, {"name": "Une noisette de beurre (POUR LES RAMEQUINS)", "canonical": true}, {"name": "1 salade", "canonical": true}]'::jsonb, '["Presser le citron.", "Dans un saladier, ajouter tous\nles ingrédients (sauf le beurre).\nMélanger la préparation.", "Beurre les ramequins et les\nremplir avec la préparation.", "Enfourner au micro-ondes\npendant 12 min.", "Laisser refroidir et servir avec\nune salade et sa vinaigrette.\nterrine de thon au\nmicro-ondes\nPour"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('e0d79b0a9458', 'omelette de pommes de terre et champignons', null, 'automne', 'décembre', 12, 4, 'vendredi', 'déjeuner/dîner', 'salé', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/omelette-de-pommes-de-terre-et-champignons.jpg', '[{"name": "1 pomme de terre", "canonical": true}, {"name": "2 champignons", "canonical": true}, {"name": "2 œufs", "canonical": true}, {"name": "1 c. à c. de persil frais", "canonical": true}, {"name": "1 c. à s. d’huile de tournesol", "canonical": true}, {"name": "Sel et poivre", "canonical": true}]'::jsonb, '["Éplucher, laver et couper la\npomme de terre en dés. La\nfaire cuire pendant 10 min\ndans une casserole d’eau\nbouillante salée.", "Laver et couper les\nchampignons.", "Dans un bol, casser et fouetter", "Faire cuire dans une poêle\nhuilée"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 22, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('6343d999ea2e', 'cookies aux lentilles à la poêle', null, 'automne', 'décembre', 12, null, null, 'dessert', 'sucré', null, 'POUR 10 COOKIES', null, null, '/assets/recipe_images/pexels/cookies-aux-lentilles-a-la-poele.jpg', '[{"name": "3 c. à s. de lentilles corail crues", "canonical": true}, {"name": "10 c. à s. de farine", "canonical": true}, {"name": "5 c. à s. de sucre", "canonical": true}, {"name": "1/3 d’une plaquette de beurre", "canonical": true}, {"name": "2 c. à s. de flocons d’avoine", "canonical": true}, {"name": "5 c. à s. de pépites de chocolat (COUPER DES PETITS MORCEAUX DE LA TABLETTE UTILISÉE POUR LA FONDUE AU CHOCOLAT)", "canonical": true}, {"name": "1 œuf", "canonical": true}, {"name": "½ c. à c. de levure chimique", "canonical": true}]'::jsonb, '["Cuire les lentilles dans une\ncasserole d’eau bouillante\npendant 10 min.", "Dans un saladier, mélanger à la\nmain", "Ajouter l’œuf cassé, les flocons\nd’avoine et les lentilles égouttées\net refroidies. Mélanger à la main\nafin de former une boule non\ncollante (ajouter de la farine\nsi besoin). Ajouter les pépites\nde chocolat.", "Former des boules. Les aplatir\npour former des cookies.", "Mettre du papier cuisson au\nfond d’une poêle et déposer les\ncookies. Laisser cuire à feu doux\npendant 10 à 15 min"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('71f37a94c4e8', 'fondue au chocolat', null, 'automne', 'décembre', 12, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/fondue-au-chocolat.jpg', '[{"name": "4 carreaux de chocolats (NOIR OU AU LAIT)", "canonical": true}, {"name": "1 banane", "canonical": true}, {"name": "1 kiwi", "canonical": true}, {"name": "1 pomme", "canonical": true}]'::jsonb, '["Faire fondre le chocolat au\nmicro-ondes ou au bain marie\n(placer le chocolat dans un\nrécipient au-dessus d’une\ncasserole d’eau bouillante).", "Laver et couper en cubes ou en\ntranches", "Déguster les fruits en les\nplongeant dans le chocolat.\nfondue au chocolat\n2\nSi les kiwis sont bio,\nla peau se mange. Au-delà de sa\ntexture qui peut être désagréable,\nla peau du kiwi est riche en\nvitamines et minéraux !"]'::jsonb, null, true, true, 'crous', 'Calendrier recettes_automne.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('97ac34e24bb7', 'granola maison', null, 'automne', 'décembre', 12, null, null, 'petit déjeuner', 'sucré', null, 'POUR 1 PERSONNE', null, null, '/assets/recipe_images/pexels/granola-maison.jpg', '[{"name": "½ tasse de flocons d’avoine", "canonical": true}, {"name": "1 c. à s. de d’amandes coupées en petits morceaux", "canonical": true}, {"name": "1 c. à s. de raisins secs (OU CRANBERRIES)", "canonical": true}, {"name": "1 c. à s. de graines (SÉSAME, TOURNESOL, CHIA, …)", "canonical": true}, {"name": "1 c. à c. de miel", "canonical": true}, {"name": "1 c. à c. de cannelle", "canonical": true}]'::jsonb, '["Dans une poêle à feu moyen,\nfaire cuire et dorer", "Ajouter le miel et la cannelle.\nMélanger.", "Laisser refroidir et ajouter les\nraisins secs (ou cranberries).", "Servir avec un fromage blanc, un\nyaourt ou du lait.\ngranola maison\nTu peux en préparer\nd’avance en multipliant\nles quantités."]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('f218fa64eb87', 'gâteau aux pommes sans four', null, 'automne', 'décembre', 12, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/gateau-aux-pommes-sans-four.jpg', '[{"name": "1 verre de crème", "canonical": true}, {"name": "2 pommes", "canonical": true}, {"name": "7 c. à s. de farine", "canonical": true}, {"name": "7 c. à s. de sucre", "canonical": true}, {"name": "½ sachet de levure", "canonical": true}, {"name": "2 œufs", "canonical": true}]'::jsonb, '["Découper les pommes en\nfines lamelles.", "Dans un saladier, mélanger la\nfarine,", "Dans une poêle recouverte\nde papier cuisson (pour éviter\nque", "Recouvrir avec le reste de la\npréparation.", "Laisser cuire à feu moyen\npendant 10 min", "Retourner le gâteau et cuire\nl’autre face pendant 1 min.\ngâteau aux pommes\nsans four\n1"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified'),
('1fc5f02226bf', 'rouleaux de printemps aux fruits', null, 'automne', 'décembre', 12, null, null, 'dessert', 'sucré', null, 'POUR 2 PERSONNES', null, null, '/assets/recipe_images/pexels/rouleaux-de-printemps-aux-fruits.jpg', '[{"name": "4 feuilles de riz", "canonical": true}, {"name": "1 banane", "canonical": true}, {"name": "1 kiwi", "canonical": true}, {"name": "1 grenade", "canonical": true}, {"name": "Quelques feuilles de menthe fraîche (EN OPTION)", "canonical": true}]'::jsonb, '["Mettre les feuilles de riz dans\nune assiette creuse avec\nde l’eau.", "Couper la grenade en deux et\nenlever les grains.", "Couper le kiwi et la banane\nen morceaux. Mélanger les\nfruits avec quelques feuilles\nde menthe.", "À l’aide d’une cuillère, disposer", "Replier le bas de la feuille\nsur les fruits, puis enrouler\nun tour de plus. Replier les\ncôtés vers l’intérieur et finir\nd’enrouler la feuille de riz, de\nmanière à former un rouleau\nde printemps.\nrouleaux de\nprintemps aux fruits\n4"]'::jsonb, null, false, true, 'crous', 'Calendrier recettes_automne.pdf', 23, '{}'::text[], '{}'::text[], '{}'::text[], 'verified')
